SELECT 'moj-all-verified-judgments-review-002-chunk-086' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0bc8eeb2-72cb-572b-8f02-2490b08abd16","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -سيارة -فسخ البيع لوجود عيب -سماع الدعوى غيابي ا -مين االستظهار -احلكم حضوري وفق ا للنظام -احلكم بسداد املدعى عليه ثمن املبيع واستالم السيارة .","document_number":"34309635","case_number":"33540310","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":"الدائرة احلقوقية األولى يف محكمة الاستئناف مبنطقة تبوك على","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/30","year":"1434","subject":"بيع -عقد -سيارة -فسخ البيع لوجود عيب -سماع الدعوى غيابي ا -مين االستظهار -احلكم حضوري وفق ا للنظام -احلكم بسداد املدعى عليه ثمن املبيع واستالم السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/30 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34309635 :‬‬\n                    ‫َر ْق ُم الدعوى‪33540310 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 331583484‬تاريخه‪1435/1/11 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــد ‪ -‬ســيارة ‪ -‬فســخ البيــع لوجــود عيــب ‪ -‬ســماع الدعــوى‬\n‫غيابي ـ ًا ‪ -‬ميــن االســتظهار ‪ -‬احلكــم حضــوري وفق ـ ًا للنظــام ‪ -‬احلكــم‬\n                 ‫بســداد املدعــى عليــه ثمــن املبيــع واســتالم الســيارة ‪.‬‬\n\n\n\n\n‫‪ -1‬مــا ذكــره صاحــب املقنــع ‪-‬رحمــه اهلل‪ -‬مــن قولــه‪« :‬وإن ســكت املدعــى‬\n‫عليــه فلــم يقــر ولــم ينكــر‪ ،‬قــال لــه القاضــي‪ :‬إن أجبــت وإال جعلتــك‬\n‫ال‪ ،‬وقضيــت عليــك» املقنــع مــع الشــرح الكبيــر واإلنصــاف‬           ‫نــاك ً‬\n                                                                  ‫(‪.)28/446‬‬\n‫‪ -2‬قــال املــرداوي ‪ -‬رحمــه اهلل ‪ -‬وهــو املذهــب قــال صاحــب الشــرح‬\n              ‫الكبيــر‪ :‬ألنــه نــاكل عمــا توجــب عليــه اجلــواب فيــه‪.‬‬\n‫‪ -3‬املــواد (‪/17‬ج) و(‪ )55‬و(‪ )176‬و(‪ )178‬مــن نظــام املرافعــات الشــرعية‬\n                                                        ‫ولوائحــه التنفيذيــة‪.‬‬\n                                    ‫‪ -4‬املادة (‪ )2/103‬من نظام املرافعات ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن الشــركة املدعــى عليهــا ســيارة جديــدة‬\n‫موصوفــة يف دعــواه وســلمها ثمنهــا وبعــد اســتالم الســيارة واســتخدمها‬\n‫الحــظ وجــود عيــوب يف الســيارة مفصلــة يف الدعــوى فطلــب مــن املدعــى‬\n\n                                                                                  ‫‪124‬‬\n\f      ‫عليهــا إصالحهــا ولــم تتجــاوب يف ذلــك؛ لــذا طلب احلكم على الشــركة‬\n      ‫املدعــى عليهــا باســتالم ســيارتهم منــه وتســليمه قيمتهــا ‪ ،‬لــم يحضــر‬\n      ‫مــن ميثــل املدعــى عليهــا مــع تبلــغ منســوبيها باحلضــور فقــررت احملكمــة‬\n      ‫مواصلــة الســير يف الدعــوى غيابيـ ًا ‪ ،‬مت فحــص الســيارة مــن قبــل اخلبراء‬\n      ‫فتبــن وجــود عــدد مــن األعطــال الفنيــة فيهــا ‪ ،‬قــررت احملكمــة توجيــه‬\n      ‫ميــن االســتظهار للمدعــى عليــه علــى أن األعطــال املذكــورة يف تقريــر‬\n      ‫اخلبــراء موجــودة يف الســيارة منــذ أن اســتلمها مــن الشــركة املدعــى‬\n      ‫عليهــا ولــم تكــن بســبب ســوء اســتخدامه فــأدى اليمــن طبــق مــا طلــب‬\n      ‫منــه‪ ،‬قضــت احملكمــة حضوريــا بثبوت صحة دعــوى املدعي وحكمت‬\n      ‫علــى الشــركة املدعــى عليهــا أن تســتلم ســيارتها مــن املدعــي وأن تســلم‬\n      ‫املدعــي ثمــن الســيارة ‪ ،‬عارضــت املدعــى عليهــا علــى احلكم‪،‬قــررت‬\n                     ‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بتبــوك املكلــف برقــم ‪ 33540310‬وتاريــخ ‪ 1433/08/21‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331583484‬وتاريــخ ‪ 1433/08/21‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n      ‫وفيهــا حضــر ‪ )........( ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ، )........‬ولــم يحضــر مــن ميثــل الشــركة املدعــى عليهــا الشــركة‬\n      ‫(‪ )........‬للســيارات وقــد وردنــا مــن محضــر اخلصــوم اإلفــادة موقعــة مــن‬\n      ‫شــخص لــم تبــن صفتــه وكذلــك لــم يوقــع عليهــا محضــر اخلصــوم لــذا‬\n\n‫‪125‬‬\n\f‫رفعــت اجللســة إلبــاغ املدعــى عليهــا مــرة أخــرى ‪ .‬ويف جلس ـ ٍة أخــرى‬\n‫حضــر املدعــي ولــم يحضــر مــن ميثــل الشــركة املدعــى عليهــا‪ ،‬وقــد‬\n‫وردنــا مــن محضــر اخلصــوم بهــذه احملكمــة اإلفــادة املتضمنــة اســتالم‬\n‫مديــر الفــرع للشــركة ألصــل ورقــة التبليــغ وعليهــا اســمه وتوقيعــه ؛ لــذا‬\n‫ُرفعــت اجللســة إلبــاغ املدعــى عليهــا مــرة أخــرى ‪ .‬ويف جلس ـ ٍة أخــرى‬\n‫حضــر املدعــي واملــدون هويتــه ســابق ًا ولــم يحضــر مــن ميثــل الشــركة‬\n‫املدعــى عليهــا وقــد وردنــا مــن قســم محضــري اخلصــوم اإلفــادة بتبليــغ‬\n‫املوظــف (‪ )........‬وصفتــه معقــب الشــركة وتوقيــع منســوب إليــه علــى‬\n‫أصــل ورقــة التبليــغ والســاعة اآلن الثامنــة وخمســون دقيقــة ولــم يحضــر‬\n‫وبنــاء علــى الفقــرة «ج» مــن املــادة الســابعة عشــرة واملــادة اخلامســة‬\n‫واخلمســون مــن نظــام املرافعــات قــررت ســماع الدعــوى غيابي ـ ًا فقــرر‬\n‫ا فيهــا أنــه بتاريــخ ‪1433/4/7‬ه ـ اشــتريت مــن‬         ‫املدعــي دعــواه قائ ـ ً‬\n‫الشــركة املدعــى عليهــا الشــركة (‪ )........‬للســيارات ســيارة مــن نــوع‬\n‫(‪( )........‬صنعــت يف عــام (‪ )........‬وقــد اشــتريتها وهــي جديــدة لــم‬\n‫تســتخدم مــن قبــل وســجلت باســمي مببلــغ إجمالــي قــدرة مائــة وســتة‬\n‫وثالثــون ألــف ريــال وبعــد اســتلمت الســيارة واســتخدمتها ال حظــت أن‬\n‫هنــاك صــوت مــن (اجلرابوكــس) واهتــزاز باملكينــة ودخــول الهــواء‬\n‫عبــر النوافــذ يف الســرعات اليســيرة ثــم رجعــت إلــى الشــركة مباشــرة‬\n‫يف صبــاح يــوم الســبت ‪1433/4/10‬ه ـ واطلعتهــم علــى املشــكلة فقــال‬\n‫لــي مديــر الشــركة وكذلــك مديــر الصيانــة أن الصــوت الــذي يف القيــر‬\n‫أو اجلرابوكــس صــوت طبيعــي يذهــب مــع االســتخدام والوقــت وقــاال‬\n‫لــي أيضــا وصــوت الهــواء نحيلــك إلــى قســم الســمكرة وقــام العامــل‬\n‫بشــد الربــات وقــال لــي إن هنــاك مشــكلة يف جــرم الســيارة وأنهــا غيــر‬\n\n\n                                                                                     ‫‪126‬‬\n\f      ‫متوازنــة ولــو فعلــت معــك مــا فعلــت لــن يذهــب صــوت الهــواء ألن هنــاك‬\n      ‫عــدم تــوازن يف هيــكل الســيارة فرجعــت إلــى مديــر الفــرع وأخبرتــه‬\n      ‫بذلــك وقــال لــي دع عنــك مــا قالــه هــذا العامــل وســوف نصلــح لــك مــا‬\n      ‫تريــد بعــد أســبوع وقبلــت كالمــه وخرجــت ثــم عــدت إليــه بعــد أســبوع‬\n      ‫وأخــذ مياطلنــي ويف كل مــرة يأتــي لــي بعــذر ثــم ملــا رأيــت موقــف‬\n      ‫الشــركة املدعــى عليهــا تقدمــت بدعــوى ضدهــم لــدى فــرع وزارة‬\n      ‫التجــارة والصناعــة بتبــوك وذلــك يف مطلــع شــهر جمــادى الثانيــة مــن عــام‬\n      ‫‪1433‬ه ـ ثــم بعــد أن اطلعــوا علــى شــكواي قــام مديــر عــام فــرع وزارة‬\n      ‫التجــارة والصناعــة بتبــوك بالكتابــة إلــى مديــر املعهــد الصناعــي‬\n      ‫الثانــوي بتبــوك للفحــص علــى ســيارتي هــذه وبعــد الكشــف عليهــا‬\n      ‫أجــاب مديــر املعهــد الصناعــي الثانــوي بالــرد علــى ســعادة مديــر عــام‬\n      ‫فــرع وزارة التجــارة بخطابــه رقــم ‪ 428‬يف ‪1433/7/28‬ه ـ واملتضمــن مــا‬\n      ‫يلــي‪( :‬ســعادة مديــر عــام فــرع وزارة التجــارة والصناعــة مبنطقــة تبــوك‬\n      ‫ســلمه اهلل الســام عليكــم ورحمــة اهلل وبركاتــه ‪ ،‬إشــارة إلــى خطــاب‬\n      ‫ســعادتكم رقــم ‪ 641/1538‬وتاريــخ ‪1433/7/26‬ه ـ واملتضمــن‬\n      ‫الكشــف علــى الســيارة (‪ )........‬لصاحبهــا ‪ ....‬والــذي يشــكو مــن وجــود‬\n      ‫خلــل بالســيارة ‪ .‬عليــه نفيدكــم أنــه أثنــاء إجــراء الفحــص علــى الســيارة‬\n      ‫أتضــح مــا يلــي‪ -1 :‬يوجــد صــوت يف اجليــر بكــس أثنــاء التعشــيق وتبديــل‬\n      ‫عصــا اجليــر ‪ -2 .‬يوجــد بهــا اهتــزاز قــوي علــى احملــرك أثنــاء التعشــيق ‪.‬‬\n      ‫‪ -3‬يوجــد صــوت هــواء أثنــاء الســير علــى الطريــق ‪ -4 .‬يوجــد حــذف يف‬\n      ‫الدركســون جهــة اليمــن أثنــاء الســير ‪ .‬وتقبلــوا‪ ......‬فقــام فــرع وزارة‬\n      ‫التجــارة مبخاطبــة فــرع الشــركة حلــل املوضــوع بشــكل ودي فلــم‬\n      ‫يتجاوبــوا معــه وأرشــدني فــرع وزارة التجــارة بالتقــدم للمحكمــة‬\n\n\n‫‪127‬‬\n\f‫فتقدمــت بدعــواي هــذه يف ‪1433/8/21‬ه ـ وعليــه فــإن هــذه األعطــال‬\n‫التــي ذكرتهــا وذكرهــا مديــر املعهــد الصناعــي الثانــوي يف خطابــه‬\n‫املوجــه لفــرع وزارة التجــارة هــي عيــوب مصنعيــة وال عالقــة لــي بهــا وهــي‬\n‫موجــودة يف الســيارة قبــل اســتالمها ‪ ،‬مــع العلــم أن الشــركة قــد ضمــت‬\n‫لــي عندمــا اشــتريتها منهــم القيــر ( اجلربوكــس) واملاكينــة ؛ لــذا أطلــب‬\n‫احلكــم علــى الشــركة املدعــى عليهــا باســتالم ســيارتهم منــي وتســليمي‬\n‫قيمتهــا وقدرهــا مائــة وســتة وثالثــون ألــف ريــال حــا ًال ‪ ،‬هــذه دعــواي ‪.‬‬\n‫وقــررت الكتابــة إلــى ســعادة مديــر املعهــد الصناعــي الثانــوي بتبــوك‬\n‫لســؤاله ‪ :‬هــل باإلمــكان اإلفــادة عــن تلــك العيــوب التــي ذكرهــا يف‬\n‫خطابــه املوجــه لفــرع وزارة التجــارة أهــي عيــوب مصنعيــة أم بســبب‬\n‫اســتخدام املدعــى ‪ ،‬وهــل باإلمــكان إيضــاح عــدد الكيلــوات التــي‬\n‫قطعتهــا الســيارة وقــت الكشــف عليهــا وبيــان األعضــاء الذيــن قامــوا‬\n‫ورفعــت اجللســة لذلــك ‪ .‬ويف جلس ـ ٍة أخــرى‬    ‫بالكشــف علــى الســيارة ‪ُ .‬‬\n‫حضر املدعي ‪ ....‬واملدون هويته ســابق ًا ‪ ،‬ولم يحضر من ميثل الشــركة‬\n‫املدعــى عليهــا الشــركة (‪ )........‬لبيــع الســيارات بصفــة شــرعية ‪ ،‬وقــد‬\n‫وردتنــا اإلفــادة رقــم ‪ 341939644‬يف ‪1434/8/10‬هـ واملتضمنة اســتالم‬\n‫محاســب الشــركة (‪ )........‬خلطــاب التبليــغ وعليهــا اســمه وتوقيعــه ‪ .‬لــذا‬\n‫ُرفعــت اجللســة للتأمــل والدراســة ‪ .‬ويف جلس ـ ٍة أخــرى حضــر املدعــي‬\n‫(‪ )........‬واملــدون هويتــه ســابقاً‪ ،‬ولــم يحضــر مــن ميثــل الشــركة املدعــى‬\n‫عليهــا الشــركة (‪ )........‬لبيــع الســيارات بصفــة شــرعية‪ .‬وقــد وردتنــا‬\n‫اإلفــادة مــن محضــر اخلصــوم بهــذه احملكمــة برقــم ‪ 342022678‬يف‬\n‫‪1434/8/22‬ه ـ واملتضمنــة اســتالم مديــر الصنــدوق بالشــركة املدعــى‬\n‫عليهــا ‪ ....‬ألصــل ورقــة التبليــغ مبوعــد هــذا اليــوم وعليهــا اســمه وتوقيــع‬\n\n\n                                                                                      ‫‪128‬‬\n\f      ‫منســوب إليــه‪ .‬وكنــا قــد كتبنــا إلــى ســعادة مديــر فــرع وزارة التجــارة‬\n      ‫والصناعــة بتبــوك لإلفــادة عمــا ذكــره املدعــي بكتابنــا رقــم‬\n      ‫‪ 341440483‬يف ‪1434/6/18‬هـ فوردني منه اجلواب برقم ‪641/1618‬‬\n      ‫يف ‪1434/7/3‬ه ـ واملتضمــن‪( :‬نفيدكــم بأن (‪ )........‬تقدم لنا بشــكوى‬\n      ‫ضــد الشــركة (‪ )........‬للســيارات يف ‪1433/6/21‬هــ‪ ،‬يشــكو مــن‬\n      ‫وجــود أعطــال فنيــة يف ســيارته التــي اشــتراها منهــم‪ ،‬ومت مخاطبــة‬\n      ‫الشــركة للعمــل علــى إصــاح الســيارة‪ ،‬وقــد تعهدت الشــركة بإصالح‬\n      ‫تلــك األعطــال‪ ،‬وطلــب قطــع الغيــار‪ ،‬لكــن الشــركة لــم تــف بوعدهــا‪،‬‬\n      ‫وبعــد ذلــك مت حتويــل الســيارة للمعهــد املهنــي الصناعــي بتبــوك؛ لفحــص‬\n      ‫الســيارة وإثبــات وجــود األعطــال املصنعيــة‪ ،‬وبعــد صــدور التقريــر مت‬\n      ‫إلــزام الشــركة بإدخــال الســيارة للصيانــة؛ إلصــاح األعطــال الــواردة‬\n      ‫يف التقريــر‪ ،‬وبعــد أســبوع طلبــوا مــن املذكــور اســتالم ســيارته ولــم يتــم‬\n      ‫إصــاح أي عطــل فنــي بالســيارة وال زالــت الشــركة متاطــل يف إصــاح‬\n      ‫الســيارة‪ ) ...‬انتهــى‪ .‬وباالطــاع علــى املرفقــات وجــدت ورقــة مفادهــا‪( :‬‬\n      ‫يف يــوم األربعــاء ‪1434/6/7‬ه ـ وبنــاء علــى الشــكوى املرفوعــة مــن األخ‬\n      ‫(‪ )........‬إلــى وزارة التجــارة مت الشــخوص علــى مقــر الوكالــة الشــركة‬\n      ‫(‪ )........‬للســيارات بتبــوك الســاعة التاســعة والنصــف ومت مقابلــة مديــر‬\n      ‫الفــرع (‪ )........‬هويتــه‪ )........( :‬ومواجهتــه بالتقريــر الفنــي الصــادر مــن‬\n      ‫املعهــد املهنــي الصناعــي رقــم ‪ 428‬يف ‪1433/7/28‬ه ـ البنــد األول‪:‬‬\n      ‫صــوت القيــر‪ ،‬وأفــاد أنــه حتــت االســتدعاء ولــم يتــم عملــه يف الســيارة‬\n      ‫وســوف يتــم إجــراء اخلدمــة الالزمــة أمــا باقــي البنــود فتخضــع الســيارة‬\n      ‫للخدمــة والصيانــة عنــد الوكالــة حتــت الضمــان ويســلم ســيارة بديلــة‪.‬‬\n      ‫ممثــل وزارة التجــارة (‪ )........‬توقيــع منســوب إليــه ومديــر الفــرع (‪)........‬‬\n\n\n‫‪129‬‬\n\f‫وتوقيــع منســوب إليــه‪ ) .‬انتهــى وقــد وردنــي مــن مديــر املعهــد املهنــي‬\n‫الصناعــي اجلــواب برقــم ‪ 187‬يف ‪1434/7/2‬ه ـ وبرفقــه اإلفــادة مــن‬\n‫رئيــس قســم احملــركات واملتضمنــة أنــه ال ميكــن حتديــد هــل األعطــال‬\n‫مصنعيــة أم بســبب ســوء االســتخدام‪ ،‬وأنــه ال ميكــن حتديــد مــن‬\n‫املســؤول عــن وجــود هــذه األعطــال‪ ،‬وال يحتفــظ املعهــد بأرقــام‬\n‫الكيلــوات التــي قطعتهــا الســيارة أثنــاء الكشــف عليهــا‪ ،‬أمــا األعضــاء‬\n‫الذيــن قامــوا بالكشــف على الســيارة فهــم‪،)........( ،)........( ،)........( :‬‬\n‫(‪ )........‬انتهــى‪ .‬ومرفــق بــه التقريــر الصــادر منهــم‪ .‬فســألت املدعــي عمــا‬\n‫يفيــد متلكــه لهــذه الســيارة فأبــرز أصــل االســتمارة وتتضمــن اســم‬\n‫املدعــي (‪ )........‬ورقــم ســجله املدنــي (‪ )........‬وأنــه ميلــك الســيارة التــي مــن‬\n‫نــوع (‪)........‬صنعــت عــام ‪2012‬م ورقــم لوحتهــا (‪ )........‬وأرفــق باملعاملــة‬\n‫صــورة مصدقــة منهــا‪ ،‬وعليــه وبعــد التأمــل والدراســة وبنــاء علــى مــا جــاء‬\n‫يف دعــوى املدعــي ومــا جــاء يف إفــادة مديــر املعهــد املهنــي الصناعــي مــن‬\n‫وجــود هــذه األعطــال الفنيــة يف محــرك الســيارة واالهتــزاز القــوي يف‬\n‫احملــرك أثنــاء التعشــيق وغيرهــا ممــا جــاء يف إفادتــه يف هــذا الوقــت‬\n‫الوجيــز مــن شــراء املدعــي للســيارة الشــركة املدعــى عليهــا ولــم جتــر‬\n‫العــادة مبثــل ذلــك‪ ،‬وبنــاء علــى مــا جــاء يف إفــادة مديــر فــرع وزارة التجارة‬\n‫مــن أن املدعــي تقــدم إليهــم بشــكواه ضــد املدعــى عليهــا بعــد مــرور‬\n‫شــهرين مــن شــراء الســيارة منهــا وأن الشــركة تعهــدت بإصــاح‬\n‫األعطــال احلاصلــة يف الســيارة وأدخلتهــا عندهــا وأخرجتهــا مــن غيــر أن‬\n‫تنهــي هــذه األعطــال وملــا جــاء يف اإلفــادة التــي أرفقهــا ســعادة مديــر فــرع‬\n‫وزارة التجــارة مــن أنــه خــرج إلــى الشــركة منــدوب مــن الفــرع وقابــل‬\n‫مديــر فــرع الشــركة املدعــى عليهــا وعــرض عليــه هــذه اإلشــكاالت‬\n\n\n                                                                                            ‫‪130‬‬\n\f      ‫التــي أثبتهــا التقريــر الفنــي املشــار إليــه بعاليــه وأقــر بهــا مديــر الشــركة‬\n      ‫املدعــى عليهــا وتعهــد بإصالحهــا وذكــر أنهــا حتــت الضمــان ثــم لــم‬\n      ‫يجــر أي شــيء حيالهــا‪ ،‬وألنــه مت إبــاغ منســوبي الشــركة املدعــى‬\n      ‫عليهــا عــدة مــرات مبواعيــد متفرقــة ولــم يحضــر مــن ميثلهــا ولــم يقــدم‬\n      ‫دفاعــه للمحكمــة بعــد علمهــم بهــذه الدعــوى وملــا ذكــره صاحــب املقنع‬\n      ‫‪-‬رحمــه اهلل‪ -‬مــن قولــه‪« :‬وإن ســكت املدعــى عليــه فلــم يقــر ولــم ينكــر‬\n      ‫قــال لــه القاضــي‪ :‬إن أجبــت وإال جعلتــك نــاكال وقضيــت عليــك‪ .‬قــال‬\n      ‫املــرداوي‪ -‬رحمــه اهلل‪ :-‬وهــو املذهــب‪ .‬قــال صاحــب الشــرح الكبيــر ‪-‬‬\n      ‫رحمــه اهلل‪ -‬ألنــه نــاكل عمــا توجــه عليــه اجلــواب فيــه»‪ .‬انظــر املقنــع مــع‬\n      ‫الشــرح الكبيــر واإلنصــاف (‪ )28/446‬انتهــى‪ .‬وملــا جــاء يف الالئحــة‬\n      ‫الثانيــة مــن املــادة الثالثــة بعــد املائــة مــن نظــام املرافعــات مــا نصــه‪« :‬إذا‬\n      ‫تخلــف اخلصــم عــن احلضــور الســتجوابه بــدون عــذر مقبــول أو امتنــع عــن‬\n      ‫اإلجابــة عــن االســتجواب دون مبــرر‪ ،‬ولــم تكــن بينــة للخصــم ‪ ،‬عـ ّـده‬\n      ‫ال ‪ ،‬وأجــرى مــا يلــزم شــرعاً»‪ .‬طلبــت مــن املدعــي ميــن‬     ‫القاضــي نــاك ً‬\n      ‫االســتظهار علــى أن هــذه األعطــال املذكــورة يف التقريــر املشــار إليــه‬\n      ‫موجــودة يف الســيارة منــذ أن اســتلمها مــن الشــركة املدعــى عليهــا ولــم‬\n      ‫تكــن بســبب ســوء اســتخدامه‪ ،‬فحلــف قائــا بعــد أن أذنــت لــه واهلل‬\n      ‫العظيــم أن هــذه األعطــال التــي وجــدت يف الســيارة والتــي ذكــرت يف‬\n      ‫التقريــر الصــادر مــن املعهــد املهنــي الصناعــي لــم تكــن بســبب‬\n      ‫اســتخدامي وهــي موجــودة يف الســيارة منــذ أن اســتلمتها مــن الشــركة‬\n      ‫املدعــى عليهــا واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم فقــد‬\n      ‫ثبــت لــدي صحــة دعــوى املدعــي وحكمــت على الشــركة املدعــى عليها‬\n      ‫أن تســتلم ســيارتها مــن املدعــي وأن تســلم املدعــي ثمــن الســيارة وقــدره‬\n\n\n‫‪131‬‬\n\f‫مائــة وســتة وثالثــون ألــف ريــال حــاال ويعــد هــذا احلكــم حضوريـ ًا يف حق‬\n‫الشــركة املدعــى عليهــا وعليــه قــررت بعــث صــورة مصدقــة مــن هــذا‬\n‫احلكــم للشــركة املدعــى عليهــا وتســليمه مــن ميثلهــا وإفهامــه بــأن لــه‬\n‫ثالثــن يومــا مــن تاريــخ االســتالم لــه أن يقــدم اعتراضــه خاللهــا وإن‬\n‫تأخــر عنهــا ســقط حــق الشــركة يف االعتــراض واكتســب احلكــم‬\n‫القطعيــة بنــاء علــى املــادة (‪ )178 ، 176‬مــن نظــام املرافعــات وختمــت‬\n‫هــذه اجللســة الســاعة الثامنــة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n                                            ‫محمد وعلى آله وصحبه أجمعني‪.‬‬\n‫احلمــد هلل والصــاة علــى رســول اهلل أمــا بعــد ‪ :‬فقــد اطلعنــا نحــن قضــاة‬\n‫الدائــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n‫املعاملــة الــواردة مــن احملكمــة العامــة بتبوك برقــم ‪ 331583484‬وتاريخ‬\n‫‪1434/9/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪)........‬‬\n‫وفقــه اهلل برقــم ‪ 34309635‬وتاريــخ ضبطــه‪ ،‬واملذكــرة االعتراضيــة‬\n‫املقدمــة مــن املدعــى عليــه وأوراق املعاملــة تقــررت باألكثريــة املصادقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪132‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":124,"source_page_end":132,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"048397b0a0d135b141fb094f5b26beee255f7378ded7279535753c696c7f91fe","normalized_text_hash":"9fccd2a7eb9183e8c62b86dd073dfde7f8fec97a8b7e87af301a8b870a8e8c78","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p124-34309635"},{"id":"a48d99bb-ac01-590b-bc29-631b6fcac59e","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -بيع أرض -دعوى غن يف الثمن -مطالبة بفسخ بيع أرض باعها مورث املدعن لوجود غن يف ثمنها -خيار الغن يسقط مبا يدل على الرضا -احلكم برد الدعوى .","document_number":"34258649","case_number":"33627459","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة األحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/3","year":"1434","subject":"بيع -عقد -بيع أرض -دعوى غن يف الثمن -مطالبة بفسخ بيع أرض باعها مورث املدعن لوجود غن يف ثمنها -خيار الغن يسقط مبا يدل على الرضا -احلكم برد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34258649 :‬‬\n                         ‫َر ْق ُم الدعوى‪33627459 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34364026‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬بيــع أرض ‪ -‬دعــوى غــن يف الثمــن ‪ -‬مطالبــة بفســخ بيــع‬\n      ‫أرض باعهــا مــورث املدعــن لوجــود غــن يف ثمنهــا‪ -‬خيــار الغــن يســقط‬\n                                 ‫مبــا يــدل علــى الرضــا ‪ -‬احلكــم بــرد الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــن بــأن املدعــى عليــه اشــترى مــن مــورث موكليــه‬\n      ‫األرض املوصوفــة يف الدعــوى بثمــن فيــه غــن واضــح مســتغال كونــه‬\n      ‫ال درايــة لــه بأســعار العقــار‪ ،‬ولــذا فقــد طلــب إبطــال البيــع املذكــور‬\n      ‫وإعــادة األرض ملوكليــه أو دفــع مــا يــوازي قيمتهــا الفعليــة اآلن كمــا‬\n      ‫طلــب إلــزام املدعــى عليــه بدفــع تعويــض ملوكليــه مقابــل األجــزاء‬\n      ‫املقتطعــة مــن األرض لصالــح الدولــة والتــي حصــل علــى تعويــض عنهــا ‪،‬‬\n      ‫أنكــر املدعــى عليــه مــا جــاء يف الدعــوى ودفــع بأنــه ال يوجــد بينــه وبــن‬\n      ‫مــورث املدعــن أي عالقــة ومعرفــة أو عقــد فهــو قــد اشــترى األرض محل‬\n      ‫الدعــوى مــن شــخص ثالــث كان قــد اشــتراها مــن مورثهــم‪ ،‬دعــوى‬\n      ‫ا عــن بينتهــا ألن مورثهــم بــاع األرض محــل‬\n                                                   ‫املدعــن غيــر مقبولــة فض ـ ً‬\n\n‫‪133‬‬\n\f‫الدعــوى واســتلم الثمــن ثــم شــاهد املشــتري يتصــرف فيهــا بالبيــع والبنــاء‬\n‫والغــرس والتعويــض مــن قبــل الدولــة واالســتالم ولــم يعــارض علــى ذلــك‬\n‫حتــى وفاتــه بعــد البيــع بزمــن طويــل جــد ًا ممــا يــدل علــى قناعتــه بالثمــن‬\n‫أو رضــاه بالغــن علــى فــرض حصولــه ‪ ،‬قضــت احملكمــة بــرد الدعــوى‬\n‫حيــث لــم يتبــن لهــا حــق للمدعــن فيمــا يطالبــون بــه ‪ ،‬قنــع املدعــى‬\n‫عليــه باحلكــم وعــارض عليــه املدعــي‪ ،‬قــررت محكمــة االســتئناف‬\n                                                       ‫املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫العامــة‬\n   ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة‬\n‫باألحســاء (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫مبوجــب وكالتــه عــن (‪ )....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء برقــم ‪ 33294177‬وتاريــخ‬\n‫‪1433/10/9‬ه ـ كمــا أحضــر وكالتــه عــن (‪ )....‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )....‬و (‪ )....‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )....‬و (‪ )....‬و (‪ )....‬ســعودية مبوجــب الســجل املدنــي رقــم (‪ )....‬و(‪)....‬‬\n‫ســعودية مبوجــب الســجل املدنــي رقــم (‪ )....‬ســعودية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )....‬الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء رقــم‬\n‫‪ 33300809‬وتاريــخ ‪1433/10/11‬ه ـ عنــه كمــا أحضــر وكالتــه عــن‬\n‫(‪ )....‬ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )....‬و (‪ )....‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬و (‪ )....‬ســعودية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )....‬و (‪ )....‬ســعودية مبوجــب الســجل املدنــي رقــم (‪ )....‬و‬\n‫(‪ )....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )....‬و (‪ )....‬الصــادرة مــن‬\n\n                                                                                        ‫‪134‬‬\n\f      ‫كتابــة العــدل الثانيــة باألحســاء رقــم ‪ 33301047‬وتاريــخ‬\n      ‫‪1433/10/11‬ه ـ كمــا أحضــر وكالتــه عــن (‪ )....‬ســعودي بالســجل‬\n      ‫املدنــي رقــم (‪ )....‬الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء رقــم‬\n      ‫‪ 33339299‬وتاريــخ ‪1433/10/28‬ه ـ وجميــع موكليــه هــم ورثــة (‪)....‬‬\n      ‫الســعودي مبوجــب الســجل املدنــي رقــم (‪ )....‬مبوجــب صــك حصــر اإلرث‬\n      ‫الصــادر مــن هــذه احملكمــة برقــم ‪ 1200100611003310009‬يف‬\n      ‫‪1431/1/16‬ه ـ كمــا حضــر املدعــى عليــه (‪ )....‬ســعودي مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )....‬وقــال املدعــي وكالــة إن دعــوى موكلــي‬\n      ‫محــررة ومكتوبــة وأطلــب كتابــة نصهــا ووجدنــا نصهــا قام املدعــو(‪)....‬‬\n      ‫بشــراء أرض مــورث موكلــي (‪ )....‬يف ‪1414/10/22‬ه ـ التــي كان‬\n      ‫ميلكهــا بالصــك املرفــق صورتــه باملعاملــة رقــم ‪ 845‬الصــادر مــن كتابــة‬\n      ‫عــدل األحســاء األولــى‪ ،‬البالــغ مســاحتها مائــة وأربعــة وســتون ألف ـ ًا‬\n      ‫ومائتــان واثنــن متــر ًا مببلــغ مليــون وســتمائة ألــف ريــال ‪ ،‬وذلــك بطريــق‬\n      ‫الغــن الواضــح والتغريــر والتضليــل واملخادعــة‪ ،‬والــذي دبــر هــذا األمــر‬\n      ‫وتولــى كبــره هــو املدعــو (‪ )....‬املدعــى عليــه حيــث إنــه يعلــم بحكــم‬\n      ‫عملــه يف أمانــة األحســاء وال يــزال موظف ـ ًا فيهــا إلــى اآلن‪ ،‬وبحكــم‬\n      ‫صلتــه الوثيقــة آنــذاك بقســم األراضــي وغيرهــا مــن أقســام األمانــة يعلــم‬\n      ‫مبخططاتهــا املســتقبلية التــي ســوف تعتمــد يف التطويــر العمرانــي يف‬\n      ‫األحســاء‪ ،‬حيــث قــام بتكــرار التــردد علــى مــورث موكلــي الــذي كان‬\n      ‫أميـ ًا كبيــر ًا يف الســن ومــن أهــل الباديــة ‪ ،‬وال دراية له بأســعار األراضي‬\n      ‫ا عــن أن يــدري مبــا تنــوي بــه األمانــة مــن‬ ‫والعقــار يف املدينــة فض ـ ً‬\n      ‫مخططــات مســتقبلية ومشــاريع طــرق يف األحســاء ونــزع ملكيــات‪ ،‬ولم‬\n      ‫يكتــف‪ ....‬بذلــك بــل أرســل أشــخاص ًا (نحتفــظ بأســمائهم وقــت طلبهــم‬\n\n\n‫‪135‬‬\n\f‫لــإدالء بشــهاداتهم ) لهــم معرفــة مبــورث موكلــي إلقناعــه ببيــع األرض‬\n‫وإظهــار عيــوب فيهــا مــن كونهــا بــدون كهربــاء وبعيــدة عــن العمــران‬\n‫وأنهــا ال تســوى أكثــر مــن مليــون ريــال بينمــا يف احلقيقــة أنهــا تســاوى‬\n‫آنــذاك أضعــاف هــذا املبلــغ ولكــي ال يظهــر (‪ )....‬يف الصــورة أو ًال‬\n‫وينكشــف أمــره وتظهــر خبيئتــه ولكــي ال يبــدو انــه اســتغل معلومــات‬\n‫بحكــم وظيفتــه لإلفــادة منهــا‪ ،‬دفــع باملدعــو (‪ )....‬لشــراء األرض‬\n‫وتســجيلها باســمه ‪ ،‬وملزيــد مــن اإليهــام وإلظهــار األمــر علــى أنــه مت‬\n‫بطريقــة طبيعيــة مت بعــد فتــرة مــن الزمــن إدخــال الشــريك املدعــو (‪)....‬‬\n‫بربــع مشــاع مــن األرض يف ‪1415/1/24‬ه ـ أي بعــد ســنة وثالثــة أشــهر‬\n‫مــن شــراء األرض‪ ،‬وقــد مت بالفعــل تنفيــذ املخطــط املعتمــد يف املنطقــة‬\n‫التــي فيهــا أرض مــورث موكلــي مــن قبــل األمانــة بعــد ســنتني مــن تاريــخ‬\n‫بيعــه ‪ ،‬واقتطعــت احلكومــة أجــزاء مــن األرض املذكــورة علــى فتــرات‬\n‫متفاوتــة ومت تعويــض املذكوريــن بأراضــي مقابــل االقتطــاع موضــح‬\n‫تفاصيلهــا يف ظهــر الصــك املذكــور (ونأمــل مــن فضيلتكــم االطــاع‬\n‫علــى صكــوك أراضــي التعويضــات مــن احلكومــة للمذكوريــن ملعرفــة‬\n‫شــراكة املذكوريــن الثالثــة فيهــا) وبعــد مــرور الســنة الثالثــة مــن تاريــخ‬\n‫البيــع أي يف ‪1417 / 7 / 28‬ه ـ وانتهــاء التعويــض للمذكوريــن وحســب‬\n‫تخطيــط الثالثــة املذكوريــن مت إدخــال املدعــى عليــه (‪)....‬كشــريك‬\n‫ثالــث مشــاع يف األرض املذكــورة ‪ ،‬ومــن خــال هــذا الترتيــب والدخــول‬\n‫املتتابــع للشــركاء (يف شــراكة باملشــاع وليــس بيعــا ملســاحة محــددة)‬\n‫ودخــول (‪)....‬كآخــر الشــركاء للتغطيــة علــى تدبيــره املذكــور‪ ،‬فــا‬\n‫ا الدخــول يف ملــك مشــاع بهــذه الطريقــة املرتبــة إال تأكيــد ًا‬  ‫يتصــور عقـ ً‬\n‫التفــاق ســابق لكــون الثالثــة شــركاء يف هــذا األمــر منــذ البدايــة‪ ،‬ومت‬\n\n\n                                                                                      ‫‪136‬‬\n\f      ‫توزيــع هــذه األدوار بهــذه الطريقــة للتمويــه والتعميــة والتظليــل عــن‬\n      ‫حقيقــة مــا جــرى بحيــث بخــس حــق مــورث موكلــي بأكثــر مــن جهــة‬\n      ‫بالغــن يف الســعر يف وقــت البيــع واســتغالل جهلــه مبــا ســتؤول إليه أرضه‬\n      ‫مــن تخطيــط وتضاعــف الثمــن واســتغل هــذا يف ظــل معرفــة (‪)....‬‬\n      ‫باملخطــط املرســوم لــأرض مبــا يشــبه يف الشــريعة بتلقــي الركبــان‬\n      ‫املنهــي عنــه ‪ ،‬وأيضــا دفــع مــورث موكلــي لبيــع األرض حتــت اإلحلــاح‬\n      ‫وإرســال معــارف لــه ال يعلمــون مــا رســم لألرض ال قناعــه بالبيع وكذلك‬\n      ‫تعييــب (‪ )....‬لــأرض وتقليــل قيمتهــا ببعدهــا عــن العمــران وعــدم وصــول‬\n      ‫اخلدمــات لهــا‪ ،‬وبهــذا تكــون إرادة مــورث موكلــي معيبــة بالتدليــس‬\n      ‫والغــرر مبــا يــوازي اإلكــراه ‪( ،‬وال يحــل مــال امــرئ إال بطيــب مــن‬\n      ‫نفســه) ولبيــان حجــم الغــن الــذي وقــع فيــه مــورث موكلــي فــإن ســعر‬\n      ‫األرض بعــد اعتمــاد التخطيــط ارتفــع بحيــث أصبــح تــوازي قيمتهــا‬\n      ‫حاليـ ًا مــا يقــارب مائتــن مليــون ريــال وال يتصــور أن أرضـ ًا قيمتهــا مليــون‬\n      ‫وســتمائة ألــف ريــال تتضاعــف قيمتهــا مائــة وأربعــن مــرة ممــا يؤكــد‬\n      ‫حجــم الغــن الــذي وقــع ملــورث موكلــي والــذي تــويف مبجــرد علمــه‬\n      ‫باخلديعــة مــن املذكوريــن حزن ـ ًا وكمــد ًا لــذا آمــل مــن فضيلتكــم‬\n      ‫التكــرم مبــا يلــي ‪ -1:‬إزالــة الظلــم والغــن الــذي وقــع علــى مــورث‬\n      ‫موكلــي بإبطــال البيــع املذكــور للحيثيــات املذكــورة أعــاه وإعــادة‬\n      ‫األرض املذكــورة ملوكلــي املذكوريــن أو دفــع مــا يــوازي قيمتهــا‬\n      ‫الفعليــة اآلن املســتحقة لهــم‪ -2 .‬إلــزام املدعــى عليــه بدفــع التعويــض‬\n      ‫ملوكلــي مقابــل األجــزاء املقتطعــة مــن أرضهــم املذكــورة مــن احلكومــة‬\n      ‫الــذي حصــل عليــه املذكــورون بــدون وجــه حــق هــذه دعــواي وبعرضهــا‬\n      ‫علــى املدعــى عليــه قــال إجابتــي مكتوبــة ونصهــا (إشــارة إلــى املعاملــة‬\n\n\n‫‪137‬‬\n\f‫املنظــورة لــدى فضيلتكــم واملتعلقــة بالدعــوى املقامــة ضــدي مــن قبــل‬\n‫(‪ )....‬وكالــه عــن (‪ )....‬واملقيــدة برقــم ‪ 331906735‬وتاريــخ ‪28‬‬\n‫‪1433/10/‬ه ـ وباطالعــي علــى الئحــة دعــواه املرفــق صــورة منهــا‬\n‫املتضمنــة أننــي اشــتريت مــن مــورث املدعــي يف عــام ‪1414‬ه ـ أرض ـ ًا يف‬\n‫(‪ )....‬جنــوب غــرب (‪ )....‬بطريــق التغريــر والتضليــل واملخادعــة والغــن ‪..‬‬\n‫إلــخ كمــا ذكــر يف صحيفــة دعــواه ‪.‬وعليــه أفيــد فضيلتكــم مبــا يلــي ‪:‬‬\n‫أوال ً‪ :‬أريــد أن انــوه عــن اختــاف أســم املــوكل بــن الالئحــة املقدمــة‬\n‫ضمــن النمــوذج والتــي اســتلمتها يف جلســة ‪1434/1/11‬ه ـ والئحــة‬\n‫الدعــوى املســتلمة يف ‪1433/10/28‬ه ـ واطلــب االطــاع علــى التوكيــل‬\n‫وتاريخــه ثاني ـاً‪ :‬أنــه ال يوجــد أرض لــي (‪ )....‬إال مــا اشــتريته مــن قبــل‬\n‫املدعــو (‪ )....‬ولــم أشــتري أي أرض مــن مــورث املدعــي وعليــه ال توجــد أي‬\n‫عالقــة أو عقــد بينــي وبــن مورثــه ثالث ـاً‪ :‬لقــد مت اتهامــي بأننــي غــررت‬\n‫وضللــت وخدعــت مورثــه وإنــي اســتغليت وظيفتــي وهــذه االتهامــات إذا‬\n‫لــم يقــدم مــا يثبتهــا فأننــي أطلــب مــن فضيلتكــم وأنتــم رمــز العدالــة‬\n‫وخليفــة اهلل يف أرضــه بتطبيــق املــادة الرابعــة مــن قواعــد احلــد مــن آثــار‬\n‫الشــكاوى الكيديــة والدعــاوى الباطلــة واملتضمــن أن مــن تقــدم‬\n‫بدعــوى خاصــه وثبــت للمحكمــة كــذب املدعــي يف دعــواه فللقاضــي‬\n‫أن ينظــر يف تعزيــره وللمدعــى عليــه املطالبــة بالتعويــض عمــا حلقــه مــن‬\n‫ضــرر بســبب هــذه الدعــوى وكذلــك مــا تضمنتــه الالئحــة التنفيذيــة‬\n‫لنظــام املرافعــات الشــرعية مــن اســاليب للوصــول ملأربــه ومبتغــاه‪ ،‬وهــو‬\n‫مــا حصــل بالفعــل كمــا ذكرنــا يف الئحة االدعاء املنظــورة لفضيلتكم‬\n‫مبحاولتــه أن ال يظهــر يف الصــورة إال متأخــر ًا لــذر الرمــاد يف العيــون‬\n‫هــذا مــا لــدي مــن إجابــة وحضــر يف هذه اجللســة (‪ )....‬الســعودي بالســجل‬\n\n\n                                                                                      ‫‪138‬‬\n\f      ‫املدنــي رقــم (‪ )....‬وقــال إننــي اشــتريت األرض محــل الدعــوى مــن مــورث‬\n      ‫املدعــن لنفســي يف عــام تاريــخ ‪1414/10/22‬ه ـ وســلمت ثمنهــا ومت‬\n      ‫اإلفــراغ لــي ومــا ذكــره املدعــي وكالــة غيــر صحيــح وقــد بعــت ربــع‬\n      ‫هــذه األرض مشــاعة (‪ )....‬يف عــام ‪1415‬ه ـ وربيــع آخــر ‪ ....‬هــذا احلاضــر‬\n      ‫يف عــام ‪1417‬ه ـ و مت التهميــش علــى الصــك الــذي بيــدي بذلــك و الصــك‬\n      ‫برقــم ‪ 1/ 845‬وتاريــخ ‪1414/10/22‬ه ـ كمــا قمــت ببيــع ربــع ثالــث‬\n      ‫مشــاع علــى أخويــي الشــقيقني (‪ )....‬و (‪ )....‬وقــد متــت املقاســمة فيمــا‬\n      ‫بيننــا وكل واحــد منــا نصيبــه حتــت يــده ولكــن الصــك مشــاع ومت‬\n      ‫عمــارة كل جــزء بالكامــل وال أوافــق علــى مــا يطالــب بــه املدعــن علمــا‬\n      ‫أننــي اشــتريت مــن مــورث املدعــن وكان مخطــط املنطقــة رقــم ‪4/400‬‬\n      ‫جنــوب (‪ )....‬معتمــد ومعــروف مــن اجلميــع وكانــت عالقتــي مبــورث‬\n      ‫املدعــي قويــة ويأتــي لزيارتــي باســتمرار ولــم يطالبنــي بشــيء وقــال‬\n      ‫املدعــى عليــه ‪ ....‬إننــي اســتلمت الربــع اخلــاص بــي وكان عبــارة كثبــان‬\n      ‫مــن الرمــال وقمــت بعمارتــه وبنــاء ســكن خــاص وأحــواش وزراعتــه‬\n      ‫بالنخيــل بالكامــل وحفــر اآلبــار رقــم ( ‪ ) 5 / 4‬التــي تنــص علــى أنــه (إذا‬\n      ‫ثبــت لناظــر القضيــة أن دعــوى املدعــي كيديــه حكــم بــرد الدعــوى ولــه‬\n      ‫احلكــم بتعزيــر املدعــي مبــا يردعــه) رابعـاً‪ :‬صاحــب الفضيلــة مــن املعلــوم‬\n      ‫لــدى فضيلتكــم أن العبــرة باحلــال وليــس باملــآل ولفضيلتكم االســتعانة‬\n      ‫بــذوي اخلبــرة للتأكــد مــن األســعار يف تلــك املنطقــة يف ذلــك احلــن واآلن‬\n      ‫كمــا نفيــد فضيلتكــم عــن عــدم الصــدق الــوارد يف املذكــرة املســلمة‬\n      ‫مــن وكيــل املدعــي يف جلســة ‪1434/1/11‬ه ـ حيــث ذكــر نص ـ ًا (أن‬\n      ‫الســعر بعــد اعتمــاد التخطيــط ارتفــع بحيــث أصبــح يــوازي قيمتهــا‬\n      ‫حالي ـاً) وأنــا اطلــب مخاطبــة األمانــة للتأكــد مــن أن املخطــط معتمــد‬\n\n\n‫‪139‬‬\n\f‫قبــل شــرائي لــأرض بأكثــر مــن خمــس عشــرة ســنه أي قبــل متلكهــا‬\n‫املدعــي بأننــي تــرددت علــى‬\n                            ‫مــن مــورث املدعــي خامس ـاً‪ :‬ذكــر وكيــل ّ‬\n‫مــورث موكليــه يف نفــس الوقــت مت إرســال أشــخاص كــي ال أبــان يف‬\n‫الصــورة وأنــا لــم اشــتري مــن مــورث موكلــه ولــم أره علــى اإلطــاق يف‬\n‫حياتــي كمــا ذكــر أيض ـ ًا أنــه مت تنفيــذ املخطــط املعتمــد بعــد ســنتني‬\n‫مــن شــراء األرض مــن قبــل ‪ ....‬مــع العلــم بــأن األرض مخططــه ومعتمــده‬\n‫ومعلومــة لــدى جميــع املكاتــب العقاريــة بشــوارعها واحمليــط بهــا‬\n‫لوقوعهــا مــن ضمــن مخطــط ‪ 400/4‬واملســمى بالدخــل احملــدود منــذ‬\n‫عــام ‪1404/1/16‬ه ـ أي قبــل الشــراء بعشــر ســنوات ؟ فــكان مــن‬\n‫األجــدى واألحــق أن يتأكــد وكيــل املدعــي مــن أقــرب مكتــب عقــاري‬\n‫يف األحســاء وأنــا أطلــب مــن فضيلتكــم احلكــم بتعزيــره وإثباتــه يف‬\n‫ضبــط القضيــة وفقــا لالئحــة التنفيذيــة رقــم ( ‪ ) 7 / 4‬هــذا ردي علــى‬\n‫دعواهــم وأمتســك بحقــي بتعزيــره والتعويــض املســاوي مبــا يقــرره الشــرع‬\n‫احلنيــف) وبعــرض ذلــك علــى املدعــي وكالــة قــال إننــي أحضــرت إجابتي‬\n‫علــى مــا ذكــره املدعــى عليــه يف اجللســة املاضيــة مكتوبــة و أطلــب‬\n‫كتابــة نصهــا أو ًال ‪ :‬مــا ذكــره املدعــى عليــه يف الفقــرة األولــى يف‬\n‫إجابتــه مــن أن هنــاك اختالف ـ ًا يف اســم موكلــي يف الئحــة االدعــاء‬\n‫املقدمــة مــن لدنــا بالوكالــة ضــد املذكــور لديكــم فــإن احلقيقــة انــه‬\n‫ليــس هنــاك اختالفـ ًا يف اســم موكلــي ملــن تأمــل يف اســمه يف الوكالــة‬\n‫الشــرعية الصــادرة منــه لنــا املرفــق صورتهــا يف املعاملــة فهــو‪)....( /‬‬\n‫ومبوجــب صــورة ســجله يف بطاقــة األحــوال املدنيــة املرفــق صورتهــا‬\n‫لديكــم املطابــق الســمه يف الئحــة االدعــاء ويف الوكالــة الشــرعية‬\n‫املرفقــة باملعاملــة ‪ ، ،‬ومبوجــب صــك حصــر الورثــة املرفــق صورتــه‬\n\n\n                                                                                 ‫‪140‬‬\n\f      ‫باملعاملــة ومبوجــب صــور وكاالت موكلــي وهــم بقيــة ورثــة ‪ ....‬ومــن‬\n      ‫ضمــن الورثــة (‪ )....‬املذكــور (‪ )....‬فخــذ موكلــي وقبيلتــه ثاني ـاً‪ :‬أن مــا‬\n      ‫ذكــره املدعــى عليــه يف الفقــرة الثانيــة مــن أنــه ال توجــد أرض (‪)....‬‬\n      ‫فهــذا غيــر صحيــح ‪ ،‬فكلمــة (‪ )....‬وجنــوب غــرب (‪ )....‬وردت يف صــك‬\n      ‫األرض املدعــى بهــا واملذكــور رقمــه يف صحيفــة ادعــاء موكلــي برقــم‬\n      ‫‪ 845‬وتاريــخ ‪1414/10/22‬ه ـ وهــي محــل هــذا النــزاع ‪ ،‬وهــي بيــت‬\n      ‫القصيــد يف هــذه الدعــوى ‪ ،‬وهــي نفــس األرض التــي أقــر املدعــى عليــه‬\n      ‫يف جوابــه علــى دعــوى موكلــي يف الفقــرة الثانيــة والرابعــة واخلامســة أنــه‬\n      ‫اشــتراها مــن (‪ )....‬ثالث ـاً‪ :‬وأمــا محاولــة املدعــى عليــه يف الفقــرة الثالثــة‬\n      ‫نفــي تغريــره وتظليلــه وغبنــه ملــورث موكلــي واســتغالل وظيفتــه يف ذلــك‬\n      ‫‪ ،‬فهــو غيــر صحيــح‪ ،‬ودليــل غــن املدعــى عليــه ملــورث موكلــي أنــه قــد‬\n      ‫اقتطعــت الدولــة مــن أرض موكلــي بعــد شــرائها مــن قبــل املدعــى عليــه‬\n      ‫مــا يقــارب أحــد عشــر ألــف متــر ًا مربعـ ًا وعوضتــه الدولــة عــن ذلــك اجلــزء‬\n      ‫اليســير مبــا يعــادل أضعــاف تلــك املســاحة بعــدد كبيــر مــن األراضــي‬\n      ‫مــن مخطــط الدخــل احملــدود املجــاور ألرض موكلــي واملدونــة أرقامهــا‬\n      ‫يف صــك األرض املدعــى بهــا ‪ ،‬وميكــن لفضيلتكــم التحقــق ممــا ذكــر‬\n      ‫عــن عــدد األراضــي املعوضــة للمدعــى عليــه ومســاحاتها وأســعارها مــن‬\n      ‫قبــل أمانــة األحســاء ومكاتــب العقــار‪ ،‬واذا كان التعويــض عــن مــا‬\n      ‫يقــارب عشــر األرض قــد بلــغ هــذا العــدد الكبيــر مــن هــذه األراضــي أال‬\n      ‫يــدل ذلــك علــى غــن املدعــى عليــه ملــورث موكلــي ؟ حيــث اشــترى‬\n      ‫األرض بالتغريــر وبثمــن بخــس ‪ ،‬فمــا ظــن فضيلتكــم بقيمــة األرض‬\n      ‫ا عــن مــا‬  ‫كلهــا آنــذاك قياس ـ ًا مبقــدار تعويــض مــا أقتطــع منهــا وفض ـ ً‬\n      ‫تبقــى منهــا بعــد االقتطــاع والبالــغ تقريب ـ ًا (‪ )%85‬مــن مســاحتهاـ رابع ـ ًا ‪:‬‬\n\n\n‫‪141‬‬\n\f‫وأمــا مــا ذكــره املدعــى عليــه يف الفقرتــن الثانيــة واخلامســة يف إجابتــه‬\n‫أنــه لــم يشــتر مــن مــورث موكلــي أي أرض ‪ ،‬وال توجــد أي عالقــة أو‬\n‫عقــد بينــه وبــن مــورث موكلــي ‪ ،‬وأنــه لــم يتــردد عليــه ولــم يــره علــى‬\n‫اإلطــاق يف حينــه فهــو كالم عــار مــن الصحــة متام ـ ًا ‪ ،‬حيــث يوجــد‬\n‫لدينــا شــهود عــدول ينفــون ادعــاءه وزعمــه بعــدم معرفتــه ملــورث موكلــي‬\n‫‪ ،‬ويثبتــون أنــه تــردد عليــه مــرات ‪ ،‬والتقــى بــه يف مزرعتــه وهــي نفــس‬\n‫األرض املدعــى بهــا املذكــورة هنــا ‪ ،‬كمــا التقــى بــه مرتــن يف بيــت‬\n‫مــورث موكلــي ‪ ،‬وأنــه يعــرف مــورث موكلــي معرفــة جيــدة ‪ ،‬وقــد‬\n‫طلــب مــن الشــهود أن يتوســطوا يف الضغــط علــى مــورث موكلــي مــن‬\n‫أجــل بيــع األرض املدعــى بهــا مــع ذكــر عيوبهــا واخفــى مــا يــدور يف‬\n‫أروقــة أمانــة األحســاء آنــذاك مــن مخاطبــات ومراســات العتمــاد‬\n‫املشــاريع العمرانيــة يف حــن أن املدعــى عليــه يعلــم ذلــك لكونــه موظفـ َا‬\n‫يف البلديــة وبحكــم عالقاتــه مــع زمالئــه مبــا يجــري فيهــا مــن التخطيط‬\n‫العمرانــي املزمــع اعتمــاده آنــذاك يف املنطقــة املذكــورة وقــرب انتــزاع‬\n‫الدولــة األرض املذكــورة لتنفيــذ شــارع عــرض ســتني بطــول ‪ 400‬متــر‬\n‫غــرب األرض املدعــى بهــا وشــارع آخــر عــرض اربعــن شــرق الــذي تقــع‬\n‫عليــه مزرعــة موكلــي اآلن ‪ ،‬وهــو مــا حصــل بالفعــل بعــد مــا يقــارب‬\n‫ســنتني مــن شــراء األرض مباشــرة ‪ ،‬فاملخاطبــات كانــت تتــداول بــن‬\n‫أمانــة األحســاء ووزارة الشــئون البلديــة قبــل شــراء أرض موكلــي يف‬\n‫عــام ‪1414‬ه ـ وميكــن لفضيلتكــم مخاطبــة أمانــة األحســاء لإلفــادة عن‬\n‫عمــل املدعــى عليــه آنــذاك يف األمانــة وقبــل وأثنــاء وقــت شــرائه لــأرض‬\n‫املدعــى بهــا ‪ ،‬وعــن بدايــة تواريــخ التخطيــط واملراســات واالعتمــادات‬\n‫للمشــاريع يف املنطقــة الواقعــة بهــا أرض مــورث موكلــي ـ خامسـ ًا ‪ :‬امــا‬\n\n\n                                                                                   ‫‪142‬‬\n\f      ‫مــا ذكــره املدعــى عليــه يف الفقــرة الرابعــة مــن اجابتــه علــى دعــوى‬\n      ‫موكلــي مــن أن األرض تقــع ضمــن مخطــط معتمــد قبــل شــرائه لــأرض‬\n      ‫بأكثــر مــن خمســة عشــر ســنة منــذ عــام ‪ 1400‬وهــو مخطــط ( ‪400 / 4‬‬\n      ‫) املســمى مخطــط (‪ )....‬فهــو محاولــة منــه لإليهــام والتضليــل وإدخــال‬\n      ‫ا يف هــذا‬ ‫أرض موكلــي ضمــن هــذا املخطــط الــذي هــو معتمــد فع ـ ً‬\n      ‫التاريــخ لكــي تنــدرج أرض موكلــي حتــت تاريــخ اعتمــاده ليكــون قبــل‬\n      ‫شــرائه لــأرض فهــو أمــر غيــر صحيــح البتــة ‪ ،‬والصحيــح أن مخطــط‬\n      ‫(‪ )....‬املذكــور مســتقل اســتقال ًال تام ـ ًا عــن أرض موكلــي التــي ال‬\n      ‫يشــملها هــذا املخطــط مطلق ـ ًا ‪ ،‬ومــن ثــم ينتفــي ادعــاؤه بــأن أرض‬\n      ‫موكلــي مندرجــة يف هــذا املخطــط وقبــل شــرائه لهــا بأكثر من خمســة‬\n      ‫عشــر ســنة وميكــن لفضيلتكــم ملخاطبــة أمانــة األحســاء للتحقــق مــن‬\n      ‫هــذه احلقيقــة التــي ذكرناهــا لدحــض ادعــاء املدعــى عليــه ومحاولتــه‬\n      ‫تضليــل العدالــة ‪ ،‬ويثبــت لفضيلتكــم مــا ذكرنــاه يف دعوانــا مــن أن‬\n      ‫املدعــى عليــه علــى علــم بتوجــه األمانــة لتخطيــط هــذه الشــوارع علــى‬\n      ‫أرض موكلــي واعتمادهــا فعمــل علــى شــرائها يف ظــل جهــل موكلــي‬\n      ‫بذلــك واشــتراها بأقــل مــن ثمنهــا ‪ ،‬واســتخدم املدعــى عليــه مــا ذكرنــاه‬\n      ‫مــن اســاليب للوصــول ملأربــه ومبتغــاه ‪ ،‬وهــو مــا حصــل بالفعــل كمــا‬\n      ‫ذكرنــا يف الئحــة االدعــاء املنظــورة لفضيلتكــم مبحاولتــه أن ال يظهــر‬\n      ‫يف الصــورة إال متأخــر ًا لــذر الرمــاد يف العيــون هــذا مــا لــدي مــن إجابــة‬\n      ‫وحضــر يف هــذه اجللســة (‪ )....‬الســعودي بالســجل املدنــي رقــم (‪ )....‬وقــال‬\n      ‫إننــي اشــتريت األرض محــل الدعــوى مــن مــورث املدعــن لنفســي يف عــام‬\n      ‫تاريــخ ‪1414/10/22‬ه ـ وســلمت ثمنهــا ومت اإلفــراغ لــي ومــا ذكــره‬\n      ‫املدعــي وكالــة غيــر صحيــح وقــد بعــت ربــع هــذه األرض مشــاعة ‪ ....‬يف‬\n\n\n‫‪143‬‬\n\f‫عام‪1415‬ه ـ ربيــع آخــر ‪ ....‬هــذا احلاضــر يف عــام ‪1417‬ه ـ ومت التهميــش‬\n‫علــى الصــك الــذي بيــدي بذلــك و الصــك برقــم ‪ 1/ 845‬و تاريــخ‬\n‫‪1414/10/22‬ه ـ كمــا قمــت ببيــع ربــع ثالــث مشــاع علــى أخويــي‬\n‫الشــقيقني (‪ )....‬وقــد متــت املقاســمة فيمــا بيننــا وكل واحــد منــا نصيبــه‬\n‫حتــت يــده ولكــن الصــك مشــاع ومت عمــارة كل جــزء بالكامــل وال‬\n‫أوافــق علــى مــا يطالــب بــه املدعــن علمــا أننــي اشــتريت مــن مــورث‬\n‫املدعــن وكان مخطــط املنطقــة رقــم ‪ 4/400‬جنــوب ‪ ....‬معتمــد و‬\n‫معــروف مــن اجلميــع و كانــت عالقتــي مبــورث املدعــي قويــة ويأتــي‬\n‫لزيارتــي باســتمرار ولــم يطالبنــي بشــيء وقــال املدعــى عليــه ‪ ....‬إننــي‬\n‫اســتلمت الربــع اخلــاص بــي وكان عبــارة كثبــان مــن الرمــال وقمــت‬\n‫بعمارتــه وبنــاء ســكن خــاص وأحــواش وزراعتــه بالنخيــل بالكامــل‬\n‫وحفــر اآلبــار وبعــد تأمــل مــا ســبق ومت ضبطــه ومبــا أن املدعــن مــن ورثــة‬\n‫(‪ )....‬يطالبــون املدعــى عليهمــا بــرد األرض محــل الدعــوى لهــم وإبطــال‬\n‫بيــع مورثهــم أو دفــع مــا يــوازي قيمتهــا ودفــع التعويــض لهــم مــن املقتطــع‬\n‫مــن األرض بدعــوى الغــن يف البيــع والتحايــل والتضليــل ومبــا أن هــذه‬\n‫ا عــن بينتهــا ملــا يأتــي ‪ :‬أو ًال ‪ :‬أن مــورث‬\n                                                ‫الدعــوى غيــر مقبولــة فض ـ ً‬\n‫املدعــن بــاع األرض محــل الدعــوى يف تاريــخ ‪1414/10/22‬ه ـ وأســتلم‬\n‫الثمــن وبقــي علــى هــذا الوضــع دون معارضــه حتــى وفاتــه عــام ‪1431‬ه ـ‬\n‫ثاني ـاً‪ :‬مشــاهدة مــورث املدعــن للمشــتري يتصــرف يف هــذه األرض‬\n‫بالبيــع والبنــاء والغــرس والتعويــض مــن قبــل الدولــة واالســتالم وعــدم‬\n‫املعارضــة ممــا يــدل علــى قناعــة مــورث املدعــن بالثمــن وأن هــذا هــو‬\n‫ثمنهــا يف ذلــك الوقــت أو رضــاه بالغــن علــى فــرض حصولــه كمــا أنــه‬\n‫مبضــي هــذا الوقــت الطويــل جــد ًا انتقلت هذه األرض إلى عدة أشــخاص‬\n\n\n                                                                                      ‫‪144‬‬\n\f      ‫واســتلموا املبيــع وقامــوا بإحيائهــا ويف إبطــال البيــع ضــرر ال يخفــى‬\n      ‫وبالقــول بذلــك يلــزم منــه عــدم اســتقرار ملــك عنــد صاحبــه وهــذا غيــر‬\n      ‫مقبــول وبنــاء علــى ذلــك لــم يتبــن لــي حــق للمدعــن فيمــا يطالبــون بــه‬\n      ‫كمــا لــم يثبــت عنــدي أن هــذه الدعــوى مــن الدعــاوي الكيديــة وبذلــك‬\n      ‫حكمــت وبعرضــه علــى اجلميــع قــرر املدعــى عليهمــا قناعتهمــا باحلكــم‬\n      ‫فيمــا قــرر املدعــي وكالــة عــدم قناعتــه وطلــب االســتئناف ومت إفهامــه‬\n      ‫باملراجعة يف يوم الثالثاء املوافق ‪1434/7/4‬هـ الســتالم نســخة احلكم‬\n      ‫وتقــدمي االعتــراض عليــه خــال ثالثــن يــوم وإال ســقط حــق املدعــن يف‬\n      ‫االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل‬\n                                     ‫على نبينا محمد وعلى آله وصحبه أجمعني‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائرة احلقوقيــة األولى يف محكمة‬\n      ‫االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة األحســاء برقــم ‪ 33/1906735‬وتاريــخ‬\n      ‫‪1434/8/8‬ه واملقيــدة لــدى احملكمــة برقــم ‪ 341962874‬وتاريــخ‬\n      ‫‪1434/8/14‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪)....‬‬\n      ‫املســجل برقــم ‪ 34258649‬وتاريــخ ‪1434/7/3‬ه اخلــاص بدعــوى ورثــة‬\n      ‫(‪ )....‬ضــد (‪ )....‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ ،‬ولبيانــه‬\n                               ‫حــرر يف ‪1434/11/19‬هــ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪145‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":133,"source_page_end":145,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e3511be040c0974a1182551e67c5619c41f76aec53698c2d88b6b856d6b918c","normalized_text_hash":"e90e10555e1f5f958c471ca5206970e25f7bd4df58001d0cfd30de75cf0b2203","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p133-34258649"},{"id":"c200951e-f325-5172-a362-72a78bb7fd0b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -بيع سيارة -فسخ البيع لعيب وغن يف الثمن -تقدير ثمن املبيع عن طريق قسم اخلبراء -ثبوت الغن الفاحش يثبت خيار الفسخ -احلكم بالفسخ ورد قيمة املبيع .","document_number":"34192793","case_number":"33687025","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"بيع -عقد -بيع سيارة -فسخ البيع لعيب وغن يف الثمن -تقدير ثمن املبيع عن طريق قسم اخلبراء -ثبوت الغن الفاحش يثبت خيار الفسخ -احلكم بالفسخ ورد قيمة املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34192793 :‬‬\n                   ‫َر ْق ُم الدعوى‪33687025 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34290958‬تاريخه‪1434/8/8 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــد ‪ -‬بيــع ســيارة ‪ -‬فســخ البيــع لعيــب وغــن يف الثمــن ‪ -‬تقديــر‬\n‫ثمــن املبيــع عــن طريــق قســم اخلبــراء ‪ -‬ثبــوت الغــن الفاحــش يثبــت‬\n                     ‫خيــار الفســخ ‪ -‬احلكــم بالفســخ ورد قيمــة املبيــع ‪.‬‬\n\n\n\n\n ‫وجود الغنب كاف يف ثبوت حق خيار الفسخ‪ .‬شرح املنتهى (‪.)195/3‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن املدعــى عليــه ســيارة موصوفــة يف‬\n‫الدعــوى وســلمه ثمنهــا وبعــد اســتالمه للســيارة اتضــح لــه أن بهــا عيوبــا‬\n‫كثيــرة مذكــورة يف دعــواه لــم يخبــره املدعــى عليــه بهــا ســوى وجــود‬\n‫عيــب يف املاكينــة‪ ،‬كمــا اتضــح لــه أن ســعر الســيارة احلقيقــي أقــل‬\n‫بكثيــر مــن الثمــن الــذي اشــتراها بــه وأنــه غــن فيهــا غبنــا فاحشــا‪،‬‬\n‫لــذا طلــب احلكــم بفســخ البيــع وإلــزام املدعــى عليــه بإعــادة الثمــن الــذي‬\n‫دفعــه لــه كامــا ‪ ،‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n‫ســوى شــراء الســيارة بالثمــن املذكــور وأنــه أخبــره بوجــود عيــب يف‬\n‫املاكينــة ‪ ،‬قــررت احملكمــة تكليــف قســم اخلبــراء بتقديــر ثمــن‬\n‫الســيارة فأفــادوا بــأن الثمــن الــذي بيعــت بــه فيــه غــن ‪ ،‬وجــود الغــن‬\n\n                                                                                      ‫‪146‬‬\n\f      ‫كاف يف ثبــوت حــق خيــار الفســخ كمــا أن الغــن يف ثمــن الســيارة‬\n      ‫محــل الدعــوى غــن فاحــش خــارج عــن العــادة ‪ ،‬قضــت احملكمــة بفســخ‬\n      ‫بيــع الســيارة املوصوفــة يف الدعــوى وألزمــت املدعــى عليــه بإعــادة ثمنهــا‬\n      ‫الــذي اســتلمه إلــى املدعــي وأن علــى املدعــي أن يســلم الســيارة للمدعــى‬\n      ‫عليــه ‪ ،‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه ‪ ،‬قــررت‬\n                                  ‫محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القائــم بعمــل املكتب القضائي‬\n      ‫الســادس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة القطيــف برقــم ‪ 33687025‬وتاريــخ ‪1433/12/01‬ه ـ‬             ‫َ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332169897‬وتاريخ ‪1433/12/1‬هـ ففي يوم‬\n      ‫الســبت املوافق ‪1434/03/28‬هـ افتتحت اجللســة الســاعة (‪ )8:00‬وفيها‬\n      ‫حضــر (‪ )........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬وحضــر حلضــوره‬\n      ‫املدعــى عليــه (‪ )........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬ونظــر ًا‬\n      ‫لتعــارض موعــد هــذه اجللســة مــع جلســة أخــرى بنفــس الوقــت لــدي يف‬\n      ‫مكتبــي املكتــب القضائــي الثامــن وعليــه فقــد رفعــت اجللســة ثــم لــدي‬\n      ‫العامــة مبحافظــة القطيــف ويف يــوم‬  ‫ّ‬     ‫أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫األربعــاء املوافــق ‪1434/04/17‬ه ـ افتتحــت اجللســة وفيها حضــر (‪)........‬‬\n      ‫يحمــل الســجل املدنــي رقــم (‪ )........‬وادعــى علــى احلاضــر معــه (‪)........‬‬\n      ‫ا يف دعــواه لقــد اشــتريت مــن املدعــى عليــه ســيارة نــوع (‪ )........‬صنــع‬\n                                                                                    ‫قائـ ً‬\n      ‫عــام (‪ )........‬اللــون (‪ )........‬رقــم اللوحــة (‪ )........‬بثمــن إجمالــي قــدره‬\n      ‫ســبعة وخمســون ألفــا وأربعمائــة ريــال وبعــد اســتالمي الســيارة أتضــح‬\n\n‫‪147‬‬\n\f‫لــي أن بهــا عيوبـ ًا كثيــرة منهــا تهريــب كارتيــر املاكينــة وتغيــر صوفــة‬\n‫املاكينــة األماميــة وبحاجــة لتصفيــة املاكينــة وإلصــاح املكيــف‬\n‫وتغييــر املســاعدات األماميــة واخللفيــة واملقصــات وبهــا مشــاكل يف‬\n‫الفرامــل وحتتــاج وزن أذرعــة وبهــا صــوت طنجــرة اجليــر كمــا اتضــح‬\n‫ان بهــا صدمــة يف مقدمــة الســيارة مــن جهــة حســاس االيربــاق حســب‬\n‫تقريــر (‪ )........‬لفحــص الســيارات بالكمبيوتــر ولــم يخبرنــي املدعــى‬\n‫عليــه بهــذه العيــوب عــدا الصوفــة كمــا اتضــح لــي أن ســعر الســيارة‬\n‫أقــل بكثيــر مــن الثمــن الــذي اشــتريته بــه وأننــي غبنــت فيهــا غبنــا‬\n‫فاحشـ ًا لــذا كلــه أخبــرت املدعــى عليــه بأنــي ال أرغــب بالســيارة وأطلــب‬\n‫الفســخ فرفــض لــذا أطلــب احلكــم بفســخ البيــع والزامــه بإعــادة الثمــن‬\n‫الــذي دفعتــه كامــا هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال ‪:‬‬\n‫مــا ذكــره املدعــي بدعــواه مــن شــراء الســيارة بالثمــن املذكــور وأننــي‬\n‫أخبرتــه بصوفــة املاكينــة فذلــك صحيــح وأمــا مــا عــدا ذلــك فكلــه‬\n‫غيــر صحيــح متامــا وأرفــض فســخ البيــع وأطلــب رد دعــواه هــذا جوابــي‬\n‫هــذا وقــد ســبق أن متــت الكتابــة إلــى قســم اخلبــراء بهــذه احملكمــة‬\n‫باخلطــاب رقــم ‪ 332169897‬يف ‪1434/01/06‬ه ـ وذلــك لبيــان ثمــن‬\n‫السيارة وردني اجلواب باخلطاب رقم ‪ 332169897‬يف ‪1434/01/17‬هـ‬\n‫وبرفقــه احملضــر املعــد منهــم برقــم ‪ 8‬يف ‪1434/01/13‬ه ـ وقــد تضمــن‬\n‫أن ثمــن الســيارة يف الوقــت الراهــن ثالثــون ألــف (‪)30.000‬ريــال والثمــن‬\n‫الــذي بيعــت بــه فيــه غــن وبعرضــه علــى املدعــى عليــه قــال إن مــا تضمنــه‬\n‫التقريــر غيــر صحيــح ثــم قفلــت املرافعــة وبعــد ســماع الدعــوى وجوابهــا‬\n‫وحيــث انكــر املدعــى عليــه الدعــوى وأثبــت محضــر قســم اخلبــراء‬\n‫باحملكمــة وجــود غــن بأكثــر مــن ســبعة وعشــرين ألــف ريــال وهــو‬\n\n\n                                                                                     ‫‪148‬‬\n\f      ‫غــن فاحــش خــارج عــن العــادة حيــث إنــه يقــارب قيمــة الســيارة احلقيقيــة‬\n      ‫وهــي ثالثــون ألــف ريــال ووجــود الغــن كاف بثبــوت حــق خيــار الفســخ‬\n      ‫كمــا قــرره الفقهــاء رحمهــم اهلل تعالــى كمــا يف شــرح املنتهــى ‪195/3‬‬\n      ‫لــذا كلــه فقــد حكمــت بفســخ بيــع الســيارة املوصوفــة يف الدعــوى‬\n      ‫علــى املدعــي بنــاء علــى طلبــه وألزمــت املدعــى عليــه بإعــادة ثمنهــا الــذي‬\n      ‫اســتلمه وقــدره ســبعة وخمســون ألفــا وأربعمائــة ريــال إلــى املدعــي وأن‬\n      ‫علــى املدعــي أن يســلم الســيارة للمدعــى عليــه وبعرضــه قنــع بــه املدعــي‬\n      ‫ولــم يقنــع املدعــى عليــه طالبــا متييــزه فافهــم باملراجعــة الســتالم نســخة‬\n      ‫احلكــم يــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ ولــه حــق تقــدمي االعتــراض‬\n      ‫خــال ثالثــن يومــن مــن التاريــخ احملــدد الســتالمه نســخة احلكــم وإذا‬\n      ‫لــم يتقــدم الالئحــة االعتراضيــة خــال هــذه املــدة فإنــه يســقط حقــه‬\n      ‫فيــه ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد هــذا‬\n      ‫اليــوم الســبت املوافــق ‪1434/6/24‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫العاشــرة والربــع وقــد وردتنــي الالئحــة االعتراضيــة املقدمــة مــن لفتــن‬\n      ‫واملقيــدة بهــذه احملكمــة برقــم ‪ 341201832‬يف ‪1434/5/18‬ه ـ وقــد‬\n      ‫جــرى اطالعــي عليهــا ولــم أجــد بهــا مؤثــرا علــى حكمــي وصلــى اهلل‬\n        ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/6/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1434/8/21‬ه ـ‬\n      ‫افتتحــت اجللســة يف متــام الســاعة احلاديــة عشــرة والنصــف وكانــت‬\n      ‫املعاملــة قــد عــادت مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫بخطــاب ســماحة رئيســها رقــم ‪ 34/1658434‬يف‪1434/8/10‬ه ـ‬\n\n\n‫‪149‬‬\n\f‫مرفــق بهــا القــرار الصــادر مــن قضــاة الدائــرة احلقوقيــة الثانيــة ق‪2/‬‬\n‫مبحكمــة االســتئناف برقــم ‪ 34290958‬يف ‪1434/8/8‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق ) اهــ‪ .‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                         ‫يف ‪1434/8/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":146,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fa226ef88c82066322f67c9fda9d9cbfa58de649dbec974af2108ff49040d4f","normalized_text_hash":"b2fd5a540b6ac4badc2ab67e6eadd6fd508a0461fc909f6d7e01cfc05da89e6d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p146-34192793"},{"id":"126f2c71-3898-575c-8de1-86fce19a0029","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -عقار -مطالبة بفسخ عقد البيع -مطالبة بإخاء عقار -عقد بيع مت قبل استخراج صك امللكية -األصل حمل العقود على الصحة -تصحيح عقد البيع -عقد البيع ال ينفسخ اال برضا الطرفن -احلكم برد دعوى طلب فسخ عقد البيع واإللزام بسداد باقي ثمن املبيع .","document_number":"3455007","case_number":"33712572","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"بيع -عقد -عقار -مطالبة بفسخ عقد البيع -مطالبة بإخاء عقار -عقد بيع مت قبل استخراج صك امللكية -األصل حمل العقود على الصحة -تصحيح عقد البيع -عقد البيع ال ينفسخ اال برضا الطرفن -احلكم برد دعوى طلب فسخ عقد البيع واإللزام بسداد باقي ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3455007 :‬‬\n                         ‫َر ْق ُم الدعوى‪33712572 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34200451‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬عقــار ‪ -‬مطالبــة بفســخ عقــد البيــع ‪ -‬مطالبــة بإخــاء‬\n      ‫عقــار ‪ -‬عقــد بيــع مت قبــل اســتخراج صــك امللكيــة ‪ -‬األصــل حمــل‬\n      ‫العقــود علــى الصحــة ‪ -‬تصحيــح عقــد البيــع ‪ -‬عقــد البيــع ال ينفســخ‬\n      ‫اال برضــا الطرفــن ‪ -‬احلكــم بــرد دعــوى طلب فســخ عقــد البيع واإللزام‬\n                                                    ‫بســداد باقــي ثمــن املبيــع ‪.‬‬\n\n\n\n\n                  ‫‪ .1‬القاعدة ( األصل حمل العقود على الصحة ما أمكن ) ‪.‬‬\n        ‫‪ .2‬القاعدة ( املطلق يبقى على إطالقه ما لم يقيد بنص أو داللة) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه بــاع للمدعــى عليــه عقــاره املوصــوف يف نــص القضيــة‬\n      ‫مببلــغ قــدره مليــون وأربعمائــة ألــف ريــال وقــد ســلم املدعــى عليــه‬\n      ‫للمدعــي مــن قيمــة العقــار مبلغ ـ ًا وقــدره ثمامنائــة ألــف ريــال والباقــي‬\n      ‫يســلم عنــد اســتخراج صــك العقــار حيــث إن العقــار وقــت إمتــام البيــع‬\n      ‫لــم يتــم اســتخراج صــك ملكيتــه وقــرر املدعــي أن إجــراءات اســتخراج‬\n      ‫صــك العقــار قــد انتهــت وخــرج صــك العقــار ومت إبــاغ املدعــى عليــه‬\n      ‫بذلــك وتزويــده بصــورة مــن الصــك وقــد تضمــن العقــد يف حالــة تأخــر‬\n      ‫املشــتري عــن تســليم باقــي املبلــغ فــإن للبائــع حــق الفســخ وإلغــاء املبايعــة‬\n‫‪151‬‬\n\f‫والتصــرف يف امللكيــة والعربــون الــذي دفــع املشــتري ال يــرد وطلــب‬\n‫املدعــي تطبيــق بنــود العقــد وإخــراج املدعــى عليــه مــن العقــار ‪ ،‬أجــاب‬\n‫املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أن الصــك تأخــر إخراجــه‬\n‫مــن قبــل املدعــي قرابــة الســنتني ونتيجــة لذلــك لــم يكــن املبلــغ املتبقــي‬\n‫موجــود ًا وقتهــا وقــرر انــه راغــب يف البيــت وليســت لديــه رغبــة يف فســخ‬\n‫العقــد وانــه مســتعد بتســليم باقــي املبلــغ ‪ ،‬قــرر املدعــي مصادقتــه علــى‬\n‫أن الصــك تأخــر ولكــن ذلــك مــن الشــركة املســئولة التــي يعمــل بهــا‬\n‫املدعــي ‪ ،‬مت اطــاع ناظــر القضيــة علــى صــك امللكيــة وعقــد املبايعــة‬\n‫ومت االستفســار عــن ســجل الصــك مــن مصــدره ‪ ،‬قــرر ناظــر القضيــة‬\n‫أن العقــد بــن الطرفــن عقــد مبايعــة وهــو مــن العقــود الالزمــة والتــي‬\n‫ال تنفســخ إال برضــا مــن الطرفــن ومــا طلبــه املدعــي مــن فســخ العقــد‬\n‫بســبب تأخــر املشــتري يف تســليم الثمــن غيــر وجيــه ألن العقــد نــص‬\n‫علــى أن باقــي الثمــن يدفــع عنــد اإلفــراغ كمــا نــص علــى أن البائــع‬\n‫هــو املســئول عــن حتريــر الصــك وأقــر املدعــي أن الصــك تأخــر بســبب‬\n‫خــارج عنــه ومبــا أن املدعــى عليــه راغــب يف العقــار ومســتعد بدفــع باقــي‬\n‫املبلــغ وقــد نــص أهــل العلــم علــى أن األصــل حمــل العقــود علــى الصحــة‬\n‫مــا أمكــن وإن املطلــق يبقــى علــى إطالقــه مــا لــم يقيــد بنــص أو داللــة‬\n‫فقــد صــدر احلكــم بــرد دعــوى املدعــي فســخ العقــد وإن عليــه املضــي يف‬\n‫العقــد واإلفــراغ للمدعــى عليــه وإن علــى املدعــى عليــه دفــع باقــي الثمــن‬\n‫حــا ًال عنــد طلــب املدعــي ‪ ،‬قــرر املدعــي عــدم القناعــة ‪ ،‬صــدر قــرار‬\n     ‫محكمــة االســتئناف باملنطقــة الشــرقية باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪152‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫باجلبيــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة باجلبيــل برقــم ‪ 33712572‬وتاريــخ ‪ 1433/12/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332276941‬وتاريــخ ‪ 1433/12/29‬ه ـ ففــي يــوم‬\n      ‫األحــد ‪ 1434/02/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n      ‫حضــر (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬وادعــى‬\n      ‫علــى احلاضــر معــه (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ )....‬وبســؤاله عــن دعــواه قــدم مذكــرة بدعــواه وطلــب ضبطهــا وهــذا‬\n      ‫نصهــا‪ :‬افيــد فضيلتكــم بــان مت بيــع عقــار الكائــن يف ‪ ...‬يف ‪............‬‬\n      ‫شــارع ‪............‬منــزل ‪............‬مببلــغ وقــدرة مليــون واربــع مئــة الــف مت‬\n      ‫دفــع مبلــغ وقــدرة ثمامنائــة الــف والباقــي عنــد اســتخراج الصــك مــن‬\n      ‫الشــركة وقــدرة ســتمائة الــف ويف تاريــخ ‪1433/10/9‬ه ـ مت اســتخراج‬\n      ‫الصــك برقــم ‪ 832401000292‬وقبــل تســعة اشــهر بلغــت املشــتري‬\n      ‫بقــرب اســتخراج الصــك ويف رمضــان ايضــا وعنــد اســتالم الصــك بلغــت‬\n      ‫املشــتري يف تاريخــه واعطــي صــورة مــن الصــك ثــم طلــب منــي اســبوعان‬\n      ‫ويتــم االفــراغ واعطيتــه وقــت كايف أي مــا يقــارب الثالثــة اشــهر حتــى‬\n      ‫يتدبــر امــوره ولــم يتــم ذلــك حتــى تاريــخ كتابــة اخلطــاب الــى االمــارة ومــن‬\n      ‫خــال الفتــرة املاضيــة لــم يدلــي أي اهتمــام يف انهــاء املوضــوع واالكتفاء‬\n      ‫بإرســال الرســائل ويف العقــد الــذي مت االتفــاق عليــه بــن الطرفــن‬\n      ‫الصــادر مــن مكتــب ‪............‬العقــاري يلــزم الطرفــن وقــد اتبعــت جميــع‬\n      ‫البنــود كبائــع والتزمــت بهــا علمــا» مــن خــال الســنتني تكبــده خســائر‬\n\n‫‪153‬‬\n\f‫مــن ايجــارات وخســائر ماليــه ومــن اضــرار يف النقــل الــى مدينــة الدمــام‬\n‫وليس على املشــتري الى بند رقم ‪ 2‬واحد وهو يف حالة تأخير املشــتري‬\n‫عــن دفــع املبلــغ املتبقــي فــان للبائــع احلــق يف فســخ البيــع والغــاء املبايعــة‬\n‫والتصــرف يف ملكــه والعربــون الــذي دفعــه املشــتري ال يــرد اليــه وليــس‬\n‫لــه حــق املطالبــة ويف هــذي احلالــة اطلــب مــن فضيلتكــم بتطبيــق العقــد‬\n‫املتفــق عليــه واســتخراجه مــن املنــزل ولكــم جزيــل الشــكر ودمتــم اهــ‪.‬‬\n‫هــذه دعــواي وباســتجواب املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي‬\n‫يف دعــواه مــن املبايعــة وتفاصيلهــا فكلــه صحيــح إال أنــه متــت املبايعــة‬\n‫بينــي وبينــه بتاريــخ ‪2011/02/01‬م وقــد وعدنــي البائــع حينهــا بــأن‬\n‫الصــك ســيخرج خــال شــهرين ثــم تفاجــأت بأنــه جلــس ســنتني ونتيجــة‬\n‫لذلــك ملــا طلــب منــي املبلــغ لــم يكــن حينهــا موجــودا لــدي وأنــا راغــب‬\n‫بالبيــت وليســت لــدي رغبــة يف الفســخ وأنــا مســتعد بدفــع املبلــغ املتبقــي‬\n‫وهــو خمســمائة وخمســة وثمانــون ألــف ريــال ألننــي ســبق وأن أعطيتــه‬\n‫مبلــغ خمســة عشــر ألــف ريــال زيــادة علــى الدفعــة األولــى التــي ذكرهــا‬\n‫يف دعــواه والتــي هــي ثمامنائــة ألــف ريــال هكــذا أجــاب وبعــرض ذلــك‬\n‫علــى املدعــي أجــاب قائــا‪ :‬تاريــخ املبايعــة وكــذا املبلــغ املتبقــي كلهــا‬\n‫صحيحــة ولكنــي لــم أعــده بإخــراج الصــك يف وقــت قريــب وصحيــح أنه‬\n‫تأخــر اســتخراج الصــك قرابــة الســنتني إال أنــه ملــا خــرج تأخر يف الســداد‬\n‫والتأخيــر لــم يكــن منــي وإمنــا مــن الشــركة التــي أعمــل بهــا هكــذا‬\n‫أجــاب ثــم ســألت املدعــي عــن أصــل الصــك فأبــرز أصلــه فوجدتــه‬\n‫يحمــل الرقــم ‪ 832401000292‬وتاريــخ ‪1433/10/09‬ه ـ وتفاصيــل‬\n‫حــدوده وأطوالــه كالتالــي‪ :‬يقــع يف ‪............‬يف حــي ‪............‬ويحــده‬\n‫شــماال منطقــة للخدمــات واملرافــق العامــة وجنوبــا شــارع ‪............‬بعــرض‬\n\n\n                                                                                           ‫‪154‬‬\n\f      ‫(‪ )18,60‬متــر وشــرقا قطعــة رقــم (‪ )11‬وغربــا قطعــة رقــم (‪ )9‬مبســاحة‬\n      ‫إجماليــة قدرهــا (‪ )560‬خمســمائة وســتون متــرا مربعــا ووجدتــه صــادرا‬\n      ‫مــن كتابــة عــدل اجلبيــل فقــررت االستفســار عــن ســجله وهــل هــو صالــح‬\n      ‫لالعتمــاد عليــه عنــد اإلفــراغ كمــا قــرر املدعــي واملدعــى عليــه بأنــه‬\n      ‫ليــس لديهمــا ســوى مــا قدمــاه مــن دعــوى وإجابــة فجــرى إغــاق بــاب‬\n      ‫املرافعــة ‪،‬ويف يــوم الثالثاء‪1434/03/03‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10.30‬وفيهــا حضــر املدعــي واملدعــى عليــه وقــد وردنــي اجلــواب مــن‬\n      ‫كتابــة عــدل اجلبيــل برقــم ‪ 3451340‬وتأريــخ ‪1434/02/11‬ه ـ مفــاده‬\n      ‫أن الصـ ّـك املذكــور ســاري املفعــول وصالــح لالعتمــاد عليــه عند اإلفراغ‬     ‫ّ‬\n      ‫املدعــي عــن العقــد املبــرم بينهمــا فأبــرز أصلــه وجــرى‬\n                                                                  ‫اه ـ ‪ .‬ثــم ســألت ّ‬\n      ‫إرفــاق صــورة منــه باملعاملــة وباالطــاع عليــه وجدتــه صــادرا مــن مكتــب‬\n      ‫‪............‬العقــاري برقــم ‪ 309‬وتأريــخ ‪2011/02/01‬م ومحــدد بــه العقــار‬\n      ‫املذكــور حســب األوصــاف املثبتــة يف دعــوى املدعــي ووجــدت فيــه مــا‬\n      ‫نصــه ‪ »:‬كيفيــة دفــع القيمــة‪ :‬ثمامنائــة ألــف ريــال مقــدم والباقــي عنــد‬\n                                                                                    ‫ُّ‬\n      ‫نصــه‪»:‬‬‫اإلفــراغ» ‪ .‬كمــا ذكــر فيــه أربعــة شــروط للمبايعــة ومنهــا مــا ُّ‬\n      ‫‪ -1‬علــى املشــتري أن يقــوم بدفــع باقــي الثمــن وقــدره ســتمائة ألــف ريــال‬\n      ‫عنــد اإلفــراغ حــن اإلقــرار للمشــتري لــدى كاتــب العــدل‪ »...‬كمــا‬\n      ‫نصــه ‪ -1 »:‬علــى البائــع املتابعــة‬‫أ ّنــه جــاء يف الشــروط اإلضافيــة مــا ُّ‬\n      ‫إلفــراغ الصــك‪ »...‬كمــا أضــاف املدعــى عليــه قائــا‪ :‬إن املبلــغ جاهــز‬\n      ‫ومســتعد بتحريــره بشــيك مصــدق هكــذا أضــاف فبنــاء علــى مــا تقـ ّـدم‬\n      ‫الدعــوى واإلجابــة ولكــون العقــد بــن الطرفــن عقــد مبايعــة وهــو‬   ‫مــن ّ‬\n      ‫مــن العقــود الالزمــة والتــي ال تنفســخ إال برضــا مــن الطرفــن‪ ،‬ولكــون‬\n      ‫مــا أبــداه املدعــي مــن طلــب تطبيــق العقــد ويعنــي بذلــك الشــرط الثانــي‬\n\n\n‫‪155‬‬\n\f‫التأخــر يف دفــع باقــي الثمــن غيــر وجيــه‬\n                                          ‫ُّ‬      ‫منــه ومفــاده فســخ العقــد حــال‬\n‫أن باقــي الثمــن يدفــع عنــد اإلفــراغ‪ ،‬كمــا‬    ‫ـص علــى ّ‬ ‫ألن العقــد نـ ّ‬\n                                                                            ‫وذلــك ّ‬\n‫أن البائــع وهــو املدعــي هــو املســؤول عــن حتريــر الصــك‪ ،‬وقــد‬     ‫ـص علــى ّ‬  ‫نـ ّ‬\n‫أن‬\n ‫تأخــر إخراجــه بســبب خــارج عنــه‪ ،‬كمــا ّ‬        ‫ـأن الصــك ّ‬   ‫املدعــي بـ ّ‬\n                                                                              ‫أقـ ّـر ّ‬\n‫الوقــت لإلفــراغ لــم يحـ ّـدده البائــع يف العقــد بزمــن ُيعــرف مــن خاللــه‬\n‫املدعــى عليــه» املشــتري» راغــب بالعقــار‬ ‫أن ّ‬   ‫تأخــر املشــتري عنــه‪ ،‬ومبــا ّ‬\n                                                                                  ‫ُّ‬\n‫ـتعد بدفــع املبلــغ املتبقي يف ذمتــه‪ ،‬وتأخره يف دفع املتبقي‬    ‫املذكــور ومسـ ٌّ‬\n‫مــن الثمــن يقابــل تأخــر املدعــي « البائــع» يف حتريــر الصــك‪ ،‬هــذا وقــد‬\n‫الصحــة مــا أمكــن‪،‬‬\n                   ‫ّ‬     ‫أن األصــل حمــل العقــود علــى‬   ‫ـص أهــل العلــم علــى ّ‬   ‫نـ ّ‬\n‫ـص أو داللــة‪ ،‬ألجــل ذلــك‬‫يقيــد بنـ ٍّ‬\n                                     ‫وأن املطلــق يبقــى علــى إطالقــه مــا لــم َّ‬   ‫ّ‬\n‫املدعــي فســخ العقــد‬\n                     ‫كلــه وجلميــع مــا ســبق فقــد حكمــت بــر ّد دعــوى ّ‬\n‫املدعــى‬\n      ‫أن علــى ّ‬ ‫للمدعــى عليــه كمــا ّ‬ ‫وأن عليــه املضــي فيــه واإلفــراغ ّ‬           ‫ّ‬\n‫عليــه دفــع باقــي الثمــن حــاال عنــد طلــب املدعــي وعــدم املماطلــة وبعــرض‬\n‫املدعــي قــرر عــدم القناعــة فجــرى تســليمه صــورة مــن صــك‬        ‫ذلــك علــى ّ‬\n‫احلكــم يف مجلــس احلكــم وجــرى إفهامــه بــأن عليــه تقــدمي اعتراضــه‬\n‫خــال ثالثــن يومــا وإذا انتهــت املــدة ولــم يقــدم اعتراضــه فــإن حقــه‬\n‫يف االعتــراض يســقط ويكتســب احلكــم القطعيــة وكان ختــام هــذه‬\n‫اجللســة الســاعة احلاديــة عشــرة والربــع‪ . .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/03‬هـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة مبحافظــة اجلبيــل برقــم‬\n\n\n                                                                                             ‫‪156‬‬\n\f      ‫‪ 34639104‬وتاريــخ ‪1434/3/14‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34715510‬وتاريــخ ‪1434/3/22‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ (‪ )....‬املســجل برقــم ‪ 3455007‬وتاريــخ ‪1434/3/3‬ه ـ‬\n      ‫اخلــاص بدعــوى(‪ )....‬ضــد(‪ )....‬يف قضيــة حقوقيــة وقــد تضمــن الصــك‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n          ‫احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/4/28‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":151,"source_page_end":157,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"11e313dc67bc54624dcca93c4564a09df165f456a357a2b9d6174b066ecc2b32","normalized_text_hash":"98c2c111d5dbdba9fe96f4ead12c50d295a206c0f01fb69e86b90f393146ec0b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p151-3455007"},{"id":"31768b7a-3749-545a-a554-24b5f4b1b495","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -رأس تريلة -استرداد حيازة سيارة ال يجوز متلكها لغير السعوديني -إثبات قبض الثمن لشهادة الشهود العدول -احلكم باسترداد ثمن املبيع بد ال عن السيارة المتناع متلكه نظام ا .","document_number":"34243235","case_number":"34129773","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/17","year":"1434","subject":"بيع -رأس تريلة -استرداد حيازة سيارة ال يجوز متلكها لغير السعوديني -إثبات قبض الثمن لشهادة الشهود العدول -احلكم باسترداد ثمن املبيع بد ال عن السيارة المتناع متلكه نظام ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34243235 :‬‬\n                   ‫َر ْق ُم الدعوى‪34129773 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34339830‬تاريخه‪1434/10/25 :‬هـ‬\n\n\n‫بيــع ‪ -‬رأس تريلــة ‪ -‬اســترداد حيــازة ســيارة ال يجــوز متلكهــا لغيــر‬\n‫الســعوديني ‪ -‬إثبــات قبــض الثمــن لشــهادة الشــهود العــدول ‪ -‬احلكــم‬\n   ‫باســترداد ثمــن املبيــع بــد ًال عــن الســيارة المتنــاع متلكــه نظام ـ ًا ‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )3‬مــن املــادة (‪ )9‬مــن نظــام املــرور ‪ ،‬ونصهــا ‪( :‬يجــوز لغيــر‬\n‫الســعوديني امتــاك املركبــات اخلصوصــي ‪ -‬ال تزيــد عــن مركبتــن ‪-‬‬\n‫ا علــى رخصــة قيــادة ســارية املفعــول)‪.‬‬\n                                         ‫شــريطة أن يكــون املشــتري حاصـ ً‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن املدعــى عليــه شــاحنة (رأس تريلــة)‬\n‫ثــم اســتلمها منــه وســلمه ثمنهــا وبعــد أن اســتخدمها ملــدة ســتة أشــهر‬\n‫قــام املدعــى عليــه بأخــذ الشــاحنة املذكــورة مــن مقــر الســكن الــذي‬\n‫يســكن بــه املدعــي عــن طريــق مفتــاح آخــر كان معــه‪ ،‬طلــب املدعــي‬\n‫إلــزام املدعــى عليــه بإعــادة الســيارة املذكــورة إليــه أو قيمتهــا التــي‬\n‫ســلمها لــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف الدعــوى جملــة وتفصيــا‬\n‫‪ -‬طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه فأحضــر أربعــة شــهود‬\n‫شــهدوا مبــا يثبــت دعــوى املدعــي وجــرى تعديلهمــا التعديــل الشــرعي‬\n\n\n                                                                                     ‫‪158‬‬\n\f      ‫‪ -‬املركبــة محــل البيــع (رأس تريلــة) وليســت مــن قبيــل املركبــات‬\n      ‫اخلصوصــي التــي يجــوز نظام ـ ًا لغيــر الســعوديني امتالكهــا ‪ -‬قضــت‬\n      ‫احملكمــة بإلــزام املدعــى عليــه بإعــادة مبلــغ الشــراء للمدعــي حــا ًال ‪-‬‬\n      ‫قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة‬\n                                               ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬  ‫بنجــران وبنـ ً‬\n      ‫العامــة بنجــران برقــم ‪ 34129773‬وتاريــخ ‪1434/03/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34687233‬وتاريــخ ‪1434/03/18‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافق‪1434/03/25‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر (‪ )........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫(‪ )........‬كمــا حضــر املدعــى عليــه (‪ )........‬اجلنســية مبوجــب رخصــة‬\n      ‫ا إن لــي بذمــة هــذا احلاضــر‬‫اإلقامــة رقــم (‪ )........‬ثــم أدعــى املدعــي قائـ ً‬\n      ‫مبلغـ ًا وقــدره مائــة وتســعة وســتون ألــف وخمســمائة ريــال ســعودي قيمــة‬\n      ‫ســيارة مــن نــوع (‪ )........‬رأس تريلــه موديــل ‪1990‬م حيــث اشــتريتها منــه‬\n      ‫مببلــغ وقــدره مائــة وســبعون ألــف ريــال ســعودي قبــل مــا يقــارب ســتة‬\n      ‫أشــهر ســلمته عنــد البيــع مائــة ألــف ريــال ثــم ســلمته بعــد ذلــك تســعة‬\n      ‫وســتون ألــف وخمســمائة ريــال وقــد اســتلمت الســيارة منــه عنــد البيــع‬\n      ‫واســتخدمتها ملــدة ســتة أشــهر ثــم بعــد ذلــك قــام املدعــى عليــه بأخــذ‬\n      ‫الســيارة املذكــورة مــن مقــر الســكن الــذي أســكن بــه حيــث كان‬\n      ‫معــه مفتــاح آخــر أطلــب إلزامــه بإعــادة الســيارة املذكــورة إلـ ّـي أو‬\n\n‫‪159‬‬\n\f‫قيمتهــا التــي ســلمته إياهــا هكــذا ادعــى وبعــرض ذلــك علــى املدعــى‬\n‫ا ال صحــة ملــا جــاء يف دعــوى املدعــي فلــم أبعــه الســيارة‬  ‫عليــه أجــاب قائـ ً‬\n‫املذكــورة يف دعــواه ولــم أســتلم منــه املبلــغ املذكــور واملدعــي بينــي‬\n‫وبينــه دعــاوى يف احملاكــم الباكســتانية بخصــوص شــراكة بينــي‬\n‫ا أطلــب‬  ‫وبينــه هكــذا أجــاب وبســؤال املدعــي عــن بينتــه أجــاب قائ ـ ً‬\n‫إمهالــي إلــى اجللســة القادمــة ثــم يف جلســة أخــرى حضــر الطرفــان‬\n‫وبســؤال املدعــي عــن بينتــه التــي وعــد بإحضارهــا يف اجللســة املاضيــة‬\n‫ال مــن (‪ )........‬باكســتاني اجلنســية‬ ‫ا أحضــرت للشــهادة ك ً‬         ‫أجــاب قائـ ً‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬و(‪ )........‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة االقامــة رقــم (‪ )........‬و(‪ )........‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة االقامــة رقــم (‪ )........‬و(‪ )........‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬وبســؤال الشــاهد األول عمــا لديــه‬\n‫ا «أشــهد هلل تعالــى أن املدعــى عليــه قــد أعلمنــي‬    ‫مــن شــهادة أجــاب قائـ ً‬\n‫أن لديــه ســيارة وهــي املذكــورة بدعــوى املدعــي وقــد طلــب منــي البحــث‬\n‫لــه عمــن يشــتريها فأعلمــت املدعــي بذلــك فاســتعد بشــرائها وقــد‬\n‫اشــتراها مــن املدعــى عليــه مببلــغ وقــدره مائــة وســبعون ألــف ريــال وقــد‬\n‫ســلم املدعــي املدعــى عليــه مبلغ ـ ًا وقــدره تســعون ألــف ريــال بحضــوري‬\n‫وبعــد ســتة أشــهر ســلم املدعــي املدعــى عليــه مبلغـ ًا وقــدره أربعــون ألــف‬\n‫ريــال ثــم بعــد أســبوع تقريبـ ًا ســلمه كذلــك تســعة آالف وخمســمائة هــذا‬\n‫مــا لــدي مــن شــهادة» وبســؤال الشــاهد الثانــي (‪ )........‬عمــا لديــه مــن‬\n‫ا «أشــهد هلل تعالــى أن املدعــي ســلم املدعــى عليــه‬       ‫شــهاده أجــاب قائ ـ ً‬\n‫مبلغـ ًا وقــدره تســعة آالف وخمســمائة ريــال مــن قيمــة الســيارة املذكــورة‬\n‫بدعــواه هــذا مــا لــدي مــن شــهادة» وبســؤال الشــاهد الثالــث (‪ )........‬عمــا‬\n\n\n                                                                                         ‫‪160‬‬\n\f      ‫ا « أشــهد هلل تعالــى أن املدعــي ســلم املدعــى‬   ‫لديــه مــن شــهاده أجــاب قائـ ً‬\n      ‫عليــه مبلغ ـ ًا وقــدره عشــرون ألــف ريــال مــن قيمــة الســيارة املذكــورة‬\n      ‫بدعــواه هــذا مــا لــدي مــن شــهادة»‪ .‬وبســؤال الشــاهد الرابــع (‪ )........‬عمــا‬\n      ‫ا « أشــهد هلل تعالــى أن املدعــي اشــترى من‬     ‫لديــه مــن شــهاده فأجــاب قائـ ً‬\n      ‫املدعــى عليــه الســيارة املذكــورة بالدعــوى مببلــغ وقــدره مائــة وســبعون‬\n      ‫ألــف ريــال وقــد ســلم املدعــي املدعــى عليــه عشــرة آالف ريــال عربــون ثــم‬\n      ‫ســلمه بعــد ذلــك مبلغـ ًا وقــدره تســعون ألــف ريــال كدفعــة أولــى هــذا مــا‬\n      ‫ا‬\n      ‫لــدي مــن شــهادة»‪ .‬وبســؤال املدعــي هــل لديــك زيــادة بينــة فأجــاب قائـ ً‬\n      ‫نعــم لــدي شــاهد آخــر وهــو هــذا احلاضــر (‪ )........‬باكســتاني اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫أجــاب قائ ـاً‪« :‬املدعــي أخــي وأشــهد هلل تعالــى أن املدعــي اشــترى‬\n      ‫مــن املدعــى عليــه الســيارة املذكــورة يف الدعــوى مببلــغ وقــدره مائــة‬\n      ‫وســبعون ألــف ريــال وســلمه منهــا مبلغـ ًا وقــدره مائــة وتســعة وســتون الــف‬\n      ‫ريــال وخمســمائة ريــال ســلمه منهــا عشــرة آالف ريــال عربــون ثــم ســلمه‬\n      ‫منهــا تســعون ألــف ريــال ثــم عشــرون ألــف ريــال ثــم أربعــون ألــف ريــال‬\n      ‫ثــم تســعة آالف وخمســمائة ريــال هــذا مــا لــدي مــن شــهادة»‪ .‬وقــد جــرى‬\n      ‫ال مــن (‪ )........‬باكســتاني اجلنســية مبوجــب‬    ‫تعديــل الشــهود مــن قبــل ك ً‬\n      ‫رخصــة اإلقامــة رقــم (‪ )........‬و (‪ )........‬باكســتاني اجلنســية مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم (‪ )........‬حيــث شــهدا بعدالــة الشــهود وأنهــم مرضــي‬\n      ‫الشــهادة وبســؤال املدعــى عليــه عــن الشــهود ومــا جــاء يف شــهادتهم‬\n      ‫ا الشــهود جميعهــم مــن جماعــة املدعــي ومــن قريــة واحــدة‬      ‫فأجــاب قائـ ً‬\n      ‫ومــا جــاء يف شــهادتهم فغيــر صحيــح هكــذا أجــاب ثــم يف جلســة أخــرى‬\n      ‫حضــر الطرفــان وأبــرز املدعــى عليــه تأشــيرة خــروج وعــودة وتذاكــر‬\n\n\n‫‪161‬‬\n\f‫ا هــذه التأشــيرة والتذاكــر تثبــت أننــي كنــت خــارج‬         ‫ســفر وأجــاب قائـ ً‬\n‫اململكــة يف الوقــت الــذي يدعــي فيــه املدعــي أنــه باعنــي الســيارة‬\n‫املذكــورة بدعــواه هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب‬\n‫ا أنــا ال أتذكــر تاريــخ البيــع والشــراء بالضبــط ومــا ذكرتــه يف‬         ‫قائ ـ ً‬\n‫دعــواي هــو تاريــخ تقريبــي وقــد اشــتريت منــه الســيارة ثــم ســافر بعدهــا‬\n‫مباشــر ًة إلــى باكســتان حيــث تــويف أخــاه هنــاك هكــذا أجــاب كمــا‬\n‫أبــرز املدعــى عليــه ورقــة مترجمــة مــن مكتــب الشــرق األوســط للترجمة‬\n‫ونصهــا « تقريــر رقــم ‪ 17‬بتاريــخ ‪2012/10/15‬م مبنطقة (‪ )........‬محطة‬\n‫(‪ )........‬رقــم ‪ 17‬الطلــب املقــدم إلــى (‪ )........‬يف الســاعة ‪ 1740‬بتاريــخ‬\n‫‪2012/10/15‬م مت تقــدمي الطلــب املكتــوب مــن قبــل املدعــو (‪)........‬‬\n‫ا‬\n‫املقيــم يف (‪ )........‬إلــى مديــر محطــة الشــرطة يف مديريــة (‪ )........‬قائ ـ ً‬\n‫أنــه كان التعامــل ملذكــور مــع (‪ )........‬و(‪ )........‬أبنــاء (‪ )........‬مبديريــة‬\n‫(‪ )........‬يف جتــارة النقــل وجلــس جلنــة التحكيــم القبائلــي بعــدة مــرات‬\n‫وحلــل هــذه القضيــة تعــن جلــوس اجلركــة يف غرفــة أذان (‪ )........‬لتســوية‬\n‫مســتحقاتي مببلــغ ‪ 45000،0‬علــى ذمــة (‪ )........‬ولــم يتمكــن احلــل ألن‬\n‫املذكــور رفــض وخــرج مــن جلســة جلنــة التحكيــم القبائلــي وحددنــي‬\n‫للنظــر علــي فيمــا بعــد علمـ ًا بــأن األمــر يتعلــق مبديريــة مــردان لــذا قمــت‬\n‫بتقــدمي الطلــب إلــى محطــة ســعادتكم للنظــر إلــى معاملتــي واتخــاذ‬\n‫اإلجــراءات القانونيــة ضــد املذكــور إلعطــاء مســتحقاتي عليــه ختــم‬\n‫اســتالم الطلــب مــن محطــة الشــرطة يف مديريــة مــردان «أ‪-‬ه ـ وبســؤاله‬\n‫ا هــذه الورقــة تثبــت أن بينــي وبــن‬   ‫عــن وجــه الشــاهد منهــا فأجــاب قائـ ً‬\n‫املدعــي دعــاوى يف باكســتان وحســابات ماليــة وهــذه الدعــوى املرفوعــة‬\n‫يف اململكــة مــن قبــل املدعــي هــي دعــوى كيديــة ويقصــد مــن وراءهــا‬\n\n\n                                                                                         ‫‪162‬‬\n\f      ‫إحلــاق األذى بــي هكــذا أجــاب وبســؤال الطرفــن هل لــدى أحد منكما‬\n      ‫ا ليــس لــدي ســوى‬   ‫مــا يريــد إضافتــه فأجــاب كل واحــد منهمــا قائ ـ ً‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى وإنــكار املدعــى عليــه مــا‬\n                                                                      ‫مــا قدمــت فبنـ ً‬\n      ‫جــاء فيهــا وملــا جــاء بشــهادة الشــهود املعدلــن التعديــل الشــرعي وألن‬\n      ‫مــا دفــع بــه املدعــى عليــه مــن عــدم وجــوده يف التاريــخ احملــدد املذكــور‬\n      ‫مــن قبــل املدعــي للبيــع يســقطه شــهادة الشــهود الذيــن شــهدوا بصحــة‬\n      ‫البيــع وألن املدعــي ذكــر أن هــذا التاريــخ تقريبــي وليــس قطعــي كمــا‬\n      ‫أن مــا دفــع بــه املدعــى عليــه مــن وجــود دعــاوى بينــه وبــن املدعــي يف‬\n      ‫باكســتان ال متنــع مــن ســماع هــذه الدعــوى الســتقاللها عــن الدعــاوى‬\n      ‫التــي يف باكســتان وألن الســيارة محــل البيــع رأس تريلــة ليســت مــن‬\n      ‫قبيــل املركبــات اخلصوصــي وملــا نصــت عليــه الفقــرة (‪ )3‬مــن املــادة (‪)9‬‬\n      ‫مــن نظــام املــرور ونصهــا «يجــوز لغيــر الســعوديني امتــاك املركبــات‬\n      ‫اخلصوصــي ‪ -‬ال تزيــد عــن مركبتــن ‪ -‬شــريطة ان يكــون املشــتري‬\n      ‫ا عــن رخصــة قيــادة ســارية املفعــول ‪ »...‬الــخ لذلــك كلــه فقــد ثبت‬ ‫حاصـ ً‬\n      ‫لــدي تســليم املدعــي للمدعــى عليــه مبلغ ـ ًا وقــدره مائــة وتســعة وســتون‬\n      ‫ألــف وخمســمائة ريــال قيمــة رأس تريلــة وحكمــت بإلــزام املدعــى‬\n      ‫عليــه بإعــادة مبلــغ الشــراء وقــدره مائــة وتســعة وســتون ألــف وخمســمائة‬\n      ‫ريــال للمدعــي حــا ًال وبعــرض ذلــك علــى الطرفــن قــرر املدعــي قناعتــه‬\n      ‫باحلكــم كمــا قــرر املدعــى عليــه اعتراضــه علــى احلكــم بالئحــة‬\n      ‫فأفهــم بــأن عليــه تقــدمي الئحتــه االعتراضيــة خــال مــدة قدرهــا ثالثــون‬\n      ‫يوم ـ ًا مــن تاريــخ اســتالمه نســخة مــن احلكــم ففهــم ذلــك وعليــه فقــد‬\n      ‫رفعــت اجللســة الســاعة احلاديــة عشــرة وبــاهلل التوفيــق وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/5‬ه ـ ‪.‬‬\n\n\n‫‪163‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبوجــب اخلطــاب رقــم ‪ 342300310‬وتاريــخ ‪1434/11/6‬ه ـ ومرفــق بــه‬\n‫قــرار التصديــق رقــم ‪ 34339830‬وتاريــخ ‪1434/10/25‬ه ـ ونص احلاجة‬\n‫منــه» وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وآلــه وصحبــه وســلم قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف ‪ ......‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه»‬\n‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                 ‫حــرر يف ‪1434/11/20‬هــ‪.‬‬\n\n\n\n\n                                                                                  ‫‪164‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":158,"source_page_end":164,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93ddd0c0a1f7cd12b29e34190939ade3eb06b172d147b33b66b08c9cbaf9ef51","normalized_text_hash":"b145286b7945d5a6e756f22799ca17d0fc5691e9cc2dcb793979c69a6f2b3ac0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p158-34243235"},{"id":"9f22c9dc-1d87-5797-91a5-168b175c3fd0","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -باقي ثمن مبيع بالتقسيط -اإلقرار ببيع االعيان قبل دخولها يف ضمانه -التمكن من القبض ينزل منزلة القبض يف الضمان ال يف حل الربح -األعيان املنقولة ال يتحقق قبضها إال بنقلها -احلكم برأس املال فقط للمدعي؛ للنهي عن ربح ما لم","document_number":"34200144","case_number":"34136760","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/28","year":"1434","subject":"بيع -باقي ثمن مبيع بالتقسيط -اإلقرار ببيع االعيان قبل دخولها يف ضمانه -التمكن من القبض ينزل منزلة القبض يف الضمان ال يف حل الربح -األعيان املنقولة ال يتحقق قبضها إال بنقلها -احلكم برأس املال فقط للمدعي؛ للنهي عن ربح ما لم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34200144 :‬‬\n                         ‫َر ْق ُم الدعوى‪34136760 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34269056‬تاريخه‪1434/7/16 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬باقــي ثمــن مبيــع بالتقســيط ‪ -‬اإلقــرار ببيــع االعيــان قبــل‬\n      ‫دخولهــا يف ضمانــه ‪ -‬التمكــن مــن القبــض ينــزل منزلــة القبــض يف‬\n      ‫الضمــان ال يف حــل الربــح ‪ -‬األعيــان املنقولــة ال يتحقــق قبضهــا إال‬\n      ‫بنقلهــا ‪ -‬احلكــم بــرأس املــال فقــط للمدعــي؛ للنهــي عــن ربــح مــا لــم‬\n                                                                          ‫يضمــن ‪.‬‬\n\n\n\n                     ‫‪ .1‬نهى النبي صلى اهلل عليه وسلم عن ربح مالم يضمن ‪.‬‬\n      ‫‪ .2‬حديــث ابــن عمــر رضــي اهلل عنهمــا‪ :‬وقــد رأيــت النــاس يف عهــد رســول‬\n      ‫اهلل صلــى اهلل عليــه وســلم إذا ابتاعــوا الطعــام جزافــا يضربــون قبــل أن‬\n      ‫يبيعــوه يف مكانهــم وذلــك حتــى يــؤوه إلــى رحالهــم‪ .‬أخرجــه البخــاري‪.‬‬\n      ‫‪ .3‬حديــث ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم نهــى أن يبيــع الرجــل طعامــا حتــى يســتوفيه قيــل البــن عبــاس‬\n      ‫كيــف ذاك قــال ذاك دراهــم بدراهــم والطعــام مرجــأ‪ .‬أخرجــه البخاري‪،‬‬\n      ‫ويف روايــة عنــه قــال‪ :‬قــال رســول اهلل صلــى اهلل عليــه وســلم‪« :‬مــن ابتــاع‬\n      ‫طعامــا فــا يبيعــه حتــى يقبضــه» قــال ابــن عبــاس‪ :‬وأحســب كل شــيء‬\n                                                 ‫مبنزلــة الطعــام‪ .‬أخرجــه مســلم‪.‬‬\n      ‫‪ .4‬حديــث زيــد بــن ثابــت‪« :‬نهــى رســول اهلل صلــى اهلل عليــه وســلم أن‬\n      ‫تبــاع الســلع حيــث تبتــاع حتــى يحوزهــا التجــار إلــى رحالهــم» أخرجــه‬\n                                                ‫أحمــد وأبــو داوود‪ ،‬وإســناده جيــد‪.‬‬\n\n‫‪165‬‬\n\f‫‪ .5‬مــا جــاء عــن أبــي هريــرة وزيــد بــن ثابــت رضــي اهلل عنهمــا أنهمــا أنكــرا‬\n‫علــى مــروان بــن احلكــم فقــاال‪ :‬أحتــل بيــع الربــا يــا مــروان! قــال‪ :‬أعــوذ‬\n‫بــاهلل ومــا ذاك فقــاال هــذه الصكــوك تبايعهــا النــاس ثــم باعوهــا قبــل‬\n‫أن يســتوفوها فبعــث مــروان احلــرس يتبعونهــا فينزعوهــا مــن أيــدي‬\n                                      ‫النــاس ويردونهــا إلــى أهلهــا‪ .‬رواه مســلم‪.‬‬\n‫‪ .6‬جــاء يف شــرح الزركشــي ( وبيــع املســلم فيــه مــن بائعــه أو غيــره قبــل‬\n‫قبضــه فاســد واملعتمــد علــى نهــي النبــي صلــى اهلل عليــه وســلم عــن بيــع‬\n                                ‫الطعــام قبــل قبضــه وعــن ربــح مالــم يضمــن )‪.‬‬\n‫‪ .7‬قــال اخلرقــي مــن احلنابلــة إن الصبــرة املتعينــة املبيعــة جزافــا تدخل‬\n‫يف ضمــان املشــتري بالعقــد وال يجــوز للمشــتري بيعهــا حتــى ينقلهــا‪.‬‬\n                       ‫(مجمــوع فتــاوي شــيخ اإلســام ابــن تيميــة ‪)400/29‬‬\n‫‪ .8‬قــال شــيخ االســام ابــن تيميــة رحمــه اهلل ( ومــن جعــل التصــرف‬\n‫تابعــا للضمــان فقــد غلــط فقــد ثبــت يف الصحيــح عــن ابــن عمــر رضــي‬\n‫اهلل عنهمــا أنــه قــال كنــا نبتــاع الطعــام جزافــا علــى عهــد رســول اهلل‬\n‫صلــى اهلل عليــه وســلم فنهــى أن نبيعــه حتــى ننقلــه إلــى رحالنــا وابــن‬\n‫عمــر هــو القائــل مضــت الســنة أن مــا أدركــت الصفقــة حيــا مجموعــا‬\n‫فهــو مــن ضمــان املشــتري فتبــن أن مثــل هــذا الطعــام مضمــون علــى‬\n‫املشــتري وال يبيعــه حتــى ينقلــه فالســنة يف هــذا البــاب فرقــت بــن‬\n‫القــادر علــى القبــض وغيــر القــادر يف الضمــان والتصــرف ) مجمــوع‬\n                                                                ‫الفتــاوي ‪.344/20‬‬\n‫‪ .9‬وقــال رحمــه اهلل‪ ( :‬إن النهــي إمنــا كان للتاجــر الــذي يربــح فــا‬\n‫يبيــع بربــح حتــى يصيــر يف حوزتــه ويعمــل فيهــا عمــا مــن أعمــال‬\n‫التجــارة إمــا بنقلهــا إلــى مــكان آخــر كالــذي يشــتري يف بلــد ويبيــع يف‬\n                                ‫آخــر وإمــا حبســها إلــى وقــت آخــر ‪ ...‬إلــخ ) ‪.‬‬\n                                                                                         ‫‪166‬‬\n\f      ‫ادعــى املدعــي أنــه بــاع للمدعــى عليــه عشــر مكيفــات‪ ،‬بالعقــد الصــادر‬\n      ‫من شــركة‪ ...‬للتقســيط‪ ،‬بقيمة إجمالية قدرها ثمانية عشــر ألف ريال‬\n      ‫مقســطة علــى أقســاط شــهرية قــدر كل قســط ألــف ريــال‪ ،‬ســدد منهــا‬\n      ‫املدعــى عليــه ســبعة آالف ريــال‪ ،‬وبقــي أحــد عشــر ألــف ريــال حالــة‪،‬‬\n      ‫وطلــب احلكــم علــى املدعــى عليــه بدفــع أحــد عشــر ألــف ريــال ‪ ،‬بعــرض‬\n      ‫دعــوى املدعــي علــى املدعــى عليــه صــادق عليهــا ‪ ،‬جــرى ســؤال املدعــي‬\n      ‫هــل آلــت إليــه األعيــان املباعــة بالشــراء مــن شــركة ‪ ...‬للتقســيط؟ وهــل‬\n      ‫قــام بنقــل األعيــان بعــد شــرائها؟ فأجــاب بأنــه اشــترى األعيــان املباعــة‬\n      ‫علــى املدعــى عليــه مــن شــركة ‪ ...‬للتقســيط بأحــد عشــر ألــف ريــال‬\n      ‫وباعهــا علــى املدعــى عليــه بثمانيــة عشــر ألــف ريــال‪ ،‬وأنــه لــم يقــم بنقلهــا‬\n      ‫مــن املعــرض وإمنــا قــام بتنحيتهــا يف أحــد جوانــب املعــرض ‪ ،‬جــرى ســؤال‬\n      ‫املدعــى عليــه هــل بــاع األعيــان علــى شــركة ‪ ...‬للتقســيط؟ فأجــاب أنــه‬\n      ‫باعهــا بعشــرة آالف ريــال ‪ ،‬املدعــي أقــر أنــه بــاع علــى املدعــى عليــه‬\n      ‫األعيــان املذكــورة قبــل دخولهــا يف ضمانــه وربــح علــى املدعــى عليــه‬\n      ‫ســبعة آالف ريــال ‪ ،‬نهــى النبــي صلــى اهلل عليــه وســلم عــن ربــح مالــم‬\n      ‫يضمن‪،‬التمكــن مــن القبــض ينــزل منزلــة القبــض يف الضمــان ال يف‬\n      ‫حــل الربــح ‪ ،‬واألعيــان املباعــة منقولــة‪ ،‬وال يتحقــق قبضهــا إال يف بيــع‬\n      ‫املدعــي للســلعة وهــي يف حيــازة بائعهــا األول وتــوارد املبايعــات عليهــا‬\n      ‫عشــرات املــرات يــؤدي إلــى قصــر تــداول الســلعة بــن التجــار للمضاربــة‬\n      ‫علــى فروقــات األســعار والســلعة ثابتــة علــى حالهــا‪ ،‬فهــذه التجارة ليســت‬\n      ‫منتجــة وال نافعــة للمجتمــع فالتجــارة كمــا تنفــع التاجــر بالربــح فإنــه‬\n\n‫‪167‬‬\n\f‫ينبغــي أن تكــون محققــة ملنافــع املجتمــع ‪ ،‬مت إفهــام املدعــي أنــه ال‬\n‫يســتحق يف ذمــة املدعــى عليــه إال رأس مالــه وقــدره أحــد عشــر ألــف‬\n‫ريــال‪ ،‬ومت احلكــم علــى املدعــى عليــه بدفــع أربعــة آالف ريــال للمدعي‪،‬‬\n‫بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر‬\n‫املدعــي عــدم قناعتــه ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                            ‫املصادقــة عليــه ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬مســاعد رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34136760‬وتاريــخ‬\n‫‪ 1434/03/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34725942‬وتاريــخ‬\n‫‪ 1434/03/23‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/04/08‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .............‬وادعــى علــى احلاضــر معــه ‪ ...........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬قائــا يف دعــواه عليــه‬\n‫بعــت املدعــى عليــه أجهــزة كهربائيــة عبــارة عــن عشــرة مكيفــات‬\n‫نــوع ‪ ......‬بالعقــد الصــادر مــن شــركة ‪ ............‬للتقســيط رقــم ‪16063‬‬\n‫يف ‪1432/2/22‬ه ـ بقيمــة إجماليــة قدرهــا ثمانيــة عشــر ألــف ريــال‬\n‫(‪ )18000‬مقســطة علــى أقســاط شــهرية قــدر كل قســط ألــف ريــال‬\n‫(‪ )1000‬اعتبــارا مــن ‪1432/3/25‬ه ـ ســدد منهــا ســبعة آالف ريــال‬\n‫(‪ )7000‬وتبقــى عليــه أحــد عشــر ألــف ريــال (‪ )11000‬وهــي حالــه‬\n‫أطلــب احلكــم عليــه بدفــع أحــد عشــر ألــف ريــال (‪ )11000‬هــذه دعــواي‬\n\n                                                                                        ‫‪168‬‬\n\f      ‫وبســؤال املدعــى عليــه قــال مــا ذكــره املدعــي مــن أننــي اشــتريت منــه‬\n      ‫أجهــزة كهربائيــة بالعقــد املذكــور أعــاه باملبلــغ اإلجمالــي واملقســط‬\n      ‫واملتبقــي وأنــه حــال صحيــح فســألت املدعــي هــل آلــت إليــك األعيــان‬\n      ‫املباعــة بالشــراء مــن شــركة ‪ ...........‬قــال نعــم اشــتريت األعيــان املباعــة‬\n      ‫علــى املدعــى عليــه مــن شــركة ‪ ...........‬بأحــد عشــر ألف ريــال (‪)11000‬‬\n      ‫وبعتهــا علــى املدعــى عليــه بثمانيــة عشــر ألــف ريــال (‪ )18000‬فســألته‬\n      ‫وهــل قمــت بنقــل األعيــان بعــد شــرائها فقــال لــم أقــم بنقلهــا مــن املعــرض‬\n      ‫وإمنــا قمــت بنتحيتهــا يف أحــد جوانــب املعــرض هكــذا أجــاب فســألت‬\n      ‫املدعــى عليــه وهــل بعــت االعيــان علــى شــركة ‪ ..........‬فقــال نعــم بعتهــا‬\n      ‫بعشــرة آالف ريــال (‪ )10000‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث أقــر املدعــي أنــه بــاع علــى املدعــى عليــه األعيــان املذكــورة قبــل‬\n      ‫دخولهــا يف ضمانــه وربــح علــى املدعــى عليــه ســبعة آالف ريــال (‪)7000‬‬\n      ‫وقــد نهــى النبــي صلــى اهلل عليــه وســلم عــن ربــح مالــم يضمــن جــاء يف‬\n      ‫شــرح الزركشــي ( وبيــع املســلم فيــه مــن بائعــه أو غيــره قبــل قبضــه‬\n      ‫فاســد واملعتمــد علــى نهــي النبــي صلــى اهلل عليــه وســلم عــن بيــع الطعــام‬\n      ‫قبــل قبضــه وعــن ربــح مالــم يضمــن ) لذلــك كلــه أفهمــت املدعــي أنــه ال‬\n      ‫يســتحق يف ذمــة املدعــى عليــه إال رأس مالــه وقــدره أحــد عشــر ألــف ريال‬\n      ‫(‪ )11000‬وعليــه فقــد حكمــت علــى املدعــى عليــه بدفــع أربعــة آالف‬\n      ‫ريــال (‪ )4000‬للمدعــي وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه قناعتــه باحلكــم كمــا قــرر املدعــي عــدم قناعتــه باحلكــم وطلــب‬\n      ‫محكمــة االســتئناف فأجبتــه لطلبــه وافهمتــه بــأن بــأن مــدة االعتــراض‬\n      ‫ثالثــون يومــا تبــدأ مــن ‪1434/ 4/ 20‬ه ـ وإذا انقضــت املــدة احملــددة قبــل‬\n      ‫تقــدمي الئحتــه االعتراضيــة فــإن حقــه يف طلــب االســتئناف يعتبــر ســاقطا‬\n\n\n‫‪169‬‬\n\f‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/08‬ه ـ‬\n‫ويف يوم الثالثاء املوافق‪ 1434/07/04‬هـ افتتحت اجللســة الســاعة (‪15‬‬\n‫‪ )10 :‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫بالرقــم ‪ 34725942‬يف ‪1434/6/17‬ه ـ وبرفقهــا قــرار الدائــرة احلقوقيــة‬\n‫السادســة رقــم ‪ 34236572‬املتضمــن وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر إعادتهــا إلــى فضيلــة حاكمهــا لطلــب‬\n‫االفــادة مــن شــركة ‪ ...........‬هــل الســلعة املباعــة ســلمت للمدعــي بعــد‬\n‫اســتالمها لثمنهــا وقــام بحيازتهــا بجانــب املعــرض مــع إرفــاق صــورة‬\n‫مــن عقــد البيــع إن وجــد فــإذا اتضــح حيــازة املدعــي للمبيــع بعــد دفــع‬\n‫ثمنــه فالبيــع صحيــح والزيــادة يف الثمــن مقابــل التأجيــل صحيحــة فعلــى‬\n‫فضيلتــه مالحظــة ذلــك وبــاهلل التوفيــق واجلــواب عليــه املدعــي ذكــر‬\n‫انــه قــام بحيــازة األعيــان املباعــة بتمييزهــا يف إحــدى جوانــب املعــرض‬\n‫ولــم يقــم بنقلهــا منــه ولــذا فــا حاجــة إلــى طلــب إفــادة الشــركة بعــد‬\n‫إقــرار املدعــي أمــا قــول أصحــاب الفضيلــة أنــه اتضــح حيــازة املدعــي‬\n‫للمبيــع بعــد دفــع ثمنــه فالبيــع صحيــح والزيــادة يف الثمــن مقابــل التأجيــل‬\n‫صحيحــة فاجلــواب عليــه أنــا لــم أحكــم ببطــان البيــع واحلكــم صــدر‬\n‫باســتحقاق رأس املــال فقــط أمــا الزيــادة فهــي باطلــة ألن املشــتري وهــو‬\n‫املدعــي هنــا بــاع العــن بعــد متكنــه مــن القبــض وقبــل القبــض احلقيقــي‬\n‫املتمثــل يف نقــل العــن املباعــة يــدل علــى ذلــك حديــث ابــن عمــر رضــي‬\n‫اهلل عنهمــا وقــد رأيــت النــاس يف عهــد رســول اهلل صلــى اهلل عليــه وســلم‬\n‫إذا ابتاعــوا الطعــام جزافــا يضربــون يف أن يبيعــوه يف مكانهــم وذلــك‬\n‫حتــى يــؤوه إلــى رحالهــم ( أخرجــه البخــاري كتــاب البيــوع ) وحديــث‬\n\n\n                                                                                      ‫‪170‬‬\n\f      ‫ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم نهــى‬\n      ‫أن يبيــع الرجــل طعامــا حتــى يســتوفيه قيــل البــن عبــاس كيــف ذاك قــال‬\n      ‫ذاك دراهــم بدراهــم والطعــام مرجــأ ( البخــاري ) ويف روايــة عنــه قــال‬\n      ‫قــال رســول اهلل صلــى اهلل عليــه وســلم مــن ابتــاع طعامــا فــا يبيعــه حتــى‬\n      ‫يقبضــه قــال ابــن عبــاس وأحســب كل شــيء مبنزلــة الطعــام ( مســلم‬\n      ‫كتــاب البيــوع ) وحديــث زيــد بــن ثابــت نهــى رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم أن تبــاع الســلع حيــث تبتــاع حتــى يحوزهــا التجــار إلــى رحالهــم‬\n      ‫( أحمــد وأبــو داوود واســناده جيــد ) فالبيــع صحيــح بتمكــن املدعــي‬\n      ‫مــن القبــض ولكــن ال يطيــب لــه الربــح حتــى يقبــض قبضــا حقيقيــا‬\n      ‫ويتحقــق القبــض يف مثــل هــذه االعيــان بنقلهــا قــال شــيخ االســام ابــن‬\n      ‫تيميــة رحمــه اهلل ( ومــن جعــل التصــرف تابعــا للضمــان فقــد غلــط فقــد‬\n      ‫ثبــت يف الصحيــح عــن ابــن عمــر رضــي اهلل عنهمــا أنــه قــال كنــا نبتــاع‬\n      ‫الطعــام جزافــا علــى عهــد رســول اهلل صلــى اهلل عليــه وســلم فنهــى أن‬\n      ‫نبيعــه حتــى ننقلــه إلــى رحالنــا وابــن عمــر هــو القائــل مضــت الســنة أن‬\n      ‫مــا أدركــت الصفقــة حيــا مجموعــا فهــو مــن ضمــان املشــتري فتبــن‬\n      ‫أن مثــل هــذا الطعــام مضمــون علــى املشــتري وال يبيعــه حتــى ينقلــه‬\n      ‫فالســنة يف هــذا البــاب فرقــت بــن القــادر علــى القبــض وغيــر القــادر يف‬\n      ‫الضمــان والتصــرف) مجمــوع الفتــاوي ‪ 344/20‬واخلرقــي مــن احلنابلــة‬\n      ‫رحمــه اهلل قــال ( إن الصبــرة املتعينــة املبيعــة جزافــا تدخــل يف ضمــان‬\n      ‫املشــتري بالعقــد وال يجــوز للمشــتري بيعهــا حتــى ينقلهــا) (مجمــوع‬\n      ‫الفتــاوي ‪ )400/29‬أ‪-‬ه ـ فالتمكــن مــن القبــض ينــزل منزلــة القبــض يف‬\n      ‫الضمــان ال يف حــل الربــح واالعيــان املباعــة منقولــة وال يتحقــق قبضهــا‬\n      ‫اال بنقلهــا وتــداول ســندات امللكيــة بــن املتبايعــن والســلعة علــى حالهــا‬\n\n\n‫‪171‬‬\n\f‫يف حيــازة بائعهــا األول هــو نظيــر مــا جــاء عــن أبــي هريــرة وزيــد بــن ثابــت‬\n‫رضــي اهلل عنهمــا أنهمــا أنكــرا علــى مــروان بــن احلكــم فقــاال أحتــل‬\n‫بيــع الربــا يــا مــروان قــال أعــوذ بــاهلل ومــا ذاك فقــاال هــذه الصكــوك‬\n‫تبايعهــا النــاس ثــم باعوهــا قبــل أن يســتوفوها فبعــث مــروان احلــرس‬\n‫يتبعونهــا فينزعوهــا مــن أيــدي النــاس ويردونهــا إلــى أهلهــا ( رواه مســلم‬\n‫كتــاب البيــوع ) ثــم أن بيــع املدعــي للســلعة وهــي يف حيــازة بائعهــا األول‬\n‫وتــوارد املبايعــات عليهــا عشــرات املــرات يــؤدي إلــى قصــر تــداول الســلعة‬\n‫بــن التجــار للمضاربــة علــى فروقــات األســعار والســلعة ثابتــة علــى حالهــا‬\n‫فهــذه التجــارة ليســت منتجــة وال نافعــة للمجتمــع فالتجــارة كمــا تنفــع‬\n‫التاجــر بالربــح فإنــه ينبغــي أن تكــون محققــة ملنافــع املجتمــع قــال شــيخ‬\n‫االســام ( إن النهــي إمنــا كان للتاجــر الــذي يربــح فــا يبيــع بربــح حتــى‬\n‫يصيــر يف حوزتــه ويعمــل فيهــا عمــا مــن أعمــال التجــارة إمــا بنقلهــا‬\n‫إلــى مــكان آخــر كالــذي يشــتري يف بلــد ويبيــع يف آخــر وإمــا حبســها‬\n‫إلــى وقــت آخــر ‪ ...‬إلــخ ) ثــم إن هــذه املبايعــات يشــم منهــا رائحــة الربــا‬\n‫فالصوريــة ظاهــرة يف هــذه املعاملــة فحقيقتهــا تــؤول إلــى كــون البائــع‬\n‫مقرضــا بفائــدة إلــى أجــل وبهــذا يتبــن أن قبــض املدعــي للعــن بعــد‬\n‫شــرائها لــم يكــن قبضــا كامــا يســتحق بــه الربــح ولــذا حكمــت لــه‬\n‫بــرأس املــال وعقــد البيــع مرفــق باملعاملــة لفــة (‪ )7‬قبــل ورود املالحظــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/04‬هــ‪.‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس واعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n\n\n                                                                                         ‫‪172‬‬\n\f      ‫الصــادر مــن فضيلــة الشــيخ ‪ ...........‬القاضــي باحملكمــة اجلزائيــة مبكة‬\n      ‫املكرمة واملسجل بع ــدد ‪ 34200144‬وتاريخ ‪1434/4/28‬هـ املتضمن‬\n      ‫دعوى ‪ ............‬ضد ‪ ، ..........‬احملكوم في ــه مبا دون باطنه ‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى‬\n      ‫احلكــم بعــد االجــراء األخيــر جوابـ ًا علــى قــرار الدائــرة رقــم ‪34236572‬‬\n      ‫وتاريــخ ‪1434/6/11‬ه ـ وعلــى فضيلتــه تدويــن تاريــخ قــرار الدائــرة يف‬\n      ‫الضبــط والصــك وســجله ‪ ،‬واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                        ‫وعل ــى آل ــه وصحب ــه وسلم ‪.‬‬\n\n\n\n\n‫‪173‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":165,"source_page_end":173,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a590d619852b8e29957812b037ecd67b8b17649a9c9e58eb3e1bed80fe17e28b","normalized_text_hash":"f9d17b68c58b8da14fd55174910dc287ce0ab900f06d1787024d01c9afd0ce2d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p165-34200144"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0bc8eeb2-72cb-572b-8f02-2490b08abd16","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -سيارة -فسخ البيع لوجود عيب -سماع الدعوى غيابي ا -مين االستظهار -احلكم حضوري وفق ا للنظام -احلكم بسداد املدعى عليه ثمن املبيع واستالم السيارة .","document_number":"34309635","case_number":"33540310","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":"الدائرة احلقوقية األولى يف محكمة الاستئناف مبنطقة تبوك على","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/30","year":"1434","subject":"بيع -عقد -سيارة -فسخ البيع لوجود عيب -سماع الدعوى غيابي ا -مين االستظهار -احلكم حضوري وفق ا للنظام -احلكم بسداد املدعى عليه ثمن املبيع واستالم السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/30 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34309635 :‬‬\n                    ‫َر ْق ُم الدعوى‪33540310 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 331583484‬تاريخه‪1435/1/11 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــد ‪ -‬ســيارة ‪ -‬فســخ البيــع لوجــود عيــب ‪ -‬ســماع الدعــوى‬\n‫غيابي ـ ًا ‪ -‬ميــن االســتظهار ‪ -‬احلكــم حضــوري وفق ـ ًا للنظــام ‪ -‬احلكــم‬\n                 ‫بســداد املدعــى عليــه ثمــن املبيــع واســتالم الســيارة ‪.‬‬\n\n\n\n\n‫‪ -1‬مــا ذكــره صاحــب املقنــع ‪-‬رحمــه اهلل‪ -‬مــن قولــه‪« :‬وإن ســكت املدعــى‬\n‫عليــه فلــم يقــر ولــم ينكــر‪ ،‬قــال لــه القاضــي‪ :‬إن أجبــت وإال جعلتــك‬\n‫ال‪ ،‬وقضيــت عليــك» املقنــع مــع الشــرح الكبيــر واإلنصــاف‬           ‫نــاك ً‬\n                                                                  ‫(‪.)28/446‬‬\n‫‪ -2‬قــال املــرداوي ‪ -‬رحمــه اهلل ‪ -‬وهــو املذهــب قــال صاحــب الشــرح‬\n              ‫الكبيــر‪ :‬ألنــه نــاكل عمــا توجــب عليــه اجلــواب فيــه‪.‬‬\n‫‪ -3‬املــواد (‪/17‬ج) و(‪ )55‬و(‪ )176‬و(‪ )178‬مــن نظــام املرافعــات الشــرعية‬\n                                                        ‫ولوائحــه التنفيذيــة‪.‬‬\n                                    ‫‪ -4‬املادة (‪ )2/103‬من نظام املرافعات ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن الشــركة املدعــى عليهــا ســيارة جديــدة‬\n‫موصوفــة يف دعــواه وســلمها ثمنهــا وبعــد اســتالم الســيارة واســتخدمها‬\n‫الحــظ وجــود عيــوب يف الســيارة مفصلــة يف الدعــوى فطلــب مــن املدعــى‬\n\n                                                                                  ‫‪124‬‬\n\f      ‫عليهــا إصالحهــا ولــم تتجــاوب يف ذلــك؛ لــذا طلب احلكم على الشــركة‬\n      ‫املدعــى عليهــا باســتالم ســيارتهم منــه وتســليمه قيمتهــا ‪ ،‬لــم يحضــر‬\n      ‫مــن ميثــل املدعــى عليهــا مــع تبلــغ منســوبيها باحلضــور فقــررت احملكمــة‬\n      ‫مواصلــة الســير يف الدعــوى غيابيـ ًا ‪ ،‬مت فحــص الســيارة مــن قبــل اخلبراء‬\n      ‫فتبــن وجــود عــدد مــن األعطــال الفنيــة فيهــا ‪ ،‬قــررت احملكمــة توجيــه‬\n      ‫ميــن االســتظهار للمدعــى عليــه علــى أن األعطــال املذكــورة يف تقريــر‬\n      ‫اخلبــراء موجــودة يف الســيارة منــذ أن اســتلمها مــن الشــركة املدعــى‬\n      ‫عليهــا ولــم تكــن بســبب ســوء اســتخدامه فــأدى اليمــن طبــق مــا طلــب‬\n      ‫منــه‪ ،‬قضــت احملكمــة حضوريــا بثبوت صحة دعــوى املدعي وحكمت‬\n      ‫علــى الشــركة املدعــى عليهــا أن تســتلم ســيارتها مــن املدعــي وأن تســلم‬\n      ‫املدعــي ثمــن الســيارة ‪ ،‬عارضــت املدعــى عليهــا علــى احلكم‪،‬قــررت‬\n                     ‫محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بتبــوك املكلــف برقــم ‪ 33540310‬وتاريــخ ‪ 1433/08/21‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331583484‬وتاريــخ ‪ 1433/08/21‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1433/11/27‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n      ‫وفيهــا حضــر ‪ )........( ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ، )........‬ولــم يحضــر مــن ميثــل الشــركة املدعــى عليهــا الشــركة‬\n      ‫(‪ )........‬للســيارات وقــد وردنــا مــن محضــر اخلصــوم اإلفــادة موقعــة مــن‬\n      ‫شــخص لــم تبــن صفتــه وكذلــك لــم يوقــع عليهــا محضــر اخلصــوم لــذا‬\n\n‫‪125‬‬\n\f‫رفعــت اجللســة إلبــاغ املدعــى عليهــا مــرة أخــرى ‪ .‬ويف جلس ـ ٍة أخــرى‬\n‫حضــر املدعــي ولــم يحضــر مــن ميثــل الشــركة املدعــى عليهــا‪ ،‬وقــد‬\n‫وردنــا مــن محضــر اخلصــوم بهــذه احملكمــة اإلفــادة املتضمنــة اســتالم‬\n‫مديــر الفــرع للشــركة ألصــل ورقــة التبليــغ وعليهــا اســمه وتوقيعــه ؛ لــذا‬\n‫ُرفعــت اجللســة إلبــاغ املدعــى عليهــا مــرة أخــرى ‪ .‬ويف جلس ـ ٍة أخــرى‬\n‫حضــر املدعــي واملــدون هويتــه ســابق ًا ولــم يحضــر مــن ميثــل الشــركة‬\n‫املدعــى عليهــا وقــد وردنــا مــن قســم محضــري اخلصــوم اإلفــادة بتبليــغ‬\n‫املوظــف (‪ )........‬وصفتــه معقــب الشــركة وتوقيــع منســوب إليــه علــى‬\n‫أصــل ورقــة التبليــغ والســاعة اآلن الثامنــة وخمســون دقيقــة ولــم يحضــر‬\n‫وبنــاء علــى الفقــرة «ج» مــن املــادة الســابعة عشــرة واملــادة اخلامســة‬\n‫واخلمســون مــن نظــام املرافعــات قــررت ســماع الدعــوى غيابي ـ ًا فقــرر‬\n‫ا فيهــا أنــه بتاريــخ ‪1433/4/7‬ه ـ اشــتريت مــن‬         ‫املدعــي دعــواه قائ ـ ً‬\n‫الشــركة املدعــى عليهــا الشــركة (‪ )........‬للســيارات ســيارة مــن نــوع‬\n‫(‪( )........‬صنعــت يف عــام (‪ )........‬وقــد اشــتريتها وهــي جديــدة لــم‬\n‫تســتخدم مــن قبــل وســجلت باســمي مببلــغ إجمالــي قــدرة مائــة وســتة‬\n‫وثالثــون ألــف ريــال وبعــد اســتلمت الســيارة واســتخدمتها ال حظــت أن‬\n‫هنــاك صــوت مــن (اجلرابوكــس) واهتــزاز باملكينــة ودخــول الهــواء‬\n‫عبــر النوافــذ يف الســرعات اليســيرة ثــم رجعــت إلــى الشــركة مباشــرة‬\n‫يف صبــاح يــوم الســبت ‪1433/4/10‬ه ـ واطلعتهــم علــى املشــكلة فقــال‬\n‫لــي مديــر الشــركة وكذلــك مديــر الصيانــة أن الصــوت الــذي يف القيــر‬\n‫أو اجلرابوكــس صــوت طبيعــي يذهــب مــع االســتخدام والوقــت وقــاال‬\n‫لــي أيضــا وصــوت الهــواء نحيلــك إلــى قســم الســمكرة وقــام العامــل‬\n‫بشــد الربــات وقــال لــي إن هنــاك مشــكلة يف جــرم الســيارة وأنهــا غيــر‬\n\n\n                                                                                     ‫‪126‬‬\n\f      ‫متوازنــة ولــو فعلــت معــك مــا فعلــت لــن يذهــب صــوت الهــواء ألن هنــاك‬\n      ‫عــدم تــوازن يف هيــكل الســيارة فرجعــت إلــى مديــر الفــرع وأخبرتــه‬\n      ‫بذلــك وقــال لــي دع عنــك مــا قالــه هــذا العامــل وســوف نصلــح لــك مــا‬\n      ‫تريــد بعــد أســبوع وقبلــت كالمــه وخرجــت ثــم عــدت إليــه بعــد أســبوع‬\n      ‫وأخــذ مياطلنــي ويف كل مــرة يأتــي لــي بعــذر ثــم ملــا رأيــت موقــف‬\n      ‫الشــركة املدعــى عليهــا تقدمــت بدعــوى ضدهــم لــدى فــرع وزارة‬\n      ‫التجــارة والصناعــة بتبــوك وذلــك يف مطلــع شــهر جمــادى الثانيــة مــن عــام‬\n      ‫‪1433‬ه ـ ثــم بعــد أن اطلعــوا علــى شــكواي قــام مديــر عــام فــرع وزارة‬\n      ‫التجــارة والصناعــة بتبــوك بالكتابــة إلــى مديــر املعهــد الصناعــي‬\n      ‫الثانــوي بتبــوك للفحــص علــى ســيارتي هــذه وبعــد الكشــف عليهــا‬\n      ‫أجــاب مديــر املعهــد الصناعــي الثانــوي بالــرد علــى ســعادة مديــر عــام‬\n      ‫فــرع وزارة التجــارة بخطابــه رقــم ‪ 428‬يف ‪1433/7/28‬ه ـ واملتضمــن مــا‬\n      ‫يلــي‪( :‬ســعادة مديــر عــام فــرع وزارة التجــارة والصناعــة مبنطقــة تبــوك‬\n      ‫ســلمه اهلل الســام عليكــم ورحمــة اهلل وبركاتــه ‪ ،‬إشــارة إلــى خطــاب‬\n      ‫ســعادتكم رقــم ‪ 641/1538‬وتاريــخ ‪1433/7/26‬ه ـ واملتضمــن‬\n      ‫الكشــف علــى الســيارة (‪ )........‬لصاحبهــا ‪ ....‬والــذي يشــكو مــن وجــود‬\n      ‫خلــل بالســيارة ‪ .‬عليــه نفيدكــم أنــه أثنــاء إجــراء الفحــص علــى الســيارة‬\n      ‫أتضــح مــا يلــي‪ -1 :‬يوجــد صــوت يف اجليــر بكــس أثنــاء التعشــيق وتبديــل‬\n      ‫عصــا اجليــر ‪ -2 .‬يوجــد بهــا اهتــزاز قــوي علــى احملــرك أثنــاء التعشــيق ‪.‬‬\n      ‫‪ -3‬يوجــد صــوت هــواء أثنــاء الســير علــى الطريــق ‪ -4 .‬يوجــد حــذف يف‬\n      ‫الدركســون جهــة اليمــن أثنــاء الســير ‪ .‬وتقبلــوا‪ ......‬فقــام فــرع وزارة‬\n      ‫التجــارة مبخاطبــة فــرع الشــركة حلــل املوضــوع بشــكل ودي فلــم‬\n      ‫يتجاوبــوا معــه وأرشــدني فــرع وزارة التجــارة بالتقــدم للمحكمــة‬\n\n\n‫‪127‬‬\n\f‫فتقدمــت بدعــواي هــذه يف ‪1433/8/21‬ه ـ وعليــه فــإن هــذه األعطــال‬\n‫التــي ذكرتهــا وذكرهــا مديــر املعهــد الصناعــي الثانــوي يف خطابــه‬\n‫املوجــه لفــرع وزارة التجــارة هــي عيــوب مصنعيــة وال عالقــة لــي بهــا وهــي‬\n‫موجــودة يف الســيارة قبــل اســتالمها ‪ ،‬مــع العلــم أن الشــركة قــد ضمــت‬\n‫لــي عندمــا اشــتريتها منهــم القيــر ( اجلربوكــس) واملاكينــة ؛ لــذا أطلــب‬\n‫احلكــم علــى الشــركة املدعــى عليهــا باســتالم ســيارتهم منــي وتســليمي‬\n‫قيمتهــا وقدرهــا مائــة وســتة وثالثــون ألــف ريــال حــا ًال ‪ ،‬هــذه دعــواي ‪.‬‬\n‫وقــررت الكتابــة إلــى ســعادة مديــر املعهــد الصناعــي الثانــوي بتبــوك‬\n‫لســؤاله ‪ :‬هــل باإلمــكان اإلفــادة عــن تلــك العيــوب التــي ذكرهــا يف‬\n‫خطابــه املوجــه لفــرع وزارة التجــارة أهــي عيــوب مصنعيــة أم بســبب‬\n‫اســتخدام املدعــى ‪ ،‬وهــل باإلمــكان إيضــاح عــدد الكيلــوات التــي‬\n‫قطعتهــا الســيارة وقــت الكشــف عليهــا وبيــان األعضــاء الذيــن قامــوا‬\n‫ورفعــت اجللســة لذلــك ‪ .‬ويف جلس ـ ٍة أخــرى‬    ‫بالكشــف علــى الســيارة ‪ُ .‬‬\n‫حضر املدعي ‪ ....‬واملدون هويته ســابق ًا ‪ ،‬ولم يحضر من ميثل الشــركة‬\n‫املدعــى عليهــا الشــركة (‪ )........‬لبيــع الســيارات بصفــة شــرعية ‪ ،‬وقــد‬\n‫وردتنــا اإلفــادة رقــم ‪ 341939644‬يف ‪1434/8/10‬هـ واملتضمنة اســتالم‬\n‫محاســب الشــركة (‪ )........‬خلطــاب التبليــغ وعليهــا اســمه وتوقيعــه ‪ .‬لــذا‬\n‫ُرفعــت اجللســة للتأمــل والدراســة ‪ .‬ويف جلس ـ ٍة أخــرى حضــر املدعــي‬\n‫(‪ )........‬واملــدون هويتــه ســابقاً‪ ،‬ولــم يحضــر مــن ميثــل الشــركة املدعــى‬\n‫عليهــا الشــركة (‪ )........‬لبيــع الســيارات بصفــة شــرعية‪ .‬وقــد وردتنــا‬\n‫اإلفــادة مــن محضــر اخلصــوم بهــذه احملكمــة برقــم ‪ 342022678‬يف‬\n‫‪1434/8/22‬ه ـ واملتضمنــة اســتالم مديــر الصنــدوق بالشــركة املدعــى‬\n‫عليهــا ‪ ....‬ألصــل ورقــة التبليــغ مبوعــد هــذا اليــوم وعليهــا اســمه وتوقيــع‬\n\n\n                                                                                      ‫‪128‬‬\n\f      ‫منســوب إليــه‪ .‬وكنــا قــد كتبنــا إلــى ســعادة مديــر فــرع وزارة التجــارة‬\n      ‫والصناعــة بتبــوك لإلفــادة عمــا ذكــره املدعــي بكتابنــا رقــم‬\n      ‫‪ 341440483‬يف ‪1434/6/18‬هـ فوردني منه اجلواب برقم ‪641/1618‬‬\n      ‫يف ‪1434/7/3‬ه ـ واملتضمــن‪( :‬نفيدكــم بأن (‪ )........‬تقدم لنا بشــكوى‬\n      ‫ضــد الشــركة (‪ )........‬للســيارات يف ‪1433/6/21‬هــ‪ ،‬يشــكو مــن‬\n      ‫وجــود أعطــال فنيــة يف ســيارته التــي اشــتراها منهــم‪ ،‬ومت مخاطبــة‬\n      ‫الشــركة للعمــل علــى إصــاح الســيارة‪ ،‬وقــد تعهدت الشــركة بإصالح‬\n      ‫تلــك األعطــال‪ ،‬وطلــب قطــع الغيــار‪ ،‬لكــن الشــركة لــم تــف بوعدهــا‪،‬‬\n      ‫وبعــد ذلــك مت حتويــل الســيارة للمعهــد املهنــي الصناعــي بتبــوك؛ لفحــص‬\n      ‫الســيارة وإثبــات وجــود األعطــال املصنعيــة‪ ،‬وبعــد صــدور التقريــر مت‬\n      ‫إلــزام الشــركة بإدخــال الســيارة للصيانــة؛ إلصــاح األعطــال الــواردة‬\n      ‫يف التقريــر‪ ،‬وبعــد أســبوع طلبــوا مــن املذكــور اســتالم ســيارته ولــم يتــم‬\n      ‫إصــاح أي عطــل فنــي بالســيارة وال زالــت الشــركة متاطــل يف إصــاح‬\n      ‫الســيارة‪ ) ...‬انتهــى‪ .‬وباالطــاع علــى املرفقــات وجــدت ورقــة مفادهــا‪( :‬‬\n      ‫يف يــوم األربعــاء ‪1434/6/7‬ه ـ وبنــاء علــى الشــكوى املرفوعــة مــن األخ‬\n      ‫(‪ )........‬إلــى وزارة التجــارة مت الشــخوص علــى مقــر الوكالــة الشــركة‬\n      ‫(‪ )........‬للســيارات بتبــوك الســاعة التاســعة والنصــف ومت مقابلــة مديــر‬\n      ‫الفــرع (‪ )........‬هويتــه‪ )........( :‬ومواجهتــه بالتقريــر الفنــي الصــادر مــن‬\n      ‫املعهــد املهنــي الصناعــي رقــم ‪ 428‬يف ‪1433/7/28‬ه ـ البنــد األول‪:‬‬\n      ‫صــوت القيــر‪ ،‬وأفــاد أنــه حتــت االســتدعاء ولــم يتــم عملــه يف الســيارة‬\n      ‫وســوف يتــم إجــراء اخلدمــة الالزمــة أمــا باقــي البنــود فتخضــع الســيارة‬\n      ‫للخدمــة والصيانــة عنــد الوكالــة حتــت الضمــان ويســلم ســيارة بديلــة‪.‬‬\n      ‫ممثــل وزارة التجــارة (‪ )........‬توقيــع منســوب إليــه ومديــر الفــرع (‪)........‬‬\n\n\n‫‪129‬‬\n\f‫وتوقيــع منســوب إليــه‪ ) .‬انتهــى وقــد وردنــي مــن مديــر املعهــد املهنــي‬\n‫الصناعــي اجلــواب برقــم ‪ 187‬يف ‪1434/7/2‬ه ـ وبرفقــه اإلفــادة مــن‬\n‫رئيــس قســم احملــركات واملتضمنــة أنــه ال ميكــن حتديــد هــل األعطــال‬\n‫مصنعيــة أم بســبب ســوء االســتخدام‪ ،‬وأنــه ال ميكــن حتديــد مــن‬\n‫املســؤول عــن وجــود هــذه األعطــال‪ ،‬وال يحتفــظ املعهــد بأرقــام‬\n‫الكيلــوات التــي قطعتهــا الســيارة أثنــاء الكشــف عليهــا‪ ،‬أمــا األعضــاء‬\n‫الذيــن قامــوا بالكشــف على الســيارة فهــم‪،)........( ،)........( ،)........( :‬‬\n‫(‪ )........‬انتهــى‪ .‬ومرفــق بــه التقريــر الصــادر منهــم‪ .‬فســألت املدعــي عمــا‬\n‫يفيــد متلكــه لهــذه الســيارة فأبــرز أصــل االســتمارة وتتضمــن اســم‬\n‫املدعــي (‪ )........‬ورقــم ســجله املدنــي (‪ )........‬وأنــه ميلــك الســيارة التــي مــن‬\n‫نــوع (‪)........‬صنعــت عــام ‪2012‬م ورقــم لوحتهــا (‪ )........‬وأرفــق باملعاملــة‬\n‫صــورة مصدقــة منهــا‪ ،‬وعليــه وبعــد التأمــل والدراســة وبنــاء علــى مــا جــاء‬\n‫يف دعــوى املدعــي ومــا جــاء يف إفــادة مديــر املعهــد املهنــي الصناعــي مــن‬\n‫وجــود هــذه األعطــال الفنيــة يف محــرك الســيارة واالهتــزاز القــوي يف‬\n‫احملــرك أثنــاء التعشــيق وغيرهــا ممــا جــاء يف إفادتــه يف هــذا الوقــت‬\n‫الوجيــز مــن شــراء املدعــي للســيارة الشــركة املدعــى عليهــا ولــم جتــر‬\n‫العــادة مبثــل ذلــك‪ ،‬وبنــاء علــى مــا جــاء يف إفــادة مديــر فــرع وزارة التجارة‬\n‫مــن أن املدعــي تقــدم إليهــم بشــكواه ضــد املدعــى عليهــا بعــد مــرور‬\n‫شــهرين مــن شــراء الســيارة منهــا وأن الشــركة تعهــدت بإصــاح‬\n‫األعطــال احلاصلــة يف الســيارة وأدخلتهــا عندهــا وأخرجتهــا مــن غيــر أن‬\n‫تنهــي هــذه األعطــال وملــا جــاء يف اإلفــادة التــي أرفقهــا ســعادة مديــر فــرع‬\n‫وزارة التجــارة مــن أنــه خــرج إلــى الشــركة منــدوب مــن الفــرع وقابــل‬\n‫مديــر فــرع الشــركة املدعــى عليهــا وعــرض عليــه هــذه اإلشــكاالت‬\n\n\n                                                                                            ‫‪130‬‬\n\f      ‫التــي أثبتهــا التقريــر الفنــي املشــار إليــه بعاليــه وأقــر بهــا مديــر الشــركة‬\n      ‫املدعــى عليهــا وتعهــد بإصالحهــا وذكــر أنهــا حتــت الضمــان ثــم لــم‬\n      ‫يجــر أي شــيء حيالهــا‪ ،‬وألنــه مت إبــاغ منســوبي الشــركة املدعــى‬\n      ‫عليهــا عــدة مــرات مبواعيــد متفرقــة ولــم يحضــر مــن ميثلهــا ولــم يقــدم‬\n      ‫دفاعــه للمحكمــة بعــد علمهــم بهــذه الدعــوى وملــا ذكــره صاحــب املقنع‬\n      ‫‪-‬رحمــه اهلل‪ -‬مــن قولــه‪« :‬وإن ســكت املدعــى عليــه فلــم يقــر ولــم ينكــر‬\n      ‫قــال لــه القاضــي‪ :‬إن أجبــت وإال جعلتــك نــاكال وقضيــت عليــك‪ .‬قــال‬\n      ‫املــرداوي‪ -‬رحمــه اهلل‪ :-‬وهــو املذهــب‪ .‬قــال صاحــب الشــرح الكبيــر ‪-‬‬\n      ‫رحمــه اهلل‪ -‬ألنــه نــاكل عمــا توجــه عليــه اجلــواب فيــه»‪ .‬انظــر املقنــع مــع‬\n      ‫الشــرح الكبيــر واإلنصــاف (‪ )28/446‬انتهــى‪ .‬وملــا جــاء يف الالئحــة‬\n      ‫الثانيــة مــن املــادة الثالثــة بعــد املائــة مــن نظــام املرافعــات مــا نصــه‪« :‬إذا‬\n      ‫تخلــف اخلصــم عــن احلضــور الســتجوابه بــدون عــذر مقبــول أو امتنــع عــن‬\n      ‫اإلجابــة عــن االســتجواب دون مبــرر‪ ،‬ولــم تكــن بينــة للخصــم ‪ ،‬عـ ّـده‬\n      ‫ال ‪ ،‬وأجــرى مــا يلــزم شــرعاً»‪ .‬طلبــت مــن املدعــي ميــن‬     ‫القاضــي نــاك ً‬\n      ‫االســتظهار علــى أن هــذه األعطــال املذكــورة يف التقريــر املشــار إليــه‬\n      ‫موجــودة يف الســيارة منــذ أن اســتلمها مــن الشــركة املدعــى عليهــا ولــم‬\n      ‫تكــن بســبب ســوء اســتخدامه‪ ،‬فحلــف قائــا بعــد أن أذنــت لــه واهلل‬\n      ‫العظيــم أن هــذه األعطــال التــي وجــدت يف الســيارة والتــي ذكــرت يف‬\n      ‫التقريــر الصــادر مــن املعهــد املهنــي الصناعــي لــم تكــن بســبب‬\n      ‫اســتخدامي وهــي موجــودة يف الســيارة منــذ أن اســتلمتها مــن الشــركة‬\n      ‫املدعــى عليهــا واهلل العظيــم هكــذا حلــف فبنــاء علــى مــا تقــدم فقــد‬\n      ‫ثبــت لــدي صحــة دعــوى املدعــي وحكمــت على الشــركة املدعــى عليها‬\n      ‫أن تســتلم ســيارتها مــن املدعــي وأن تســلم املدعــي ثمــن الســيارة وقــدره‬\n\n\n‫‪131‬‬\n\f‫مائــة وســتة وثالثــون ألــف ريــال حــاال ويعــد هــذا احلكــم حضوريـ ًا يف حق‬\n‫الشــركة املدعــى عليهــا وعليــه قــررت بعــث صــورة مصدقــة مــن هــذا‬\n‫احلكــم للشــركة املدعــى عليهــا وتســليمه مــن ميثلهــا وإفهامــه بــأن لــه‬\n‫ثالثــن يومــا مــن تاريــخ االســتالم لــه أن يقــدم اعتراضــه خاللهــا وإن‬\n‫تأخــر عنهــا ســقط حــق الشــركة يف االعتــراض واكتســب احلكــم‬\n‫القطعيــة بنــاء علــى املــادة (‪ )178 ، 176‬مــن نظــام املرافعــات وختمــت‬\n‫هــذه اجللســة الســاعة الثامنــة والنصــف وصلــى اهلل وســلم علــى نبينــا‬\n                                            ‫محمد وعلى آله وصحبه أجمعني‪.‬‬\n‫احلمــد هلل والصــاة علــى رســول اهلل أمــا بعــد ‪ :‬فقــد اطلعنــا نحــن قضــاة‬\n‫الدائــرة احلقوقيــة األولــى يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n‫املعاملــة الــواردة مــن احملكمــة العامــة بتبوك برقــم ‪ 331583484‬وتاريخ‬\n‫‪1434/9/23‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪)........‬‬\n‫وفقــه اهلل برقــم ‪ 34309635‬وتاريــخ ضبطــه‪ ،‬واملذكــرة االعتراضيــة‬\n‫املقدمــة مــن املدعــى عليــه وأوراق املعاملــة تقــررت باألكثريــة املصادقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪132‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":124,"source_page_end":132,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"048397b0a0d135b141fb094f5b26beee255f7378ded7279535753c696c7f91fe","normalized_text_hash":"9fccd2a7eb9183e8c62b86dd073dfde7f8fec97a8b7e87af301a8b870a8e8c78","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p124-34309635"},{"id":"a48d99bb-ac01-590b-bc29-631b6fcac59e","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -بيع أرض -دعوى غن يف الثمن -مطالبة بفسخ بيع أرض باعها مورث املدعن لوجود غن يف ثمنها -خيار الغن يسقط مبا يدل على الرضا -احلكم برد الدعوى .","document_number":"34258649","case_number":"33627459","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة األحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/3","year":"1434","subject":"بيع -عقد -بيع أرض -دعوى غن يف الثمن -مطالبة بفسخ بيع أرض باعها مورث املدعن لوجود غن يف ثمنها -خيار الغن يسقط مبا يدل على الرضا -احلكم برد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34258649 :‬‬\n                         ‫َر ْق ُم الدعوى‪33627459 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34364026‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬بيــع أرض ‪ -‬دعــوى غــن يف الثمــن ‪ -‬مطالبــة بفســخ بيــع‬\n      ‫أرض باعهــا مــورث املدعــن لوجــود غــن يف ثمنهــا‪ -‬خيــار الغــن يســقط‬\n                                 ‫مبــا يــدل علــى الرضــا ‪ -‬احلكــم بــرد الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــن بــأن املدعــى عليــه اشــترى مــن مــورث موكليــه‬\n      ‫األرض املوصوفــة يف الدعــوى بثمــن فيــه غــن واضــح مســتغال كونــه‬\n      ‫ال درايــة لــه بأســعار العقــار‪ ،‬ولــذا فقــد طلــب إبطــال البيــع املذكــور‬\n      ‫وإعــادة األرض ملوكليــه أو دفــع مــا يــوازي قيمتهــا الفعليــة اآلن كمــا‬\n      ‫طلــب إلــزام املدعــى عليــه بدفــع تعويــض ملوكليــه مقابــل األجــزاء‬\n      ‫املقتطعــة مــن األرض لصالــح الدولــة والتــي حصــل علــى تعويــض عنهــا ‪،‬‬\n      ‫أنكــر املدعــى عليــه مــا جــاء يف الدعــوى ودفــع بأنــه ال يوجــد بينــه وبــن‬\n      ‫مــورث املدعــن أي عالقــة ومعرفــة أو عقــد فهــو قــد اشــترى األرض محل‬\n      ‫الدعــوى مــن شــخص ثالــث كان قــد اشــتراها مــن مورثهــم‪ ،‬دعــوى‬\n      ‫ا عــن بينتهــا ألن مورثهــم بــاع األرض محــل‬\n                                                   ‫املدعــن غيــر مقبولــة فض ـ ً‬\n\n‫‪133‬‬\n\f‫الدعــوى واســتلم الثمــن ثــم شــاهد املشــتري يتصــرف فيهــا بالبيــع والبنــاء‬\n‫والغــرس والتعويــض مــن قبــل الدولــة واالســتالم ولــم يعــارض علــى ذلــك‬\n‫حتــى وفاتــه بعــد البيــع بزمــن طويــل جــد ًا ممــا يــدل علــى قناعتــه بالثمــن‬\n‫أو رضــاه بالغــن علــى فــرض حصولــه ‪ ،‬قضــت احملكمــة بــرد الدعــوى‬\n‫حيــث لــم يتبــن لهــا حــق للمدعــن فيمــا يطالبــون بــه ‪ ،‬قنــع املدعــى‬\n‫عليــه باحلكــم وعــارض عليــه املدعــي‪ ،‬قــررت محكمــة االســتئناف‬\n                                                       ‫املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫العامــة‬\n   ‫ّ‬      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة‬\n‫باألحســاء (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫مبوجــب وكالتــه عــن (‪ )....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء برقــم ‪ 33294177‬وتاريــخ‬\n‫‪1433/10/9‬ه ـ كمــا أحضــر وكالتــه عــن (‪ )....‬ســعودي مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )....‬و (‪ )....‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )....‬و (‪ )....‬و (‪ )....‬ســعودية مبوجــب الســجل املدنــي رقــم (‪ )....‬و(‪)....‬‬\n‫ســعودية مبوجــب الســجل املدنــي رقــم (‪ )....‬ســعودية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )....‬الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء رقــم‬\n‫‪ 33300809‬وتاريــخ ‪1433/10/11‬ه ـ عنــه كمــا أحضــر وكالتــه عــن‬\n‫(‪ )....‬ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ )....‬و (‪ )....‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم (‪ )....‬و (‪ )....‬ســعودية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )....‬و (‪ )....‬ســعودية مبوجــب الســجل املدنــي رقــم (‪ )....‬و‬\n‫(‪ )....‬ســعودي مبوجــب الســجل املدنــي رقــم (‪ )....‬و (‪ )....‬الصــادرة مــن‬\n\n                                                                                        ‫‪134‬‬\n\f      ‫كتابــة العــدل الثانيــة باألحســاء رقــم ‪ 33301047‬وتاريــخ‬\n      ‫‪1433/10/11‬ه ـ كمــا أحضــر وكالتــه عــن (‪ )....‬ســعودي بالســجل‬\n      ‫املدنــي رقــم (‪ )....‬الصــادرة مــن كتابــة العــدل الثانيــة باألحســاء رقــم‬\n      ‫‪ 33339299‬وتاريــخ ‪1433/10/28‬ه ـ وجميــع موكليــه هــم ورثــة (‪)....‬‬\n      ‫الســعودي مبوجــب الســجل املدنــي رقــم (‪ )....‬مبوجــب صــك حصــر اإلرث‬\n      ‫الصــادر مــن هــذه احملكمــة برقــم ‪ 1200100611003310009‬يف‬\n      ‫‪1431/1/16‬ه ـ كمــا حضــر املدعــى عليــه (‪ )....‬ســعودي مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )....‬وقــال املدعــي وكالــة إن دعــوى موكلــي‬\n      ‫محــررة ومكتوبــة وأطلــب كتابــة نصهــا ووجدنــا نصهــا قام املدعــو(‪)....‬‬\n      ‫بشــراء أرض مــورث موكلــي (‪ )....‬يف ‪1414/10/22‬ه ـ التــي كان‬\n      ‫ميلكهــا بالصــك املرفــق صورتــه باملعاملــة رقــم ‪ 845‬الصــادر مــن كتابــة‬\n      ‫عــدل األحســاء األولــى‪ ،‬البالــغ مســاحتها مائــة وأربعــة وســتون ألف ـ ًا‬\n      ‫ومائتــان واثنــن متــر ًا مببلــغ مليــون وســتمائة ألــف ريــال ‪ ،‬وذلــك بطريــق‬\n      ‫الغــن الواضــح والتغريــر والتضليــل واملخادعــة‪ ،‬والــذي دبــر هــذا األمــر‬\n      ‫وتولــى كبــره هــو املدعــو (‪ )....‬املدعــى عليــه حيــث إنــه يعلــم بحكــم‬\n      ‫عملــه يف أمانــة األحســاء وال يــزال موظف ـ ًا فيهــا إلــى اآلن‪ ،‬وبحكــم‬\n      ‫صلتــه الوثيقــة آنــذاك بقســم األراضــي وغيرهــا مــن أقســام األمانــة يعلــم‬\n      ‫مبخططاتهــا املســتقبلية التــي ســوف تعتمــد يف التطويــر العمرانــي يف‬\n      ‫األحســاء‪ ،‬حيــث قــام بتكــرار التــردد علــى مــورث موكلــي الــذي كان‬\n      ‫أميـ ًا كبيــر ًا يف الســن ومــن أهــل الباديــة ‪ ،‬وال دراية له بأســعار األراضي‬\n      ‫ا عــن أن يــدري مبــا تنــوي بــه األمانــة مــن‬ ‫والعقــار يف املدينــة فض ـ ً‬\n      ‫مخططــات مســتقبلية ومشــاريع طــرق يف األحســاء ونــزع ملكيــات‪ ،‬ولم‬\n      ‫يكتــف‪ ....‬بذلــك بــل أرســل أشــخاص ًا (نحتفــظ بأســمائهم وقــت طلبهــم‬\n\n\n‫‪135‬‬\n\f‫لــإدالء بشــهاداتهم ) لهــم معرفــة مبــورث موكلــي إلقناعــه ببيــع األرض‬\n‫وإظهــار عيــوب فيهــا مــن كونهــا بــدون كهربــاء وبعيــدة عــن العمــران‬\n‫وأنهــا ال تســوى أكثــر مــن مليــون ريــال بينمــا يف احلقيقــة أنهــا تســاوى‬\n‫آنــذاك أضعــاف هــذا املبلــغ ولكــي ال يظهــر (‪ )....‬يف الصــورة أو ًال‬\n‫وينكشــف أمــره وتظهــر خبيئتــه ولكــي ال يبــدو انــه اســتغل معلومــات‬\n‫بحكــم وظيفتــه لإلفــادة منهــا‪ ،‬دفــع باملدعــو (‪ )....‬لشــراء األرض‬\n‫وتســجيلها باســمه ‪ ،‬وملزيــد مــن اإليهــام وإلظهــار األمــر علــى أنــه مت‬\n‫بطريقــة طبيعيــة مت بعــد فتــرة مــن الزمــن إدخــال الشــريك املدعــو (‪)....‬‬\n‫بربــع مشــاع مــن األرض يف ‪1415/1/24‬ه ـ أي بعــد ســنة وثالثــة أشــهر‬\n‫مــن شــراء األرض‪ ،‬وقــد مت بالفعــل تنفيــذ املخطــط املعتمــد يف املنطقــة‬\n‫التــي فيهــا أرض مــورث موكلــي مــن قبــل األمانــة بعــد ســنتني مــن تاريــخ‬\n‫بيعــه ‪ ،‬واقتطعــت احلكومــة أجــزاء مــن األرض املذكــورة علــى فتــرات‬\n‫متفاوتــة ومت تعويــض املذكوريــن بأراضــي مقابــل االقتطــاع موضــح‬\n‫تفاصيلهــا يف ظهــر الصــك املذكــور (ونأمــل مــن فضيلتكــم االطــاع‬\n‫علــى صكــوك أراضــي التعويضــات مــن احلكومــة للمذكوريــن ملعرفــة‬\n‫شــراكة املذكوريــن الثالثــة فيهــا) وبعــد مــرور الســنة الثالثــة مــن تاريــخ‬\n‫البيــع أي يف ‪1417 / 7 / 28‬ه ـ وانتهــاء التعويــض للمذكوريــن وحســب‬\n‫تخطيــط الثالثــة املذكوريــن مت إدخــال املدعــى عليــه (‪)....‬كشــريك‬\n‫ثالــث مشــاع يف األرض املذكــورة ‪ ،‬ومــن خــال هــذا الترتيــب والدخــول‬\n‫املتتابــع للشــركاء (يف شــراكة باملشــاع وليــس بيعــا ملســاحة محــددة)‬\n‫ودخــول (‪)....‬كآخــر الشــركاء للتغطيــة علــى تدبيــره املذكــور‪ ،‬فــا‬\n‫ا الدخــول يف ملــك مشــاع بهــذه الطريقــة املرتبــة إال تأكيــد ًا‬  ‫يتصــور عقـ ً‬\n‫التفــاق ســابق لكــون الثالثــة شــركاء يف هــذا األمــر منــذ البدايــة‪ ،‬ومت‬\n\n\n                                                                                      ‫‪136‬‬\n\f      ‫توزيــع هــذه األدوار بهــذه الطريقــة للتمويــه والتعميــة والتظليــل عــن‬\n      ‫حقيقــة مــا جــرى بحيــث بخــس حــق مــورث موكلــي بأكثــر مــن جهــة‬\n      ‫بالغــن يف الســعر يف وقــت البيــع واســتغالل جهلــه مبــا ســتؤول إليه أرضه‬\n      ‫مــن تخطيــط وتضاعــف الثمــن واســتغل هــذا يف ظــل معرفــة (‪)....‬‬\n      ‫باملخطــط املرســوم لــأرض مبــا يشــبه يف الشــريعة بتلقــي الركبــان‬\n      ‫املنهــي عنــه ‪ ،‬وأيضــا دفــع مــورث موكلــي لبيــع األرض حتــت اإلحلــاح‬\n      ‫وإرســال معــارف لــه ال يعلمــون مــا رســم لألرض ال قناعــه بالبيع وكذلك‬\n      ‫تعييــب (‪ )....‬لــأرض وتقليــل قيمتهــا ببعدهــا عــن العمــران وعــدم وصــول‬\n      ‫اخلدمــات لهــا‪ ،‬وبهــذا تكــون إرادة مــورث موكلــي معيبــة بالتدليــس‬\n      ‫والغــرر مبــا يــوازي اإلكــراه ‪( ،‬وال يحــل مــال امــرئ إال بطيــب مــن‬\n      ‫نفســه) ولبيــان حجــم الغــن الــذي وقــع فيــه مــورث موكلــي فــإن ســعر‬\n      ‫األرض بعــد اعتمــاد التخطيــط ارتفــع بحيــث أصبــح تــوازي قيمتهــا‬\n      ‫حاليـ ًا مــا يقــارب مائتــن مليــون ريــال وال يتصــور أن أرضـ ًا قيمتهــا مليــون‬\n      ‫وســتمائة ألــف ريــال تتضاعــف قيمتهــا مائــة وأربعــن مــرة ممــا يؤكــد‬\n      ‫حجــم الغــن الــذي وقــع ملــورث موكلــي والــذي تــويف مبجــرد علمــه‬\n      ‫باخلديعــة مــن املذكوريــن حزن ـ ًا وكمــد ًا لــذا آمــل مــن فضيلتكــم‬\n      ‫التكــرم مبــا يلــي ‪ -1:‬إزالــة الظلــم والغــن الــذي وقــع علــى مــورث‬\n      ‫موكلــي بإبطــال البيــع املذكــور للحيثيــات املذكــورة أعــاه وإعــادة‬\n      ‫األرض املذكــورة ملوكلــي املذكوريــن أو دفــع مــا يــوازي قيمتهــا‬\n      ‫الفعليــة اآلن املســتحقة لهــم‪ -2 .‬إلــزام املدعــى عليــه بدفــع التعويــض‬\n      ‫ملوكلــي مقابــل األجــزاء املقتطعــة مــن أرضهــم املذكــورة مــن احلكومــة‬\n      ‫الــذي حصــل عليــه املذكــورون بــدون وجــه حــق هــذه دعــواي وبعرضهــا‬\n      ‫علــى املدعــى عليــه قــال إجابتــي مكتوبــة ونصهــا (إشــارة إلــى املعاملــة‬\n\n\n‫‪137‬‬\n\f‫املنظــورة لــدى فضيلتكــم واملتعلقــة بالدعــوى املقامــة ضــدي مــن قبــل‬\n‫(‪ )....‬وكالــه عــن (‪ )....‬واملقيــدة برقــم ‪ 331906735‬وتاريــخ ‪28‬‬\n‫‪1433/10/‬ه ـ وباطالعــي علــى الئحــة دعــواه املرفــق صــورة منهــا‬\n‫املتضمنــة أننــي اشــتريت مــن مــورث املدعــي يف عــام ‪1414‬ه ـ أرض ـ ًا يف‬\n‫(‪ )....‬جنــوب غــرب (‪ )....‬بطريــق التغريــر والتضليــل واملخادعــة والغــن ‪..‬‬\n‫إلــخ كمــا ذكــر يف صحيفــة دعــواه ‪.‬وعليــه أفيــد فضيلتكــم مبــا يلــي ‪:‬‬\n‫أوال ً‪ :‬أريــد أن انــوه عــن اختــاف أســم املــوكل بــن الالئحــة املقدمــة‬\n‫ضمــن النمــوذج والتــي اســتلمتها يف جلســة ‪1434/1/11‬ه ـ والئحــة‬\n‫الدعــوى املســتلمة يف ‪1433/10/28‬ه ـ واطلــب االطــاع علــى التوكيــل‬\n‫وتاريخــه ثاني ـاً‪ :‬أنــه ال يوجــد أرض لــي (‪ )....‬إال مــا اشــتريته مــن قبــل‬\n‫املدعــو (‪ )....‬ولــم أشــتري أي أرض مــن مــورث املدعــي وعليــه ال توجــد أي‬\n‫عالقــة أو عقــد بينــي وبــن مورثــه ثالث ـاً‪ :‬لقــد مت اتهامــي بأننــي غــررت‬\n‫وضللــت وخدعــت مورثــه وإنــي اســتغليت وظيفتــي وهــذه االتهامــات إذا‬\n‫لــم يقــدم مــا يثبتهــا فأننــي أطلــب مــن فضيلتكــم وأنتــم رمــز العدالــة‬\n‫وخليفــة اهلل يف أرضــه بتطبيــق املــادة الرابعــة مــن قواعــد احلــد مــن آثــار‬\n‫الشــكاوى الكيديــة والدعــاوى الباطلــة واملتضمــن أن مــن تقــدم‬\n‫بدعــوى خاصــه وثبــت للمحكمــة كــذب املدعــي يف دعــواه فللقاضــي‬\n‫أن ينظــر يف تعزيــره وللمدعــى عليــه املطالبــة بالتعويــض عمــا حلقــه مــن‬\n‫ضــرر بســبب هــذه الدعــوى وكذلــك مــا تضمنتــه الالئحــة التنفيذيــة‬\n‫لنظــام املرافعــات الشــرعية مــن اســاليب للوصــول ملأربــه ومبتغــاه‪ ،‬وهــو‬\n‫مــا حصــل بالفعــل كمــا ذكرنــا يف الئحة االدعاء املنظــورة لفضيلتكم‬\n‫مبحاولتــه أن ال يظهــر يف الصــورة إال متأخــر ًا لــذر الرمــاد يف العيــون‬\n‫هــذا مــا لــدي مــن إجابــة وحضــر يف هذه اجللســة (‪ )....‬الســعودي بالســجل‬\n\n\n                                                                                      ‫‪138‬‬\n\f      ‫املدنــي رقــم (‪ )....‬وقــال إننــي اشــتريت األرض محــل الدعــوى مــن مــورث‬\n      ‫املدعــن لنفســي يف عــام تاريــخ ‪1414/10/22‬ه ـ وســلمت ثمنهــا ومت‬\n      ‫اإلفــراغ لــي ومــا ذكــره املدعــي وكالــة غيــر صحيــح وقــد بعــت ربــع‬\n      ‫هــذه األرض مشــاعة (‪ )....‬يف عــام ‪1415‬ه ـ وربيــع آخــر ‪ ....‬هــذا احلاضــر‬\n      ‫يف عــام ‪1417‬ه ـ و مت التهميــش علــى الصــك الــذي بيــدي بذلــك و الصــك‬\n      ‫برقــم ‪ 1/ 845‬وتاريــخ ‪1414/10/22‬ه ـ كمــا قمــت ببيــع ربــع ثالــث‬\n      ‫مشــاع علــى أخويــي الشــقيقني (‪ )....‬و (‪ )....‬وقــد متــت املقاســمة فيمــا‬\n      ‫بيننــا وكل واحــد منــا نصيبــه حتــت يــده ولكــن الصــك مشــاع ومت‬\n      ‫عمــارة كل جــزء بالكامــل وال أوافــق علــى مــا يطالــب بــه املدعــن علمــا‬\n      ‫أننــي اشــتريت مــن مــورث املدعــن وكان مخطــط املنطقــة رقــم ‪4/400‬‬\n      ‫جنــوب (‪ )....‬معتمــد ومعــروف مــن اجلميــع وكانــت عالقتــي مبــورث‬\n      ‫املدعــي قويــة ويأتــي لزيارتــي باســتمرار ولــم يطالبنــي بشــيء وقــال‬\n      ‫املدعــى عليــه ‪ ....‬إننــي اســتلمت الربــع اخلــاص بــي وكان عبــارة كثبــان‬\n      ‫مــن الرمــال وقمــت بعمارتــه وبنــاء ســكن خــاص وأحــواش وزراعتــه‬\n      ‫بالنخيــل بالكامــل وحفــر اآلبــار رقــم ( ‪ ) 5 / 4‬التــي تنــص علــى أنــه (إذا‬\n      ‫ثبــت لناظــر القضيــة أن دعــوى املدعــي كيديــه حكــم بــرد الدعــوى ولــه‬\n      ‫احلكــم بتعزيــر املدعــي مبــا يردعــه) رابعـاً‪ :‬صاحــب الفضيلــة مــن املعلــوم‬\n      ‫لــدى فضيلتكــم أن العبــرة باحلــال وليــس باملــآل ولفضيلتكم االســتعانة‬\n      ‫بــذوي اخلبــرة للتأكــد مــن األســعار يف تلــك املنطقــة يف ذلــك احلــن واآلن‬\n      ‫كمــا نفيــد فضيلتكــم عــن عــدم الصــدق الــوارد يف املذكــرة املســلمة‬\n      ‫مــن وكيــل املدعــي يف جلســة ‪1434/1/11‬ه ـ حيــث ذكــر نص ـ ًا (أن‬\n      ‫الســعر بعــد اعتمــاد التخطيــط ارتفــع بحيــث أصبــح يــوازي قيمتهــا‬\n      ‫حالي ـاً) وأنــا اطلــب مخاطبــة األمانــة للتأكــد مــن أن املخطــط معتمــد‬\n\n\n‫‪139‬‬\n\f‫قبــل شــرائي لــأرض بأكثــر مــن خمــس عشــرة ســنه أي قبــل متلكهــا‬\n‫املدعــي بأننــي تــرددت علــى‬\n                            ‫مــن مــورث املدعــي خامس ـاً‪ :‬ذكــر وكيــل ّ‬\n‫مــورث موكليــه يف نفــس الوقــت مت إرســال أشــخاص كــي ال أبــان يف‬\n‫الصــورة وأنــا لــم اشــتري مــن مــورث موكلــه ولــم أره علــى اإلطــاق يف‬\n‫حياتــي كمــا ذكــر أيض ـ ًا أنــه مت تنفيــذ املخطــط املعتمــد بعــد ســنتني‬\n‫مــن شــراء األرض مــن قبــل ‪ ....‬مــع العلــم بــأن األرض مخططــه ومعتمــده‬\n‫ومعلومــة لــدى جميــع املكاتــب العقاريــة بشــوارعها واحمليــط بهــا‬\n‫لوقوعهــا مــن ضمــن مخطــط ‪ 400/4‬واملســمى بالدخــل احملــدود منــذ‬\n‫عــام ‪1404/1/16‬ه ـ أي قبــل الشــراء بعشــر ســنوات ؟ فــكان مــن‬\n‫األجــدى واألحــق أن يتأكــد وكيــل املدعــي مــن أقــرب مكتــب عقــاري‬\n‫يف األحســاء وأنــا أطلــب مــن فضيلتكــم احلكــم بتعزيــره وإثباتــه يف‬\n‫ضبــط القضيــة وفقــا لالئحــة التنفيذيــة رقــم ( ‪ ) 7 / 4‬هــذا ردي علــى‬\n‫دعواهــم وأمتســك بحقــي بتعزيــره والتعويــض املســاوي مبــا يقــرره الشــرع‬\n‫احلنيــف) وبعــرض ذلــك علــى املدعــي وكالــة قــال إننــي أحضــرت إجابتي‬\n‫علــى مــا ذكــره املدعــى عليــه يف اجللســة املاضيــة مكتوبــة و أطلــب‬\n‫كتابــة نصهــا أو ًال ‪ :‬مــا ذكــره املدعــى عليــه يف الفقــرة األولــى يف‬\n‫إجابتــه مــن أن هنــاك اختالف ـ ًا يف اســم موكلــي يف الئحــة االدعــاء‬\n‫املقدمــة مــن لدنــا بالوكالــة ضــد املذكــور لديكــم فــإن احلقيقــة انــه‬\n‫ليــس هنــاك اختالفـ ًا يف اســم موكلــي ملــن تأمــل يف اســمه يف الوكالــة‬\n‫الشــرعية الصــادرة منــه لنــا املرفــق صورتهــا يف املعاملــة فهــو‪)....( /‬‬\n‫ومبوجــب صــورة ســجله يف بطاقــة األحــوال املدنيــة املرفــق صورتهــا‬\n‫لديكــم املطابــق الســمه يف الئحــة االدعــاء ويف الوكالــة الشــرعية‬\n‫املرفقــة باملعاملــة ‪ ، ،‬ومبوجــب صــك حصــر الورثــة املرفــق صورتــه‬\n\n\n                                                                                 ‫‪140‬‬\n\f      ‫باملعاملــة ومبوجــب صــور وكاالت موكلــي وهــم بقيــة ورثــة ‪ ....‬ومــن‬\n      ‫ضمــن الورثــة (‪ )....‬املذكــور (‪ )....‬فخــذ موكلــي وقبيلتــه ثاني ـاً‪ :‬أن مــا‬\n      ‫ذكــره املدعــى عليــه يف الفقــرة الثانيــة مــن أنــه ال توجــد أرض (‪)....‬‬\n      ‫فهــذا غيــر صحيــح ‪ ،‬فكلمــة (‪ )....‬وجنــوب غــرب (‪ )....‬وردت يف صــك‬\n      ‫األرض املدعــى بهــا واملذكــور رقمــه يف صحيفــة ادعــاء موكلــي برقــم‬\n      ‫‪ 845‬وتاريــخ ‪1414/10/22‬ه ـ وهــي محــل هــذا النــزاع ‪ ،‬وهــي بيــت‬\n      ‫القصيــد يف هــذه الدعــوى ‪ ،‬وهــي نفــس األرض التــي أقــر املدعــى عليــه‬\n      ‫يف جوابــه علــى دعــوى موكلــي يف الفقــرة الثانيــة والرابعــة واخلامســة أنــه‬\n      ‫اشــتراها مــن (‪ )....‬ثالث ـاً‪ :‬وأمــا محاولــة املدعــى عليــه يف الفقــرة الثالثــة‬\n      ‫نفــي تغريــره وتظليلــه وغبنــه ملــورث موكلــي واســتغالل وظيفتــه يف ذلــك‬\n      ‫‪ ،‬فهــو غيــر صحيــح‪ ،‬ودليــل غــن املدعــى عليــه ملــورث موكلــي أنــه قــد‬\n      ‫اقتطعــت الدولــة مــن أرض موكلــي بعــد شــرائها مــن قبــل املدعــى عليــه‬\n      ‫مــا يقــارب أحــد عشــر ألــف متــر ًا مربعـ ًا وعوضتــه الدولــة عــن ذلــك اجلــزء‬\n      ‫اليســير مبــا يعــادل أضعــاف تلــك املســاحة بعــدد كبيــر مــن األراضــي‬\n      ‫مــن مخطــط الدخــل احملــدود املجــاور ألرض موكلــي واملدونــة أرقامهــا‬\n      ‫يف صــك األرض املدعــى بهــا ‪ ،‬وميكــن لفضيلتكــم التحقــق ممــا ذكــر‬\n      ‫عــن عــدد األراضــي املعوضــة للمدعــى عليــه ومســاحاتها وأســعارها مــن‬\n      ‫قبــل أمانــة األحســاء ومكاتــب العقــار‪ ،‬واذا كان التعويــض عــن مــا‬\n      ‫يقــارب عشــر األرض قــد بلــغ هــذا العــدد الكبيــر مــن هــذه األراضــي أال‬\n      ‫يــدل ذلــك علــى غــن املدعــى عليــه ملــورث موكلــي ؟ حيــث اشــترى‬\n      ‫األرض بالتغريــر وبثمــن بخــس ‪ ،‬فمــا ظــن فضيلتكــم بقيمــة األرض‬\n      ‫ا عــن مــا‬  ‫كلهــا آنــذاك قياس ـ ًا مبقــدار تعويــض مــا أقتطــع منهــا وفض ـ ً‬\n      ‫تبقــى منهــا بعــد االقتطــاع والبالــغ تقريب ـ ًا (‪ )%85‬مــن مســاحتهاـ رابع ـ ًا ‪:‬‬\n\n\n‫‪141‬‬\n\f‫وأمــا مــا ذكــره املدعــى عليــه يف الفقرتــن الثانيــة واخلامســة يف إجابتــه‬\n‫أنــه لــم يشــتر مــن مــورث موكلــي أي أرض ‪ ،‬وال توجــد أي عالقــة أو‬\n‫عقــد بينــه وبــن مــورث موكلــي ‪ ،‬وأنــه لــم يتــردد عليــه ولــم يــره علــى‬\n‫اإلطــاق يف حينــه فهــو كالم عــار مــن الصحــة متام ـ ًا ‪ ،‬حيــث يوجــد‬\n‫لدينــا شــهود عــدول ينفــون ادعــاءه وزعمــه بعــدم معرفتــه ملــورث موكلــي‬\n‫‪ ،‬ويثبتــون أنــه تــردد عليــه مــرات ‪ ،‬والتقــى بــه يف مزرعتــه وهــي نفــس‬\n‫األرض املدعــى بهــا املذكــورة هنــا ‪ ،‬كمــا التقــى بــه مرتــن يف بيــت‬\n‫مــورث موكلــي ‪ ،‬وأنــه يعــرف مــورث موكلــي معرفــة جيــدة ‪ ،‬وقــد‬\n‫طلــب مــن الشــهود أن يتوســطوا يف الضغــط علــى مــورث موكلــي مــن‬\n‫أجــل بيــع األرض املدعــى بهــا مــع ذكــر عيوبهــا واخفــى مــا يــدور يف‬\n‫أروقــة أمانــة األحســاء آنــذاك مــن مخاطبــات ومراســات العتمــاد‬\n‫املشــاريع العمرانيــة يف حــن أن املدعــى عليــه يعلــم ذلــك لكونــه موظفـ َا‬\n‫يف البلديــة وبحكــم عالقاتــه مــع زمالئــه مبــا يجــري فيهــا مــن التخطيط‬\n‫العمرانــي املزمــع اعتمــاده آنــذاك يف املنطقــة املذكــورة وقــرب انتــزاع‬\n‫الدولــة األرض املذكــورة لتنفيــذ شــارع عــرض ســتني بطــول ‪ 400‬متــر‬\n‫غــرب األرض املدعــى بهــا وشــارع آخــر عــرض اربعــن شــرق الــذي تقــع‬\n‫عليــه مزرعــة موكلــي اآلن ‪ ،‬وهــو مــا حصــل بالفعــل بعــد مــا يقــارب‬\n‫ســنتني مــن شــراء األرض مباشــرة ‪ ،‬فاملخاطبــات كانــت تتــداول بــن‬\n‫أمانــة األحســاء ووزارة الشــئون البلديــة قبــل شــراء أرض موكلــي يف‬\n‫عــام ‪1414‬ه ـ وميكــن لفضيلتكــم مخاطبــة أمانــة األحســاء لإلفــادة عن‬\n‫عمــل املدعــى عليــه آنــذاك يف األمانــة وقبــل وأثنــاء وقــت شــرائه لــأرض‬\n‫املدعــى بهــا ‪ ،‬وعــن بدايــة تواريــخ التخطيــط واملراســات واالعتمــادات‬\n‫للمشــاريع يف املنطقــة الواقعــة بهــا أرض مــورث موكلــي ـ خامسـ ًا ‪ :‬امــا‬\n\n\n                                                                                   ‫‪142‬‬\n\f      ‫مــا ذكــره املدعــى عليــه يف الفقــرة الرابعــة مــن اجابتــه علــى دعــوى‬\n      ‫موكلــي مــن أن األرض تقــع ضمــن مخطــط معتمــد قبــل شــرائه لــأرض‬\n      ‫بأكثــر مــن خمســة عشــر ســنة منــذ عــام ‪ 1400‬وهــو مخطــط ( ‪400 / 4‬‬\n      ‫) املســمى مخطــط (‪ )....‬فهــو محاولــة منــه لإليهــام والتضليــل وإدخــال‬\n      ‫ا يف هــذا‬ ‫أرض موكلــي ضمــن هــذا املخطــط الــذي هــو معتمــد فع ـ ً‬\n      ‫التاريــخ لكــي تنــدرج أرض موكلــي حتــت تاريــخ اعتمــاده ليكــون قبــل‬\n      ‫شــرائه لــأرض فهــو أمــر غيــر صحيــح البتــة ‪ ،‬والصحيــح أن مخطــط‬\n      ‫(‪ )....‬املذكــور مســتقل اســتقال ًال تام ـ ًا عــن أرض موكلــي التــي ال‬\n      ‫يشــملها هــذا املخطــط مطلق ـ ًا ‪ ،‬ومــن ثــم ينتفــي ادعــاؤه بــأن أرض‬\n      ‫موكلــي مندرجــة يف هــذا املخطــط وقبــل شــرائه لهــا بأكثر من خمســة‬\n      ‫عشــر ســنة وميكــن لفضيلتكــم ملخاطبــة أمانــة األحســاء للتحقــق مــن‬\n      ‫هــذه احلقيقــة التــي ذكرناهــا لدحــض ادعــاء املدعــى عليــه ومحاولتــه‬\n      ‫تضليــل العدالــة ‪ ،‬ويثبــت لفضيلتكــم مــا ذكرنــاه يف دعوانــا مــن أن‬\n      ‫املدعــى عليــه علــى علــم بتوجــه األمانــة لتخطيــط هــذه الشــوارع علــى‬\n      ‫أرض موكلــي واعتمادهــا فعمــل علــى شــرائها يف ظــل جهــل موكلــي‬\n      ‫بذلــك واشــتراها بأقــل مــن ثمنهــا ‪ ،‬واســتخدم املدعــى عليــه مــا ذكرنــاه‬\n      ‫مــن اســاليب للوصــول ملأربــه ومبتغــاه ‪ ،‬وهــو مــا حصــل بالفعــل كمــا‬\n      ‫ذكرنــا يف الئحــة االدعــاء املنظــورة لفضيلتكــم مبحاولتــه أن ال يظهــر‬\n      ‫يف الصــورة إال متأخــر ًا لــذر الرمــاد يف العيــون هــذا مــا لــدي مــن إجابــة‬\n      ‫وحضــر يف هــذه اجللســة (‪ )....‬الســعودي بالســجل املدنــي رقــم (‪ )....‬وقــال‬\n      ‫إننــي اشــتريت األرض محــل الدعــوى مــن مــورث املدعــن لنفســي يف عــام‬\n      ‫تاريــخ ‪1414/10/22‬ه ـ وســلمت ثمنهــا ومت اإلفــراغ لــي ومــا ذكــره‬\n      ‫املدعــي وكالــة غيــر صحيــح وقــد بعــت ربــع هــذه األرض مشــاعة ‪ ....‬يف‬\n\n\n‫‪143‬‬\n\f‫عام‪1415‬ه ـ ربيــع آخــر ‪ ....‬هــذا احلاضــر يف عــام ‪1417‬ه ـ ومت التهميــش‬\n‫علــى الصــك الــذي بيــدي بذلــك و الصــك برقــم ‪ 1/ 845‬و تاريــخ‬\n‫‪1414/10/22‬ه ـ كمــا قمــت ببيــع ربــع ثالــث مشــاع علــى أخويــي‬\n‫الشــقيقني (‪ )....‬وقــد متــت املقاســمة فيمــا بيننــا وكل واحــد منــا نصيبــه‬\n‫حتــت يــده ولكــن الصــك مشــاع ومت عمــارة كل جــزء بالكامــل وال‬\n‫أوافــق علــى مــا يطالــب بــه املدعــن علمــا أننــي اشــتريت مــن مــورث‬\n‫املدعــن وكان مخطــط املنطقــة رقــم ‪ 4/400‬جنــوب ‪ ....‬معتمــد و‬\n‫معــروف مــن اجلميــع و كانــت عالقتــي مبــورث املدعــي قويــة ويأتــي‬\n‫لزيارتــي باســتمرار ولــم يطالبنــي بشــيء وقــال املدعــى عليــه ‪ ....‬إننــي‬\n‫اســتلمت الربــع اخلــاص بــي وكان عبــارة كثبــان مــن الرمــال وقمــت‬\n‫بعمارتــه وبنــاء ســكن خــاص وأحــواش وزراعتــه بالنخيــل بالكامــل‬\n‫وحفــر اآلبــار وبعــد تأمــل مــا ســبق ومت ضبطــه ومبــا أن املدعــن مــن ورثــة‬\n‫(‪ )....‬يطالبــون املدعــى عليهمــا بــرد األرض محــل الدعــوى لهــم وإبطــال‬\n‫بيــع مورثهــم أو دفــع مــا يــوازي قيمتهــا ودفــع التعويــض لهــم مــن املقتطــع‬\n‫مــن األرض بدعــوى الغــن يف البيــع والتحايــل والتضليــل ومبــا أن هــذه‬\n‫ا عــن بينتهــا ملــا يأتــي ‪ :‬أو ًال ‪ :‬أن مــورث‬\n                                                ‫الدعــوى غيــر مقبولــة فض ـ ً‬\n‫املدعــن بــاع األرض محــل الدعــوى يف تاريــخ ‪1414/10/22‬ه ـ وأســتلم‬\n‫الثمــن وبقــي علــى هــذا الوضــع دون معارضــه حتــى وفاتــه عــام ‪1431‬ه ـ‬\n‫ثاني ـاً‪ :‬مشــاهدة مــورث املدعــن للمشــتري يتصــرف يف هــذه األرض‬\n‫بالبيــع والبنــاء والغــرس والتعويــض مــن قبــل الدولــة واالســتالم وعــدم‬\n‫املعارضــة ممــا يــدل علــى قناعــة مــورث املدعــن بالثمــن وأن هــذا هــو‬\n‫ثمنهــا يف ذلــك الوقــت أو رضــاه بالغــن علــى فــرض حصولــه كمــا أنــه‬\n‫مبضــي هــذا الوقــت الطويــل جــد ًا انتقلت هذه األرض إلى عدة أشــخاص‬\n\n\n                                                                                      ‫‪144‬‬\n\f      ‫واســتلموا املبيــع وقامــوا بإحيائهــا ويف إبطــال البيــع ضــرر ال يخفــى‬\n      ‫وبالقــول بذلــك يلــزم منــه عــدم اســتقرار ملــك عنــد صاحبــه وهــذا غيــر‬\n      ‫مقبــول وبنــاء علــى ذلــك لــم يتبــن لــي حــق للمدعــن فيمــا يطالبــون بــه‬\n      ‫كمــا لــم يثبــت عنــدي أن هــذه الدعــوى مــن الدعــاوي الكيديــة وبذلــك‬\n      ‫حكمــت وبعرضــه علــى اجلميــع قــرر املدعــى عليهمــا قناعتهمــا باحلكــم‬\n      ‫فيمــا قــرر املدعــي وكالــة عــدم قناعتــه وطلــب االســتئناف ومت إفهامــه‬\n      ‫باملراجعة يف يوم الثالثاء املوافق ‪1434/7/4‬هـ الســتالم نســخة احلكم‬\n      ‫وتقــدمي االعتــراض عليــه خــال ثالثــن يــوم وإال ســقط حــق املدعــن يف‬\n      ‫االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل‬\n                                     ‫على نبينا محمد وعلى آله وصحبه أجمعني‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائرة احلقوقيــة األولى يف محكمة‬\n      ‫االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة األحســاء برقــم ‪ 33/1906735‬وتاريــخ‬\n      ‫‪1434/8/8‬ه واملقيــدة لــدى احملكمــة برقــم ‪ 341962874‬وتاريــخ‬\n      ‫‪1434/8/14‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ (‪)....‬‬\n      ‫املســجل برقــم ‪ 34258649‬وتاريــخ ‪1434/7/3‬ه اخلــاص بدعــوى ورثــة‬\n      ‫(‪ )....‬ضــد (‪ )....‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ ،‬ولبيانــه‬\n                               ‫حــرر يف ‪1434/11/19‬هــ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪145‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":133,"source_page_end":145,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e3511be040c0974a1182551e67c5619c41f76aec53698c2d88b6b856d6b918c","normalized_text_hash":"e90e10555e1f5f958c471ca5206970e25f7bd4df58001d0cfd30de75cf0b2203","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p133-34258649"},{"id":"c200951e-f325-5172-a362-72a78bb7fd0b","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -بيع سيارة -فسخ البيع لعيب وغن يف الثمن -تقدير ثمن املبيع عن طريق قسم اخلبراء -ثبوت الغن الفاحش يثبت خيار الفسخ -احلكم بالفسخ ورد قيمة املبيع .","document_number":"34192793","case_number":"33687025","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"بيع -عقد -بيع سيارة -فسخ البيع لعيب وغن يف الثمن -تقدير ثمن املبيع عن طريق قسم اخلبراء -ثبوت الغن الفاحش يثبت خيار الفسخ -احلكم بالفسخ ورد قيمة املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34192793 :‬‬\n                   ‫َر ْق ُم الدعوى‪33687025 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34290958‬تاريخه‪1434/8/8 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــد ‪ -‬بيــع ســيارة ‪ -‬فســخ البيــع لعيــب وغــن يف الثمــن ‪ -‬تقديــر‬\n‫ثمــن املبيــع عــن طريــق قســم اخلبــراء ‪ -‬ثبــوت الغــن الفاحــش يثبــت‬\n                     ‫خيــار الفســخ ‪ -‬احلكــم بالفســخ ورد قيمــة املبيــع ‪.‬‬\n\n\n\n\n ‫وجود الغنب كاف يف ثبوت حق خيار الفسخ‪ .‬شرح املنتهى (‪.)195/3‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن املدعــى عليــه ســيارة موصوفــة يف‬\n‫الدعــوى وســلمه ثمنهــا وبعــد اســتالمه للســيارة اتضــح لــه أن بهــا عيوبــا‬\n‫كثيــرة مذكــورة يف دعــواه لــم يخبــره املدعــى عليــه بهــا ســوى وجــود‬\n‫عيــب يف املاكينــة‪ ،‬كمــا اتضــح لــه أن ســعر الســيارة احلقيقــي أقــل‬\n‫بكثيــر مــن الثمــن الــذي اشــتراها بــه وأنــه غــن فيهــا غبنــا فاحشــا‪،‬‬\n‫لــذا طلــب احلكــم بفســخ البيــع وإلــزام املدعــى عليــه بإعــادة الثمــن الــذي‬\n‫دفعــه لــه كامــا ‪ ،‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n‫ســوى شــراء الســيارة بالثمــن املذكــور وأنــه أخبــره بوجــود عيــب يف‬\n‫املاكينــة ‪ ،‬قــررت احملكمــة تكليــف قســم اخلبــراء بتقديــر ثمــن‬\n‫الســيارة فأفــادوا بــأن الثمــن الــذي بيعــت بــه فيــه غــن ‪ ،‬وجــود الغــن‬\n\n                                                                                      ‫‪146‬‬\n\f      ‫كاف يف ثبــوت حــق خيــار الفســخ كمــا أن الغــن يف ثمــن الســيارة‬\n      ‫محــل الدعــوى غــن فاحــش خــارج عــن العــادة ‪ ،‬قضــت احملكمــة بفســخ‬\n      ‫بيــع الســيارة املوصوفــة يف الدعــوى وألزمــت املدعــى عليــه بإعــادة ثمنهــا‬\n      ‫الــذي اســتلمه إلــى املدعــي وأن علــى املدعــي أن يســلم الســيارة للمدعــى‬\n      ‫عليــه ‪ ،‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه ‪ ،‬قــررت‬\n                                  ‫محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القائــم بعمــل املكتب القضائي‬\n      ‫الســادس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة القطيــف برقــم ‪ 33687025‬وتاريــخ ‪1433/12/01‬ه ـ‬             ‫َ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 332169897‬وتاريخ ‪1433/12/1‬هـ ففي يوم‬\n      ‫الســبت املوافق ‪1434/03/28‬هـ افتتحت اجللســة الســاعة (‪ )8:00‬وفيها‬\n      ‫حضــر (‪ )........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬وحضــر حلضــوره‬\n      ‫املدعــى عليــه (‪ )........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬ونظــر ًا‬\n      ‫لتعــارض موعــد هــذه اجللســة مــع جلســة أخــرى بنفــس الوقــت لــدي يف‬\n      ‫مكتبــي املكتــب القضائــي الثامــن وعليــه فقــد رفعــت اجللســة ثــم لــدي‬\n      ‫العامــة مبحافظــة القطيــف ويف يــوم‬  ‫ّ‬     ‫أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫األربعــاء املوافــق ‪1434/04/17‬ه ـ افتتحــت اجللســة وفيها حضــر (‪)........‬‬\n      ‫يحمــل الســجل املدنــي رقــم (‪ )........‬وادعــى علــى احلاضــر معــه (‪)........‬‬\n      ‫ا يف دعــواه لقــد اشــتريت مــن املدعــى عليــه ســيارة نــوع (‪ )........‬صنــع‬\n                                                                                    ‫قائـ ً‬\n      ‫عــام (‪ )........‬اللــون (‪ )........‬رقــم اللوحــة (‪ )........‬بثمــن إجمالــي قــدره‬\n      ‫ســبعة وخمســون ألفــا وأربعمائــة ريــال وبعــد اســتالمي الســيارة أتضــح‬\n\n‫‪147‬‬\n\f‫لــي أن بهــا عيوبـ ًا كثيــرة منهــا تهريــب كارتيــر املاكينــة وتغيــر صوفــة‬\n‫املاكينــة األماميــة وبحاجــة لتصفيــة املاكينــة وإلصــاح املكيــف‬\n‫وتغييــر املســاعدات األماميــة واخللفيــة واملقصــات وبهــا مشــاكل يف‬\n‫الفرامــل وحتتــاج وزن أذرعــة وبهــا صــوت طنجــرة اجليــر كمــا اتضــح‬\n‫ان بهــا صدمــة يف مقدمــة الســيارة مــن جهــة حســاس االيربــاق حســب‬\n‫تقريــر (‪ )........‬لفحــص الســيارات بالكمبيوتــر ولــم يخبرنــي املدعــى‬\n‫عليــه بهــذه العيــوب عــدا الصوفــة كمــا اتضــح لــي أن ســعر الســيارة‬\n‫أقــل بكثيــر مــن الثمــن الــذي اشــتريته بــه وأننــي غبنــت فيهــا غبنــا‬\n‫فاحشـ ًا لــذا كلــه أخبــرت املدعــى عليــه بأنــي ال أرغــب بالســيارة وأطلــب‬\n‫الفســخ فرفــض لــذا أطلــب احلكــم بفســخ البيــع والزامــه بإعــادة الثمــن‬\n‫الــذي دفعتــه كامــا هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال ‪:‬‬\n‫مــا ذكــره املدعــي بدعــواه مــن شــراء الســيارة بالثمــن املذكــور وأننــي‬\n‫أخبرتــه بصوفــة املاكينــة فذلــك صحيــح وأمــا مــا عــدا ذلــك فكلــه‬\n‫غيــر صحيــح متامــا وأرفــض فســخ البيــع وأطلــب رد دعــواه هــذا جوابــي‬\n‫هــذا وقــد ســبق أن متــت الكتابــة إلــى قســم اخلبــراء بهــذه احملكمــة‬\n‫باخلطــاب رقــم ‪ 332169897‬يف ‪1434/01/06‬ه ـ وذلــك لبيــان ثمــن‬\n‫السيارة وردني اجلواب باخلطاب رقم ‪ 332169897‬يف ‪1434/01/17‬هـ‬\n‫وبرفقــه احملضــر املعــد منهــم برقــم ‪ 8‬يف ‪1434/01/13‬ه ـ وقــد تضمــن‬\n‫أن ثمــن الســيارة يف الوقــت الراهــن ثالثــون ألــف (‪)30.000‬ريــال والثمــن‬\n‫الــذي بيعــت بــه فيــه غــن وبعرضــه علــى املدعــى عليــه قــال إن مــا تضمنــه‬\n‫التقريــر غيــر صحيــح ثــم قفلــت املرافعــة وبعــد ســماع الدعــوى وجوابهــا‬\n‫وحيــث انكــر املدعــى عليــه الدعــوى وأثبــت محضــر قســم اخلبــراء‬\n‫باحملكمــة وجــود غــن بأكثــر مــن ســبعة وعشــرين ألــف ريــال وهــو‬\n\n\n                                                                                     ‫‪148‬‬\n\f      ‫غــن فاحــش خــارج عــن العــادة حيــث إنــه يقــارب قيمــة الســيارة احلقيقيــة‬\n      ‫وهــي ثالثــون ألــف ريــال ووجــود الغــن كاف بثبــوت حــق خيــار الفســخ‬\n      ‫كمــا قــرره الفقهــاء رحمهــم اهلل تعالــى كمــا يف شــرح املنتهــى ‪195/3‬‬\n      ‫لــذا كلــه فقــد حكمــت بفســخ بيــع الســيارة املوصوفــة يف الدعــوى‬\n      ‫علــى املدعــي بنــاء علــى طلبــه وألزمــت املدعــى عليــه بإعــادة ثمنهــا الــذي‬\n      ‫اســتلمه وقــدره ســبعة وخمســون ألفــا وأربعمائــة ريــال إلــى املدعــي وأن‬\n      ‫علــى املدعــي أن يســلم الســيارة للمدعــى عليــه وبعرضــه قنــع بــه املدعــي‬\n      ‫ولــم يقنــع املدعــى عليــه طالبــا متييــزه فافهــم باملراجعــة الســتالم نســخة‬\n      ‫احلكــم يــوم الثالثــاء املوافــق ‪1434/4/23‬ه ـ ولــه حــق تقــدمي االعتــراض‬\n      ‫خــال ثالثــن يومــن مــن التاريــخ احملــدد الســتالمه نســخة احلكــم وإذا‬\n      ‫لــم يتقــدم الالئحــة االعتراضيــة خــال هــذه املــدة فإنــه يســقط حقــه‬\n      ‫فيــه ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد هــذا‬\n      ‫اليــوم الســبت املوافــق ‪1434/6/24‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫العاشــرة والربــع وقــد وردتنــي الالئحــة االعتراضيــة املقدمــة مــن لفتــن‬\n      ‫واملقيــدة بهــذه احملكمــة برقــم ‪ 341201832‬يف ‪1434/5/18‬ه ـ وقــد‬\n      ‫جــرى اطالعــي عليهــا ولــم أجــد بهــا مؤثــرا علــى حكمــي وصلــى اهلل‬\n        ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/6/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد املوافــق ‪1434/8/21‬ه ـ‬\n      ‫افتتحــت اجللســة يف متــام الســاعة احلاديــة عشــرة والنصــف وكانــت‬\n      ‫املعاملــة قــد عــادت مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫بخطــاب ســماحة رئيســها رقــم ‪ 34/1658434‬يف‪1434/8/10‬ه ـ‬\n\n\n‫‪149‬‬\n\f‫مرفــق بهــا القــرار الصــادر مــن قضــاة الدائــرة احلقوقيــة الثانيــة ق‪2/‬‬\n‫مبحكمــة االســتئناف برقــم ‪ 34290958‬يف ‪1434/8/8‬ه ـ ونــص‬\n‫احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق ) اهــ‪ .‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                         ‫يف ‪1434/8/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪150‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":146,"source_page_end":150,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1fa226ef88c82066322f67c9fda9d9cbfa58de649dbec974af2108ff49040d4f","normalized_text_hash":"b2fd5a540b6ac4badc2ab67e6eadd6fd508a0461fc909f6d7e01cfc05da89e6d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p146-34192793"},{"id":"126f2c71-3898-575c-8de1-86fce19a0029","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -عقار -مطالبة بفسخ عقد البيع -مطالبة بإخاء عقار -عقد بيع مت قبل استخراج صك امللكية -األصل حمل العقود على الصحة -تصحيح عقد البيع -عقد البيع ال ينفسخ اال برضا الطرفن -احلكم برد دعوى طلب فسخ عقد البيع واإللزام بسداد باقي ثمن املبيع .","document_number":"3455007","case_number":"33712572","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باجلبيل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/3","year":"1434","subject":"بيع -عقد -عقار -مطالبة بفسخ عقد البيع -مطالبة بإخاء عقار -عقد بيع مت قبل استخراج صك امللكية -األصل حمل العقود على الصحة -تصحيح عقد البيع -عقد البيع ال ينفسخ اال برضا الطرفن -احلكم برد دعوى طلب فسخ عقد البيع واإللزام بسداد باقي ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3455007 :‬‬\n                         ‫َر ْق ُم الدعوى‪33712572 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34200451‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬عقــار ‪ -‬مطالبــة بفســخ عقــد البيــع ‪ -‬مطالبــة بإخــاء‬\n      ‫عقــار ‪ -‬عقــد بيــع مت قبــل اســتخراج صــك امللكيــة ‪ -‬األصــل حمــل‬\n      ‫العقــود علــى الصحــة ‪ -‬تصحيــح عقــد البيــع ‪ -‬عقــد البيــع ال ينفســخ‬\n      ‫اال برضــا الطرفــن ‪ -‬احلكــم بــرد دعــوى طلب فســخ عقــد البيع واإللزام‬\n                                                    ‫بســداد باقــي ثمــن املبيــع ‪.‬‬\n\n\n\n\n                  ‫‪ .1‬القاعدة ( األصل حمل العقود على الصحة ما أمكن ) ‪.‬‬\n        ‫‪ .2‬القاعدة ( املطلق يبقى على إطالقه ما لم يقيد بنص أو داللة) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه بــاع للمدعــى عليــه عقــاره املوصــوف يف نــص القضيــة‬\n      ‫مببلــغ قــدره مليــون وأربعمائــة ألــف ريــال وقــد ســلم املدعــى عليــه‬\n      ‫للمدعــي مــن قيمــة العقــار مبلغ ـ ًا وقــدره ثمامنائــة ألــف ريــال والباقــي‬\n      ‫يســلم عنــد اســتخراج صــك العقــار حيــث إن العقــار وقــت إمتــام البيــع‬\n      ‫لــم يتــم اســتخراج صــك ملكيتــه وقــرر املدعــي أن إجــراءات اســتخراج‬\n      ‫صــك العقــار قــد انتهــت وخــرج صــك العقــار ومت إبــاغ املدعــى عليــه‬\n      ‫بذلــك وتزويــده بصــورة مــن الصــك وقــد تضمــن العقــد يف حالــة تأخــر‬\n      ‫املشــتري عــن تســليم باقــي املبلــغ فــإن للبائــع حــق الفســخ وإلغــاء املبايعــة‬\n‫‪151‬‬\n\f‫والتصــرف يف امللكيــة والعربــون الــذي دفــع املشــتري ال يــرد وطلــب‬\n‫املدعــي تطبيــق بنــود العقــد وإخــراج املدعــى عليــه مــن العقــار ‪ ،‬أجــاب‬\n‫املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أن الصــك تأخــر إخراجــه‬\n‫مــن قبــل املدعــي قرابــة الســنتني ونتيجــة لذلــك لــم يكــن املبلــغ املتبقــي‬\n‫موجــود ًا وقتهــا وقــرر انــه راغــب يف البيــت وليســت لديــه رغبــة يف فســخ‬\n‫العقــد وانــه مســتعد بتســليم باقــي املبلــغ ‪ ،‬قــرر املدعــي مصادقتــه علــى‬\n‫أن الصــك تأخــر ولكــن ذلــك مــن الشــركة املســئولة التــي يعمــل بهــا‬\n‫املدعــي ‪ ،‬مت اطــاع ناظــر القضيــة علــى صــك امللكيــة وعقــد املبايعــة‬\n‫ومت االستفســار عــن ســجل الصــك مــن مصــدره ‪ ،‬قــرر ناظــر القضيــة‬\n‫أن العقــد بــن الطرفــن عقــد مبايعــة وهــو مــن العقــود الالزمــة والتــي‬\n‫ال تنفســخ إال برضــا مــن الطرفــن ومــا طلبــه املدعــي مــن فســخ العقــد‬\n‫بســبب تأخــر املشــتري يف تســليم الثمــن غيــر وجيــه ألن العقــد نــص‬\n‫علــى أن باقــي الثمــن يدفــع عنــد اإلفــراغ كمــا نــص علــى أن البائــع‬\n‫هــو املســئول عــن حتريــر الصــك وأقــر املدعــي أن الصــك تأخــر بســبب‬\n‫خــارج عنــه ومبــا أن املدعــى عليــه راغــب يف العقــار ومســتعد بدفــع باقــي‬\n‫املبلــغ وقــد نــص أهــل العلــم علــى أن األصــل حمــل العقــود علــى الصحــة‬\n‫مــا أمكــن وإن املطلــق يبقــى علــى إطالقــه مــا لــم يقيــد بنــص أو داللــة‬\n‫فقــد صــدر احلكــم بــرد دعــوى املدعــي فســخ العقــد وإن عليــه املضــي يف‬\n‫العقــد واإلفــراغ للمدعــى عليــه وإن علــى املدعــى عليــه دفــع باقــي الثمــن‬\n‫حــا ًال عنــد طلــب املدعــي ‪ ،‬قــرر املدعــي عــدم القناعــة ‪ ،‬صــدر قــرار‬\n     ‫محكمــة االســتئناف باملنطقــة الشــرقية باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪152‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫باجلبيــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة باجلبيــل برقــم ‪ 33712572‬وتاريــخ ‪ 1433/12/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332276941‬وتاريــخ ‪ 1433/12/29‬ه ـ ففــي يــوم‬\n      ‫األحــد ‪ 1434/02/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n      ‫حضــر (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬وادعــى‬\n      ‫علــى احلاضــر معــه (‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ )....‬وبســؤاله عــن دعــواه قــدم مذكــرة بدعــواه وطلــب ضبطهــا وهــذا‬\n      ‫نصهــا‪ :‬افيــد فضيلتكــم بــان مت بيــع عقــار الكائــن يف ‪ ...‬يف ‪............‬‬\n      ‫شــارع ‪............‬منــزل ‪............‬مببلــغ وقــدرة مليــون واربــع مئــة الــف مت‬\n      ‫دفــع مبلــغ وقــدرة ثمامنائــة الــف والباقــي عنــد اســتخراج الصــك مــن‬\n      ‫الشــركة وقــدرة ســتمائة الــف ويف تاريــخ ‪1433/10/9‬ه ـ مت اســتخراج‬\n      ‫الصــك برقــم ‪ 832401000292‬وقبــل تســعة اشــهر بلغــت املشــتري‬\n      ‫بقــرب اســتخراج الصــك ويف رمضــان ايضــا وعنــد اســتالم الصــك بلغــت‬\n      ‫املشــتري يف تاريخــه واعطــي صــورة مــن الصــك ثــم طلــب منــي اســبوعان‬\n      ‫ويتــم االفــراغ واعطيتــه وقــت كايف أي مــا يقــارب الثالثــة اشــهر حتــى‬\n      ‫يتدبــر امــوره ولــم يتــم ذلــك حتــى تاريــخ كتابــة اخلطــاب الــى االمــارة ومــن‬\n      ‫خــال الفتــرة املاضيــة لــم يدلــي أي اهتمــام يف انهــاء املوضــوع واالكتفاء‬\n      ‫بإرســال الرســائل ويف العقــد الــذي مت االتفــاق عليــه بــن الطرفــن‬\n      ‫الصــادر مــن مكتــب ‪............‬العقــاري يلــزم الطرفــن وقــد اتبعــت جميــع‬\n      ‫البنــود كبائــع والتزمــت بهــا علمــا» مــن خــال الســنتني تكبــده خســائر‬\n\n‫‪153‬‬\n\f‫مــن ايجــارات وخســائر ماليــه ومــن اضــرار يف النقــل الــى مدينــة الدمــام‬\n‫وليس على املشــتري الى بند رقم ‪ 2‬واحد وهو يف حالة تأخير املشــتري‬\n‫عــن دفــع املبلــغ املتبقــي فــان للبائــع احلــق يف فســخ البيــع والغــاء املبايعــة‬\n‫والتصــرف يف ملكــه والعربــون الــذي دفعــه املشــتري ال يــرد اليــه وليــس‬\n‫لــه حــق املطالبــة ويف هــذي احلالــة اطلــب مــن فضيلتكــم بتطبيــق العقــد‬\n‫املتفــق عليــه واســتخراجه مــن املنــزل ولكــم جزيــل الشــكر ودمتــم اهــ‪.‬‬\n‫هــذه دعــواي وباســتجواب املدعــى عليــه أجــاب قائــا‪ :‬مــا ذكــره املدعــي‬\n‫يف دعــواه مــن املبايعــة وتفاصيلهــا فكلــه صحيــح إال أنــه متــت املبايعــة‬\n‫بينــي وبينــه بتاريــخ ‪2011/02/01‬م وقــد وعدنــي البائــع حينهــا بــأن‬\n‫الصــك ســيخرج خــال شــهرين ثــم تفاجــأت بأنــه جلــس ســنتني ونتيجــة‬\n‫لذلــك ملــا طلــب منــي املبلــغ لــم يكــن حينهــا موجــودا لــدي وأنــا راغــب‬\n‫بالبيــت وليســت لــدي رغبــة يف الفســخ وأنــا مســتعد بدفــع املبلــغ املتبقــي‬\n‫وهــو خمســمائة وخمســة وثمانــون ألــف ريــال ألننــي ســبق وأن أعطيتــه‬\n‫مبلــغ خمســة عشــر ألــف ريــال زيــادة علــى الدفعــة األولــى التــي ذكرهــا‬\n‫يف دعــواه والتــي هــي ثمامنائــة ألــف ريــال هكــذا أجــاب وبعــرض ذلــك‬\n‫علــى املدعــي أجــاب قائــا‪ :‬تاريــخ املبايعــة وكــذا املبلــغ املتبقــي كلهــا‬\n‫صحيحــة ولكنــي لــم أعــده بإخــراج الصــك يف وقــت قريــب وصحيــح أنه‬\n‫تأخــر اســتخراج الصــك قرابــة الســنتني إال أنــه ملــا خــرج تأخر يف الســداد‬\n‫والتأخيــر لــم يكــن منــي وإمنــا مــن الشــركة التــي أعمــل بهــا هكــذا‬\n‫أجــاب ثــم ســألت املدعــي عــن أصــل الصــك فأبــرز أصلــه فوجدتــه‬\n‫يحمــل الرقــم ‪ 832401000292‬وتاريــخ ‪1433/10/09‬ه ـ وتفاصيــل‬\n‫حــدوده وأطوالــه كالتالــي‪ :‬يقــع يف ‪............‬يف حــي ‪............‬ويحــده‬\n‫شــماال منطقــة للخدمــات واملرافــق العامــة وجنوبــا شــارع ‪............‬بعــرض‬\n\n\n                                                                                           ‫‪154‬‬\n\f      ‫(‪ )18,60‬متــر وشــرقا قطعــة رقــم (‪ )11‬وغربــا قطعــة رقــم (‪ )9‬مبســاحة‬\n      ‫إجماليــة قدرهــا (‪ )560‬خمســمائة وســتون متــرا مربعــا ووجدتــه صــادرا‬\n      ‫مــن كتابــة عــدل اجلبيــل فقــررت االستفســار عــن ســجله وهــل هــو صالــح‬\n      ‫لالعتمــاد عليــه عنــد اإلفــراغ كمــا قــرر املدعــي واملدعــى عليــه بأنــه‬\n      ‫ليــس لديهمــا ســوى مــا قدمــاه مــن دعــوى وإجابــة فجــرى إغــاق بــاب‬\n      ‫املرافعــة ‪،‬ويف يــوم الثالثاء‪1434/03/03‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10.30‬وفيهــا حضــر املدعــي واملدعــى عليــه وقــد وردنــي اجلــواب مــن‬\n      ‫كتابــة عــدل اجلبيــل برقــم ‪ 3451340‬وتأريــخ ‪1434/02/11‬ه ـ مفــاده‬\n      ‫أن الصـ ّـك املذكــور ســاري املفعــول وصالــح لالعتمــاد عليــه عند اإلفراغ‬     ‫ّ‬\n      ‫املدعــي عــن العقــد املبــرم بينهمــا فأبــرز أصلــه وجــرى‬\n                                                                  ‫اه ـ ‪ .‬ثــم ســألت ّ‬\n      ‫إرفــاق صــورة منــه باملعاملــة وباالطــاع عليــه وجدتــه صــادرا مــن مكتــب‬\n      ‫‪............‬العقــاري برقــم ‪ 309‬وتأريــخ ‪2011/02/01‬م ومحــدد بــه العقــار‬\n      ‫املذكــور حســب األوصــاف املثبتــة يف دعــوى املدعــي ووجــدت فيــه مــا‬\n      ‫نصــه ‪ »:‬كيفيــة دفــع القيمــة‪ :‬ثمامنائــة ألــف ريــال مقــدم والباقــي عنــد‬\n                                                                                    ‫ُّ‬\n      ‫نصــه‪»:‬‬‫اإلفــراغ» ‪ .‬كمــا ذكــر فيــه أربعــة شــروط للمبايعــة ومنهــا مــا ُّ‬\n      ‫‪ -1‬علــى املشــتري أن يقــوم بدفــع باقــي الثمــن وقــدره ســتمائة ألــف ريــال‬\n      ‫عنــد اإلفــراغ حــن اإلقــرار للمشــتري لــدى كاتــب العــدل‪ »...‬كمــا‬\n      ‫نصــه ‪ -1 »:‬علــى البائــع املتابعــة‬‫أ ّنــه جــاء يف الشــروط اإلضافيــة مــا ُّ‬\n      ‫إلفــراغ الصــك‪ »...‬كمــا أضــاف املدعــى عليــه قائــا‪ :‬إن املبلــغ جاهــز‬\n      ‫ومســتعد بتحريــره بشــيك مصــدق هكــذا أضــاف فبنــاء علــى مــا تقـ ّـدم‬\n      ‫الدعــوى واإلجابــة ولكــون العقــد بــن الطرفــن عقــد مبايعــة وهــو‬   ‫مــن ّ‬\n      ‫مــن العقــود الالزمــة والتــي ال تنفســخ إال برضــا مــن الطرفــن‪ ،‬ولكــون‬\n      ‫مــا أبــداه املدعــي مــن طلــب تطبيــق العقــد ويعنــي بذلــك الشــرط الثانــي‬\n\n\n‫‪155‬‬\n\f‫التأخــر يف دفــع باقــي الثمــن غيــر وجيــه‬\n                                          ‫ُّ‬      ‫منــه ومفــاده فســخ العقــد حــال‬\n‫أن باقــي الثمــن يدفــع عنــد اإلفــراغ‪ ،‬كمــا‬    ‫ـص علــى ّ‬ ‫ألن العقــد نـ ّ‬\n                                                                            ‫وذلــك ّ‬\n‫أن البائــع وهــو املدعــي هــو املســؤول عــن حتريــر الصــك‪ ،‬وقــد‬     ‫ـص علــى ّ‬  ‫نـ ّ‬\n‫أن‬\n ‫تأخــر إخراجــه بســبب خــارج عنــه‪ ،‬كمــا ّ‬        ‫ـأن الصــك ّ‬   ‫املدعــي بـ ّ‬\n                                                                              ‫أقـ ّـر ّ‬\n‫الوقــت لإلفــراغ لــم يحـ ّـدده البائــع يف العقــد بزمــن ُيعــرف مــن خاللــه‬\n‫املدعــى عليــه» املشــتري» راغــب بالعقــار‬ ‫أن ّ‬   ‫تأخــر املشــتري عنــه‪ ،‬ومبــا ّ‬\n                                                                                  ‫ُّ‬\n‫ـتعد بدفــع املبلــغ املتبقي يف ذمتــه‪ ،‬وتأخره يف دفع املتبقي‬    ‫املذكــور ومسـ ٌّ‬\n‫مــن الثمــن يقابــل تأخــر املدعــي « البائــع» يف حتريــر الصــك‪ ،‬هــذا وقــد‬\n‫الصحــة مــا أمكــن‪،‬‬\n                   ‫ّ‬     ‫أن األصــل حمــل العقــود علــى‬   ‫ـص أهــل العلــم علــى ّ‬   ‫نـ ّ‬\n‫ـص أو داللــة‪ ،‬ألجــل ذلــك‬‫يقيــد بنـ ٍّ‬\n                                     ‫وأن املطلــق يبقــى علــى إطالقــه مــا لــم َّ‬   ‫ّ‬\n‫املدعــي فســخ العقــد‬\n                     ‫كلــه وجلميــع مــا ســبق فقــد حكمــت بــر ّد دعــوى ّ‬\n‫املدعــى‬\n      ‫أن علــى ّ‬ ‫للمدعــى عليــه كمــا ّ‬ ‫وأن عليــه املضــي فيــه واإلفــراغ ّ‬           ‫ّ‬\n‫عليــه دفــع باقــي الثمــن حــاال عنــد طلــب املدعــي وعــدم املماطلــة وبعــرض‬\n‫املدعــي قــرر عــدم القناعــة فجــرى تســليمه صــورة مــن صــك‬        ‫ذلــك علــى ّ‬\n‫احلكــم يف مجلــس احلكــم وجــرى إفهامــه بــأن عليــه تقــدمي اعتراضــه‬\n‫خــال ثالثــن يومــا وإذا انتهــت املــدة ولــم يقــدم اعتراضــه فــإن حقــه‬\n‫يف االعتــراض يســقط ويكتســب احلكــم القطعيــة وكان ختــام هــذه‬\n‫اجللســة الســاعة احلاديــة عشــرة والربــع‪ . .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/03‬هـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n‫أمــا بعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى يف‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة مبحافظــة اجلبيــل برقــم‬\n\n\n                                                                                             ‫‪156‬‬\n\f      ‫‪ 34639104‬وتاريــخ ‪1434/3/14‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34715510‬وتاريــخ ‪1434/3/22‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة الشــيخ (‪ )....‬املســجل برقــم ‪ 3455007‬وتاريــخ ‪1434/3/3‬ه ـ‬\n      ‫اخلــاص بدعــوى(‪ )....‬ضــد(‪ )....‬يف قضيــة حقوقيــة وقــد تضمــن الصــك‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n      ‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة علــى‬\n          ‫احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/4/28‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪157‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":151,"source_page_end":157,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"11e313dc67bc54624dcca93c4564a09df165f456a357a2b9d6174b066ecc2b32","normalized_text_hash":"98c2c111d5dbdba9fe96f4ead12c50d295a206c0f01fb69e86b90f393146ec0b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p151-3455007"},{"id":"31768b7a-3749-545a-a554-24b5f4b1b495","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -رأس تريلة -استرداد حيازة سيارة ال يجوز متلكها لغير السعوديني -إثبات قبض الثمن لشهادة الشهود العدول -احلكم باسترداد ثمن املبيع بد ال عن السيارة المتناع متلكه نظام ا .","document_number":"34243235","case_number":"34129773","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/17","year":"1434","subject":"بيع -رأس تريلة -استرداد حيازة سيارة ال يجوز متلكها لغير السعوديني -إثبات قبض الثمن لشهادة الشهود العدول -احلكم باسترداد ثمن املبيع بد ال عن السيارة المتناع متلكه نظام ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34243235 :‬‬\n                   ‫َر ْق ُم الدعوى‪34129773 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34339830‬تاريخه‪1434/10/25 :‬هـ‬\n\n\n‫بيــع ‪ -‬رأس تريلــة ‪ -‬اســترداد حيــازة ســيارة ال يجــوز متلكهــا لغيــر‬\n‫الســعوديني ‪ -‬إثبــات قبــض الثمــن لشــهادة الشــهود العــدول ‪ -‬احلكــم‬\n   ‫باســترداد ثمــن املبيــع بــد ًال عــن الســيارة المتنــاع متلكــه نظام ـ ًا ‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )3‬مــن املــادة (‪ )9‬مــن نظــام املــرور ‪ ،‬ونصهــا ‪( :‬يجــوز لغيــر‬\n‫الســعوديني امتــاك املركبــات اخلصوصــي ‪ -‬ال تزيــد عــن مركبتــن ‪-‬‬\n‫ا علــى رخصــة قيــادة ســارية املفعــول)‪.‬‬\n                                         ‫شــريطة أن يكــون املشــتري حاصـ ً‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى مــن املدعــى عليــه شــاحنة (رأس تريلــة)‬\n‫ثــم اســتلمها منــه وســلمه ثمنهــا وبعــد أن اســتخدمها ملــدة ســتة أشــهر‬\n‫قــام املدعــى عليــه بأخــذ الشــاحنة املذكــورة مــن مقــر الســكن الــذي‬\n‫يســكن بــه املدعــي عــن طريــق مفتــاح آخــر كان معــه‪ ،‬طلــب املدعــي‬\n‫إلــزام املدعــى عليــه بإعــادة الســيارة املذكــورة إليــه أو قيمتهــا التــي‬\n‫ســلمها لــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف الدعــوى جملــة وتفصيــا‬\n‫‪ -‬طلبــت احملكمــة مــن املدعــي أن يقــدم بينتــه فأحضــر أربعــة شــهود‬\n‫شــهدوا مبــا يثبــت دعــوى املدعــي وجــرى تعديلهمــا التعديــل الشــرعي‬\n\n\n                                                                                     ‫‪158‬‬\n\f      ‫‪ -‬املركبــة محــل البيــع (رأس تريلــة) وليســت مــن قبيــل املركبــات‬\n      ‫اخلصوصــي التــي يجــوز نظام ـ ًا لغيــر الســعوديني امتالكهــا ‪ -‬قضــت‬\n      ‫احملكمــة بإلــزام املدعــى عليــه بإعــادة مبلــغ الشــراء للمدعــي حــا ًال ‪-‬‬\n      ‫قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة‬\n                                               ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬  ‫بنجــران وبنـ ً‬\n      ‫العامــة بنجــران برقــم ‪ 34129773‬وتاريــخ ‪1434/03/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34687233‬وتاريــخ ‪1434/03/18‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافق‪1434/03/25‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر (‪ )........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫(‪ )........‬كمــا حضــر املدعــى عليــه (‪ )........‬اجلنســية مبوجــب رخصــة‬\n      ‫ا إن لــي بذمــة هــذا احلاضــر‬‫اإلقامــة رقــم (‪ )........‬ثــم أدعــى املدعــي قائـ ً‬\n      ‫مبلغـ ًا وقــدره مائــة وتســعة وســتون ألــف وخمســمائة ريــال ســعودي قيمــة‬\n      ‫ســيارة مــن نــوع (‪ )........‬رأس تريلــه موديــل ‪1990‬م حيــث اشــتريتها منــه‬\n      ‫مببلــغ وقــدره مائــة وســبعون ألــف ريــال ســعودي قبــل مــا يقــارب ســتة‬\n      ‫أشــهر ســلمته عنــد البيــع مائــة ألــف ريــال ثــم ســلمته بعــد ذلــك تســعة‬\n      ‫وســتون ألــف وخمســمائة ريــال وقــد اســتلمت الســيارة منــه عنــد البيــع‬\n      ‫واســتخدمتها ملــدة ســتة أشــهر ثــم بعــد ذلــك قــام املدعــى عليــه بأخــذ‬\n      ‫الســيارة املذكــورة مــن مقــر الســكن الــذي أســكن بــه حيــث كان‬\n      ‫معــه مفتــاح آخــر أطلــب إلزامــه بإعــادة الســيارة املذكــورة إلـ ّـي أو‬\n\n‫‪159‬‬\n\f‫قيمتهــا التــي ســلمته إياهــا هكــذا ادعــى وبعــرض ذلــك علــى املدعــى‬\n‫ا ال صحــة ملــا جــاء يف دعــوى املدعــي فلــم أبعــه الســيارة‬  ‫عليــه أجــاب قائـ ً‬\n‫املذكــورة يف دعــواه ولــم أســتلم منــه املبلــغ املذكــور واملدعــي بينــي‬\n‫وبينــه دعــاوى يف احملاكــم الباكســتانية بخصــوص شــراكة بينــي‬\n‫ا أطلــب‬  ‫وبينــه هكــذا أجــاب وبســؤال املدعــي عــن بينتــه أجــاب قائ ـ ً‬\n‫إمهالــي إلــى اجللســة القادمــة ثــم يف جلســة أخــرى حضــر الطرفــان‬\n‫وبســؤال املدعــي عــن بينتــه التــي وعــد بإحضارهــا يف اجللســة املاضيــة‬\n‫ال مــن (‪ )........‬باكســتاني اجلنســية‬ ‫ا أحضــرت للشــهادة ك ً‬         ‫أجــاب قائـ ً‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬و(‪ )........‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة االقامــة رقــم (‪ )........‬و(‪ )........‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة االقامــة رقــم (‪ )........‬و(‪ )........‬باكســتاني اجلنســية‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬وبســؤال الشــاهد األول عمــا لديــه‬\n‫ا «أشــهد هلل تعالــى أن املدعــى عليــه قــد أعلمنــي‬    ‫مــن شــهادة أجــاب قائـ ً‬\n‫أن لديــه ســيارة وهــي املذكــورة بدعــوى املدعــي وقــد طلــب منــي البحــث‬\n‫لــه عمــن يشــتريها فأعلمــت املدعــي بذلــك فاســتعد بشــرائها وقــد‬\n‫اشــتراها مــن املدعــى عليــه مببلــغ وقــدره مائــة وســبعون ألــف ريــال وقــد‬\n‫ســلم املدعــي املدعــى عليــه مبلغ ـ ًا وقــدره تســعون ألــف ريــال بحضــوري‬\n‫وبعــد ســتة أشــهر ســلم املدعــي املدعــى عليــه مبلغـ ًا وقــدره أربعــون ألــف‬\n‫ريــال ثــم بعــد أســبوع تقريبـ ًا ســلمه كذلــك تســعة آالف وخمســمائة هــذا‬\n‫مــا لــدي مــن شــهادة» وبســؤال الشــاهد الثانــي (‪ )........‬عمــا لديــه مــن‬\n‫ا «أشــهد هلل تعالــى أن املدعــي ســلم املدعــى عليــه‬       ‫شــهاده أجــاب قائ ـ ً‬\n‫مبلغـ ًا وقــدره تســعة آالف وخمســمائة ريــال مــن قيمــة الســيارة املذكــورة‬\n‫بدعــواه هــذا مــا لــدي مــن شــهادة» وبســؤال الشــاهد الثالــث (‪ )........‬عمــا‬\n\n\n                                                                                         ‫‪160‬‬\n\f      ‫ا « أشــهد هلل تعالــى أن املدعــي ســلم املدعــى‬   ‫لديــه مــن شــهاده أجــاب قائـ ً‬\n      ‫عليــه مبلغ ـ ًا وقــدره عشــرون ألــف ريــال مــن قيمــة الســيارة املذكــورة‬\n      ‫بدعــواه هــذا مــا لــدي مــن شــهادة»‪ .‬وبســؤال الشــاهد الرابــع (‪ )........‬عمــا‬\n      ‫ا « أشــهد هلل تعالــى أن املدعــي اشــترى من‬     ‫لديــه مــن شــهاده فأجــاب قائـ ً‬\n      ‫املدعــى عليــه الســيارة املذكــورة بالدعــوى مببلــغ وقــدره مائــة وســبعون‬\n      ‫ألــف ريــال وقــد ســلم املدعــي املدعــى عليــه عشــرة آالف ريــال عربــون ثــم‬\n      ‫ســلمه بعــد ذلــك مبلغـ ًا وقــدره تســعون ألــف ريــال كدفعــة أولــى هــذا مــا‬\n      ‫ا‬\n      ‫لــدي مــن شــهادة»‪ .‬وبســؤال املدعــي هــل لديــك زيــادة بينــة فأجــاب قائـ ً‬\n      ‫نعــم لــدي شــاهد آخــر وهــو هــذا احلاضــر (‪ )........‬باكســتاني اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬وبســؤاله عمــا لديــه مــن شــهادة‬\n      ‫أجــاب قائ ـاً‪« :‬املدعــي أخــي وأشــهد هلل تعالــى أن املدعــي اشــترى‬\n      ‫مــن املدعــى عليــه الســيارة املذكــورة يف الدعــوى مببلــغ وقــدره مائــة‬\n      ‫وســبعون ألــف ريــال وســلمه منهــا مبلغـ ًا وقــدره مائــة وتســعة وســتون الــف‬\n      ‫ريــال وخمســمائة ريــال ســلمه منهــا عشــرة آالف ريــال عربــون ثــم ســلمه‬\n      ‫منهــا تســعون ألــف ريــال ثــم عشــرون ألــف ريــال ثــم أربعــون ألــف ريــال‬\n      ‫ثــم تســعة آالف وخمســمائة ريــال هــذا مــا لــدي مــن شــهادة»‪ .‬وقــد جــرى‬\n      ‫ال مــن (‪ )........‬باكســتاني اجلنســية مبوجــب‬    ‫تعديــل الشــهود مــن قبــل ك ً‬\n      ‫رخصــة اإلقامــة رقــم (‪ )........‬و (‪ )........‬باكســتاني اجلنســية مبوجــب‬\n      ‫رخصــة اإلقامــة رقــم (‪ )........‬حيــث شــهدا بعدالــة الشــهود وأنهــم مرضــي‬\n      ‫الشــهادة وبســؤال املدعــى عليــه عــن الشــهود ومــا جــاء يف شــهادتهم‬\n      ‫ا الشــهود جميعهــم مــن جماعــة املدعــي ومــن قريــة واحــدة‬      ‫فأجــاب قائـ ً‬\n      ‫ومــا جــاء يف شــهادتهم فغيــر صحيــح هكــذا أجــاب ثــم يف جلســة أخــرى‬\n      ‫حضــر الطرفــان وأبــرز املدعــى عليــه تأشــيرة خــروج وعــودة وتذاكــر‬\n\n\n‫‪161‬‬\n\f‫ا هــذه التأشــيرة والتذاكــر تثبــت أننــي كنــت خــارج‬         ‫ســفر وأجــاب قائـ ً‬\n‫اململكــة يف الوقــت الــذي يدعــي فيــه املدعــي أنــه باعنــي الســيارة‬\n‫املذكــورة بدعــواه هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب‬\n‫ا أنــا ال أتذكــر تاريــخ البيــع والشــراء بالضبــط ومــا ذكرتــه يف‬         ‫قائ ـ ً‬\n‫دعــواي هــو تاريــخ تقريبــي وقــد اشــتريت منــه الســيارة ثــم ســافر بعدهــا‬\n‫مباشــر ًة إلــى باكســتان حيــث تــويف أخــاه هنــاك هكــذا أجــاب كمــا‬\n‫أبــرز املدعــى عليــه ورقــة مترجمــة مــن مكتــب الشــرق األوســط للترجمة‬\n‫ونصهــا « تقريــر رقــم ‪ 17‬بتاريــخ ‪2012/10/15‬م مبنطقة (‪ )........‬محطة‬\n‫(‪ )........‬رقــم ‪ 17‬الطلــب املقــدم إلــى (‪ )........‬يف الســاعة ‪ 1740‬بتاريــخ‬\n‫‪2012/10/15‬م مت تقــدمي الطلــب املكتــوب مــن قبــل املدعــو (‪)........‬‬\n‫ا‬\n‫املقيــم يف (‪ )........‬إلــى مديــر محطــة الشــرطة يف مديريــة (‪ )........‬قائ ـ ً‬\n‫أنــه كان التعامــل ملذكــور مــع (‪ )........‬و(‪ )........‬أبنــاء (‪ )........‬مبديريــة‬\n‫(‪ )........‬يف جتــارة النقــل وجلــس جلنــة التحكيــم القبائلــي بعــدة مــرات‬\n‫وحلــل هــذه القضيــة تعــن جلــوس اجلركــة يف غرفــة أذان (‪ )........‬لتســوية‬\n‫مســتحقاتي مببلــغ ‪ 45000،0‬علــى ذمــة (‪ )........‬ولــم يتمكــن احلــل ألن‬\n‫املذكــور رفــض وخــرج مــن جلســة جلنــة التحكيــم القبائلــي وحددنــي‬\n‫للنظــر علــي فيمــا بعــد علمـ ًا بــأن األمــر يتعلــق مبديريــة مــردان لــذا قمــت‬\n‫بتقــدمي الطلــب إلــى محطــة ســعادتكم للنظــر إلــى معاملتــي واتخــاذ‬\n‫اإلجــراءات القانونيــة ضــد املذكــور إلعطــاء مســتحقاتي عليــه ختــم‬\n‫اســتالم الطلــب مــن محطــة الشــرطة يف مديريــة مــردان «أ‪-‬ه ـ وبســؤاله‬\n‫ا هــذه الورقــة تثبــت أن بينــي وبــن‬   ‫عــن وجــه الشــاهد منهــا فأجــاب قائـ ً‬\n‫املدعــي دعــاوى يف باكســتان وحســابات ماليــة وهــذه الدعــوى املرفوعــة‬\n‫يف اململكــة مــن قبــل املدعــي هــي دعــوى كيديــة ويقصــد مــن وراءهــا‬\n\n\n                                                                                         ‫‪162‬‬\n\f      ‫إحلــاق األذى بــي هكــذا أجــاب وبســؤال الطرفــن هل لــدى أحد منكما‬\n      ‫ا ليــس لــدي ســوى‬   ‫مــا يريــد إضافتــه فأجــاب كل واحــد منهمــا قائ ـ ً‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى وإنــكار املدعــى عليــه مــا‬\n                                                                      ‫مــا قدمــت فبنـ ً‬\n      ‫جــاء فيهــا وملــا جــاء بشــهادة الشــهود املعدلــن التعديــل الشــرعي وألن‬\n      ‫مــا دفــع بــه املدعــى عليــه مــن عــدم وجــوده يف التاريــخ احملــدد املذكــور‬\n      ‫مــن قبــل املدعــي للبيــع يســقطه شــهادة الشــهود الذيــن شــهدوا بصحــة‬\n      ‫البيــع وألن املدعــي ذكــر أن هــذا التاريــخ تقريبــي وليــس قطعــي كمــا‬\n      ‫أن مــا دفــع بــه املدعــى عليــه مــن وجــود دعــاوى بينــه وبــن املدعــي يف‬\n      ‫باكســتان ال متنــع مــن ســماع هــذه الدعــوى الســتقاللها عــن الدعــاوى‬\n      ‫التــي يف باكســتان وألن الســيارة محــل البيــع رأس تريلــة ليســت مــن‬\n      ‫قبيــل املركبــات اخلصوصــي وملــا نصــت عليــه الفقــرة (‪ )3‬مــن املــادة (‪)9‬‬\n      ‫مــن نظــام املــرور ونصهــا «يجــوز لغيــر الســعوديني امتــاك املركبــات‬\n      ‫اخلصوصــي ‪ -‬ال تزيــد عــن مركبتــن ‪ -‬شــريطة ان يكــون املشــتري‬\n      ‫ا عــن رخصــة قيــادة ســارية املفعــول ‪ »...‬الــخ لذلــك كلــه فقــد ثبت‬ ‫حاصـ ً‬\n      ‫لــدي تســليم املدعــي للمدعــى عليــه مبلغ ـ ًا وقــدره مائــة وتســعة وســتون‬\n      ‫ألــف وخمســمائة ريــال قيمــة رأس تريلــة وحكمــت بإلــزام املدعــى‬\n      ‫عليــه بإعــادة مبلــغ الشــراء وقــدره مائــة وتســعة وســتون ألــف وخمســمائة‬\n      ‫ريــال للمدعــي حــا ًال وبعــرض ذلــك علــى الطرفــن قــرر املدعــي قناعتــه‬\n      ‫باحلكــم كمــا قــرر املدعــى عليــه اعتراضــه علــى احلكــم بالئحــة‬\n      ‫فأفهــم بــأن عليــه تقــدمي الئحتــه االعتراضيــة خــال مــدة قدرهــا ثالثــون‬\n      ‫يوم ـ ًا مــن تاريــخ اســتالمه نســخة مــن احلكــم ففهــم ذلــك وعليــه فقــد‬\n      ‫رفعــت اجللســة الســاعة احلاديــة عشــرة وبــاهلل التوفيــق وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/6/5‬ه ـ ‪.‬‬\n\n\n‫‪163‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبوجــب اخلطــاب رقــم ‪ 342300310‬وتاريــخ ‪1434/11/6‬ه ـ ومرفــق بــه‬\n‫قــرار التصديــق رقــم ‪ 34339830‬وتاريــخ ‪1434/10/25‬ه ـ ونص احلاجة‬\n‫منــه» وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫وآلــه وصحبــه وســلم قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه قاضــي‬\n‫اســتئناف ‪ ......‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه»‬\n‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                 ‫حــرر يف ‪1434/11/20‬هــ‪.‬‬\n\n\n\n\n                                                                                  ‫‪164‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":158,"source_page_end":164,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"93ddd0c0a1f7cd12b29e34190939ade3eb06b172d147b33b66b08c9cbaf9ef51","normalized_text_hash":"b145286b7945d5a6e756f22799ca17d0fc5691e9cc2dcb793979c69a6f2b3ac0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p158-34243235"},{"id":"9f22c9dc-1d87-5797-91a5-168b175c3fd0","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -باقي ثمن مبيع بالتقسيط -اإلقرار ببيع االعيان قبل دخولها يف ضمانه -التمكن من القبض ينزل منزلة القبض يف الضمان ال يف حل الربح -األعيان املنقولة ال يتحقق قبضها إال بنقلها -احلكم برأس املال فقط للمدعي؛ للنهي عن ربح ما لم","document_number":"34200144","case_number":"34136760","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/28","year":"1434","subject":"بيع -باقي ثمن مبيع بالتقسيط -اإلقرار ببيع االعيان قبل دخولها يف ضمانه -التمكن من القبض ينزل منزلة القبض يف الضمان ال يف حل الربح -األعيان املنقولة ال يتحقق قبضها إال بنقلها -احلكم برأس املال فقط للمدعي؛ للنهي عن ربح ما لم","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/28 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34200144 :‬‬\n                         ‫َر ْق ُم الدعوى‪34136760 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34269056‬تاريخه‪1434/7/16 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬باقــي ثمــن مبيــع بالتقســيط ‪ -‬اإلقــرار ببيــع االعيــان قبــل‬\n      ‫دخولهــا يف ضمانــه ‪ -‬التمكــن مــن القبــض ينــزل منزلــة القبــض يف‬\n      ‫الضمــان ال يف حــل الربــح ‪ -‬األعيــان املنقولــة ال يتحقــق قبضهــا إال‬\n      ‫بنقلهــا ‪ -‬احلكــم بــرأس املــال فقــط للمدعــي؛ للنهــي عــن ربــح مــا لــم‬\n                                                                          ‫يضمــن ‪.‬‬\n\n\n\n                     ‫‪ .1‬نهى النبي صلى اهلل عليه وسلم عن ربح مالم يضمن ‪.‬‬\n      ‫‪ .2‬حديــث ابــن عمــر رضــي اهلل عنهمــا‪ :‬وقــد رأيــت النــاس يف عهــد رســول‬\n      ‫اهلل صلــى اهلل عليــه وســلم إذا ابتاعــوا الطعــام جزافــا يضربــون قبــل أن‬\n      ‫يبيعــوه يف مكانهــم وذلــك حتــى يــؤوه إلــى رحالهــم‪ .‬أخرجــه البخــاري‪.‬‬\n      ‫‪ .3‬حديــث ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم نهــى أن يبيــع الرجــل طعامــا حتــى يســتوفيه قيــل البــن عبــاس‬\n      ‫كيــف ذاك قــال ذاك دراهــم بدراهــم والطعــام مرجــأ‪ .‬أخرجــه البخاري‪،‬‬\n      ‫ويف روايــة عنــه قــال‪ :‬قــال رســول اهلل صلــى اهلل عليــه وســلم‪« :‬مــن ابتــاع‬\n      ‫طعامــا فــا يبيعــه حتــى يقبضــه» قــال ابــن عبــاس‪ :‬وأحســب كل شــيء‬\n                                                 ‫مبنزلــة الطعــام‪ .‬أخرجــه مســلم‪.‬‬\n      ‫‪ .4‬حديــث زيــد بــن ثابــت‪« :‬نهــى رســول اهلل صلــى اهلل عليــه وســلم أن‬\n      ‫تبــاع الســلع حيــث تبتــاع حتــى يحوزهــا التجــار إلــى رحالهــم» أخرجــه‬\n                                                ‫أحمــد وأبــو داوود‪ ،‬وإســناده جيــد‪.‬‬\n\n‫‪165‬‬\n\f‫‪ .5‬مــا جــاء عــن أبــي هريــرة وزيــد بــن ثابــت رضــي اهلل عنهمــا أنهمــا أنكــرا‬\n‫علــى مــروان بــن احلكــم فقــاال‪ :‬أحتــل بيــع الربــا يــا مــروان! قــال‪ :‬أعــوذ‬\n‫بــاهلل ومــا ذاك فقــاال هــذه الصكــوك تبايعهــا النــاس ثــم باعوهــا قبــل‬\n‫أن يســتوفوها فبعــث مــروان احلــرس يتبعونهــا فينزعوهــا مــن أيــدي‬\n                                      ‫النــاس ويردونهــا إلــى أهلهــا‪ .‬رواه مســلم‪.‬‬\n‫‪ .6‬جــاء يف شــرح الزركشــي ( وبيــع املســلم فيــه مــن بائعــه أو غيــره قبــل‬\n‫قبضــه فاســد واملعتمــد علــى نهــي النبــي صلــى اهلل عليــه وســلم عــن بيــع‬\n                                ‫الطعــام قبــل قبضــه وعــن ربــح مالــم يضمــن )‪.‬‬\n‫‪ .7‬قــال اخلرقــي مــن احلنابلــة إن الصبــرة املتعينــة املبيعــة جزافــا تدخل‬\n‫يف ضمــان املشــتري بالعقــد وال يجــوز للمشــتري بيعهــا حتــى ينقلهــا‪.‬‬\n                       ‫(مجمــوع فتــاوي شــيخ اإلســام ابــن تيميــة ‪)400/29‬‬\n‫‪ .8‬قــال شــيخ االســام ابــن تيميــة رحمــه اهلل ( ومــن جعــل التصــرف‬\n‫تابعــا للضمــان فقــد غلــط فقــد ثبــت يف الصحيــح عــن ابــن عمــر رضــي‬\n‫اهلل عنهمــا أنــه قــال كنــا نبتــاع الطعــام جزافــا علــى عهــد رســول اهلل‬\n‫صلــى اهلل عليــه وســلم فنهــى أن نبيعــه حتــى ننقلــه إلــى رحالنــا وابــن‬\n‫عمــر هــو القائــل مضــت الســنة أن مــا أدركــت الصفقــة حيــا مجموعــا‬\n‫فهــو مــن ضمــان املشــتري فتبــن أن مثــل هــذا الطعــام مضمــون علــى‬\n‫املشــتري وال يبيعــه حتــى ينقلــه فالســنة يف هــذا البــاب فرقــت بــن‬\n‫القــادر علــى القبــض وغيــر القــادر يف الضمــان والتصــرف ) مجمــوع‬\n                                                                ‫الفتــاوي ‪.344/20‬‬\n‫‪ .9‬وقــال رحمــه اهلل‪ ( :‬إن النهــي إمنــا كان للتاجــر الــذي يربــح فــا‬\n‫يبيــع بربــح حتــى يصيــر يف حوزتــه ويعمــل فيهــا عمــا مــن أعمــال‬\n‫التجــارة إمــا بنقلهــا إلــى مــكان آخــر كالــذي يشــتري يف بلــد ويبيــع يف‬\n                                ‫آخــر وإمــا حبســها إلــى وقــت آخــر ‪ ...‬إلــخ ) ‪.‬‬\n                                                                                         ‫‪166‬‬\n\f      ‫ادعــى املدعــي أنــه بــاع للمدعــى عليــه عشــر مكيفــات‪ ،‬بالعقــد الصــادر‬\n      ‫من شــركة‪ ...‬للتقســيط‪ ،‬بقيمة إجمالية قدرها ثمانية عشــر ألف ريال‬\n      ‫مقســطة علــى أقســاط شــهرية قــدر كل قســط ألــف ريــال‪ ،‬ســدد منهــا‬\n      ‫املدعــى عليــه ســبعة آالف ريــال‪ ،‬وبقــي أحــد عشــر ألــف ريــال حالــة‪،‬‬\n      ‫وطلــب احلكــم علــى املدعــى عليــه بدفــع أحــد عشــر ألــف ريــال ‪ ،‬بعــرض‬\n      ‫دعــوى املدعــي علــى املدعــى عليــه صــادق عليهــا ‪ ،‬جــرى ســؤال املدعــي‬\n      ‫هــل آلــت إليــه األعيــان املباعــة بالشــراء مــن شــركة ‪ ...‬للتقســيط؟ وهــل‬\n      ‫قــام بنقــل األعيــان بعــد شــرائها؟ فأجــاب بأنــه اشــترى األعيــان املباعــة‬\n      ‫علــى املدعــى عليــه مــن شــركة ‪ ...‬للتقســيط بأحــد عشــر ألــف ريــال‬\n      ‫وباعهــا علــى املدعــى عليــه بثمانيــة عشــر ألــف ريــال‪ ،‬وأنــه لــم يقــم بنقلهــا‬\n      ‫مــن املعــرض وإمنــا قــام بتنحيتهــا يف أحــد جوانــب املعــرض ‪ ،‬جــرى ســؤال‬\n      ‫املدعــى عليــه هــل بــاع األعيــان علــى شــركة ‪ ...‬للتقســيط؟ فأجــاب أنــه‬\n      ‫باعهــا بعشــرة آالف ريــال ‪ ،‬املدعــي أقــر أنــه بــاع علــى املدعــى عليــه‬\n      ‫األعيــان املذكــورة قبــل دخولهــا يف ضمانــه وربــح علــى املدعــى عليــه‬\n      ‫ســبعة آالف ريــال ‪ ،‬نهــى النبــي صلــى اهلل عليــه وســلم عــن ربــح مالــم‬\n      ‫يضمن‪،‬التمكــن مــن القبــض ينــزل منزلــة القبــض يف الضمــان ال يف‬\n      ‫حــل الربــح ‪ ،‬واألعيــان املباعــة منقولــة‪ ،‬وال يتحقــق قبضهــا إال يف بيــع‬\n      ‫املدعــي للســلعة وهــي يف حيــازة بائعهــا األول وتــوارد املبايعــات عليهــا‬\n      ‫عشــرات املــرات يــؤدي إلــى قصــر تــداول الســلعة بــن التجــار للمضاربــة‬\n      ‫علــى فروقــات األســعار والســلعة ثابتــة علــى حالهــا‪ ،‬فهــذه التجارة ليســت‬\n      ‫منتجــة وال نافعــة للمجتمــع فالتجــارة كمــا تنفــع التاجــر بالربــح فإنــه‬\n\n‫‪167‬‬\n\f‫ينبغــي أن تكــون محققــة ملنافــع املجتمــع ‪ ،‬مت إفهــام املدعــي أنــه ال‬\n‫يســتحق يف ذمــة املدعــى عليــه إال رأس مالــه وقــدره أحــد عشــر ألــف‬\n‫ريــال‪ ،‬ومت احلكــم علــى املدعــى عليــه بدفــع أربعــة آالف ريــال للمدعي‪،‬‬\n‫بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر‬\n‫املدعــي عــدم قناعتــه ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                            ‫املصادقــة عليــه ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬مســاعد رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34136760‬وتاريــخ‬\n‫‪ 1434/03/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34725942‬وتاريــخ‬\n‫‪ 1434/03/23‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/04/08‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .............‬وادعــى علــى احلاضــر معــه ‪ ...........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬قائــا يف دعــواه عليــه‬\n‫بعــت املدعــى عليــه أجهــزة كهربائيــة عبــارة عــن عشــرة مكيفــات‬\n‫نــوع ‪ ......‬بالعقــد الصــادر مــن شــركة ‪ ............‬للتقســيط رقــم ‪16063‬‬\n‫يف ‪1432/2/22‬ه ـ بقيمــة إجماليــة قدرهــا ثمانيــة عشــر ألــف ريــال‬\n‫(‪ )18000‬مقســطة علــى أقســاط شــهرية قــدر كل قســط ألــف ريــال‬\n‫(‪ )1000‬اعتبــارا مــن ‪1432/3/25‬ه ـ ســدد منهــا ســبعة آالف ريــال‬\n‫(‪ )7000‬وتبقــى عليــه أحــد عشــر ألــف ريــال (‪ )11000‬وهــي حالــه‬\n‫أطلــب احلكــم عليــه بدفــع أحــد عشــر ألــف ريــال (‪ )11000‬هــذه دعــواي‬\n\n                                                                                        ‫‪168‬‬\n\f      ‫وبســؤال املدعــى عليــه قــال مــا ذكــره املدعــي مــن أننــي اشــتريت منــه‬\n      ‫أجهــزة كهربائيــة بالعقــد املذكــور أعــاه باملبلــغ اإلجمالــي واملقســط‬\n      ‫واملتبقــي وأنــه حــال صحيــح فســألت املدعــي هــل آلــت إليــك األعيــان‬\n      ‫املباعــة بالشــراء مــن شــركة ‪ ...........‬قــال نعــم اشــتريت األعيــان املباعــة‬\n      ‫علــى املدعــى عليــه مــن شــركة ‪ ...........‬بأحــد عشــر ألف ريــال (‪)11000‬‬\n      ‫وبعتهــا علــى املدعــى عليــه بثمانيــة عشــر ألــف ريــال (‪ )18000‬فســألته‬\n      ‫وهــل قمــت بنقــل األعيــان بعــد شــرائها فقــال لــم أقــم بنقلهــا مــن املعــرض‬\n      ‫وإمنــا قمــت بنتحيتهــا يف أحــد جوانــب املعــرض هكــذا أجــاب فســألت‬\n      ‫املدعــى عليــه وهــل بعــت االعيــان علــى شــركة ‪ ..........‬فقــال نعــم بعتهــا‬\n      ‫بعشــرة آالف ريــال (‪ )10000‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث أقــر املدعــي أنــه بــاع علــى املدعــى عليــه األعيــان املذكــورة قبــل‬\n      ‫دخولهــا يف ضمانــه وربــح علــى املدعــى عليــه ســبعة آالف ريــال (‪)7000‬‬\n      ‫وقــد نهــى النبــي صلــى اهلل عليــه وســلم عــن ربــح مالــم يضمــن جــاء يف‬\n      ‫شــرح الزركشــي ( وبيــع املســلم فيــه مــن بائعــه أو غيــره قبــل قبضــه‬\n      ‫فاســد واملعتمــد علــى نهــي النبــي صلــى اهلل عليــه وســلم عــن بيــع الطعــام‬\n      ‫قبــل قبضــه وعــن ربــح مالــم يضمــن ) لذلــك كلــه أفهمــت املدعــي أنــه ال‬\n      ‫يســتحق يف ذمــة املدعــى عليــه إال رأس مالــه وقــدره أحــد عشــر ألــف ريال‬\n      ‫(‪ )11000‬وعليــه فقــد حكمــت علــى املدعــى عليــه بدفــع أربعــة آالف‬\n      ‫ريــال (‪ )4000‬للمدعــي وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه قناعتــه باحلكــم كمــا قــرر املدعــي عــدم قناعتــه باحلكــم وطلــب‬\n      ‫محكمــة االســتئناف فأجبتــه لطلبــه وافهمتــه بــأن بــأن مــدة االعتــراض‬\n      ‫ثالثــون يومــا تبــدأ مــن ‪1434/ 4/ 20‬ه ـ وإذا انقضــت املــدة احملــددة قبــل‬\n      ‫تقــدمي الئحتــه االعتراضيــة فــإن حقــه يف طلــب االســتئناف يعتبــر ســاقطا‬\n\n\n‫‪169‬‬\n\f‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪ 1434/04/08‬ه ـ‬\n‫ويف يوم الثالثاء املوافق‪ 1434/07/04‬هـ افتتحت اجللســة الســاعة (‪15‬‬\n‫‪ )10 :‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫بالرقــم ‪ 34725942‬يف ‪1434/6/17‬ه ـ وبرفقهــا قــرار الدائــرة احلقوقيــة‬\n‫السادســة رقــم ‪ 34236572‬املتضمــن وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــرر إعادتهــا إلــى فضيلــة حاكمهــا لطلــب‬\n‫االفــادة مــن شــركة ‪ ...........‬هــل الســلعة املباعــة ســلمت للمدعــي بعــد‬\n‫اســتالمها لثمنهــا وقــام بحيازتهــا بجانــب املعــرض مــع إرفــاق صــورة‬\n‫مــن عقــد البيــع إن وجــد فــإذا اتضــح حيــازة املدعــي للمبيــع بعــد دفــع‬\n‫ثمنــه فالبيــع صحيــح والزيــادة يف الثمــن مقابــل التأجيــل صحيحــة فعلــى‬\n‫فضيلتــه مالحظــة ذلــك وبــاهلل التوفيــق واجلــواب عليــه املدعــي ذكــر‬\n‫انــه قــام بحيــازة األعيــان املباعــة بتمييزهــا يف إحــدى جوانــب املعــرض‬\n‫ولــم يقــم بنقلهــا منــه ولــذا فــا حاجــة إلــى طلــب إفــادة الشــركة بعــد‬\n‫إقــرار املدعــي أمــا قــول أصحــاب الفضيلــة أنــه اتضــح حيــازة املدعــي‬\n‫للمبيــع بعــد دفــع ثمنــه فالبيــع صحيــح والزيــادة يف الثمــن مقابــل التأجيــل‬\n‫صحيحــة فاجلــواب عليــه أنــا لــم أحكــم ببطــان البيــع واحلكــم صــدر‬\n‫باســتحقاق رأس املــال فقــط أمــا الزيــادة فهــي باطلــة ألن املشــتري وهــو‬\n‫املدعــي هنــا بــاع العــن بعــد متكنــه مــن القبــض وقبــل القبــض احلقيقــي‬\n‫املتمثــل يف نقــل العــن املباعــة يــدل علــى ذلــك حديــث ابــن عمــر رضــي‬\n‫اهلل عنهمــا وقــد رأيــت النــاس يف عهــد رســول اهلل صلــى اهلل عليــه وســلم‬\n‫إذا ابتاعــوا الطعــام جزافــا يضربــون يف أن يبيعــوه يف مكانهــم وذلــك‬\n‫حتــى يــؤوه إلــى رحالهــم ( أخرجــه البخــاري كتــاب البيــوع ) وحديــث‬\n\n\n                                                                                      ‫‪170‬‬\n\f      ‫ابــن عبــاس رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم نهــى‬\n      ‫أن يبيــع الرجــل طعامــا حتــى يســتوفيه قيــل البــن عبــاس كيــف ذاك قــال‬\n      ‫ذاك دراهــم بدراهــم والطعــام مرجــأ ( البخــاري ) ويف روايــة عنــه قــال‬\n      ‫قــال رســول اهلل صلــى اهلل عليــه وســلم مــن ابتــاع طعامــا فــا يبيعــه حتــى‬\n      ‫يقبضــه قــال ابــن عبــاس وأحســب كل شــيء مبنزلــة الطعــام ( مســلم‬\n      ‫كتــاب البيــوع ) وحديــث زيــد بــن ثابــت نهــى رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم أن تبــاع الســلع حيــث تبتــاع حتــى يحوزهــا التجــار إلــى رحالهــم‬\n      ‫( أحمــد وأبــو داوود واســناده جيــد ) فالبيــع صحيــح بتمكــن املدعــي‬\n      ‫مــن القبــض ولكــن ال يطيــب لــه الربــح حتــى يقبــض قبضــا حقيقيــا‬\n      ‫ويتحقــق القبــض يف مثــل هــذه االعيــان بنقلهــا قــال شــيخ االســام ابــن‬\n      ‫تيميــة رحمــه اهلل ( ومــن جعــل التصــرف تابعــا للضمــان فقــد غلــط فقــد‬\n      ‫ثبــت يف الصحيــح عــن ابــن عمــر رضــي اهلل عنهمــا أنــه قــال كنــا نبتــاع‬\n      ‫الطعــام جزافــا علــى عهــد رســول اهلل صلــى اهلل عليــه وســلم فنهــى أن‬\n      ‫نبيعــه حتــى ننقلــه إلــى رحالنــا وابــن عمــر هــو القائــل مضــت الســنة أن‬\n      ‫مــا أدركــت الصفقــة حيــا مجموعــا فهــو مــن ضمــان املشــتري فتبــن‬\n      ‫أن مثــل هــذا الطعــام مضمــون علــى املشــتري وال يبيعــه حتــى ينقلــه‬\n      ‫فالســنة يف هــذا البــاب فرقــت بــن القــادر علــى القبــض وغيــر القــادر يف‬\n      ‫الضمــان والتصــرف) مجمــوع الفتــاوي ‪ 344/20‬واخلرقــي مــن احلنابلــة‬\n      ‫رحمــه اهلل قــال ( إن الصبــرة املتعينــة املبيعــة جزافــا تدخــل يف ضمــان‬\n      ‫املشــتري بالعقــد وال يجــوز للمشــتري بيعهــا حتــى ينقلهــا) (مجمــوع‬\n      ‫الفتــاوي ‪ )400/29‬أ‪-‬ه ـ فالتمكــن مــن القبــض ينــزل منزلــة القبــض يف‬\n      ‫الضمــان ال يف حــل الربــح واالعيــان املباعــة منقولــة وال يتحقــق قبضهــا‬\n      ‫اال بنقلهــا وتــداول ســندات امللكيــة بــن املتبايعــن والســلعة علــى حالهــا‬\n\n\n‫‪171‬‬\n\f‫يف حيــازة بائعهــا األول هــو نظيــر مــا جــاء عــن أبــي هريــرة وزيــد بــن ثابــت‬\n‫رضــي اهلل عنهمــا أنهمــا أنكــرا علــى مــروان بــن احلكــم فقــاال أحتــل‬\n‫بيــع الربــا يــا مــروان قــال أعــوذ بــاهلل ومــا ذاك فقــاال هــذه الصكــوك‬\n‫تبايعهــا النــاس ثــم باعوهــا قبــل أن يســتوفوها فبعــث مــروان احلــرس‬\n‫يتبعونهــا فينزعوهــا مــن أيــدي النــاس ويردونهــا إلــى أهلهــا ( رواه مســلم‬\n‫كتــاب البيــوع ) ثــم أن بيــع املدعــي للســلعة وهــي يف حيــازة بائعهــا األول‬\n‫وتــوارد املبايعــات عليهــا عشــرات املــرات يــؤدي إلــى قصــر تــداول الســلعة‬\n‫بــن التجــار للمضاربــة علــى فروقــات األســعار والســلعة ثابتــة علــى حالهــا‬\n‫فهــذه التجــارة ليســت منتجــة وال نافعــة للمجتمــع فالتجــارة كمــا تنفــع‬\n‫التاجــر بالربــح فإنــه ينبغــي أن تكــون محققــة ملنافــع املجتمــع قــال شــيخ‬\n‫االســام ( إن النهــي إمنــا كان للتاجــر الــذي يربــح فــا يبيــع بربــح حتــى‬\n‫يصيــر يف حوزتــه ويعمــل فيهــا عمــا مــن أعمــال التجــارة إمــا بنقلهــا‬\n‫إلــى مــكان آخــر كالــذي يشــتري يف بلــد ويبيــع يف آخــر وإمــا حبســها‬\n‫إلــى وقــت آخــر ‪ ...‬إلــخ ) ثــم إن هــذه املبايعــات يشــم منهــا رائحــة الربــا‬\n‫فالصوريــة ظاهــرة يف هــذه املعاملــة فحقيقتهــا تــؤول إلــى كــون البائــع‬\n‫مقرضــا بفائــدة إلــى أجــل وبهــذا يتبــن أن قبــض املدعــي للعــن بعــد‬\n‫شــرائها لــم يكــن قبضــا كامــا يســتحق بــه الربــح ولــذا حكمــت لــه‬\n‫بــرأس املــال وعقــد البيــع مرفــق باملعاملــة لفــة (‪ )7‬قبــل ورود املالحظــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/04‬هــ‪.‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس واعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n\n\n                                                                                         ‫‪172‬‬\n\f      ‫الصــادر مــن فضيلــة الشــيخ ‪ ...........‬القاضــي باحملكمــة اجلزائيــة مبكة‬\n      ‫املكرمة واملسجل بع ــدد ‪ 34200144‬وتاريخ ‪1434/4/28‬هـ املتضمن‬\n      ‫دعوى ‪ ............‬ضد ‪ ، ..........‬احملكوم في ــه مبا دون باطنه ‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى‬\n      ‫احلكــم بعــد االجــراء األخيــر جوابـ ًا علــى قــرار الدائــرة رقــم ‪34236572‬‬\n      ‫وتاريــخ ‪1434/6/11‬ه ـ وعلــى فضيلتــه تدويــن تاريــخ قــرار الدائــرة يف‬\n      ‫الضبــط والصــك وســجله ‪ ،‬واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                        ‫وعل ــى آل ــه وصحب ــه وسلم ‪.‬‬\n\n\n\n\n‫‪173‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":165,"source_page_end":173,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a590d619852b8e29957812b037ecd67b8b17649a9c9e58eb3e1bed80fe17e28b","normalized_text_hash":"f9d17b68c58b8da14fd55174910dc287ce0ab900f06d1787024d01c9afd0ce2d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p165-34200144"}]$archive_payload$::jsonb) AS x LIMIT 25
